import {useCallback, useEffect, useMemo, useRef} from 'react'

import {maxLimitParamatersAmount} from './ParametersSidebar.consts'

const waitSliderAnimnationTime = 300

function useParametersSidebar(
  parameters: Record<string, string | undefined>,
  onAdd?: () => void,
  errorMessage?: string,
) {
  const lastNameInputRef = useRef<HTMLTextAreaElement>(null)
  const parametersKeys = useMemo(() => Object.keys(parameters), [parameters])
  const parametersLength = parametersKeys.length
  const hasParametersFormErrorMessage = !!errorMessage
  const isShowBottomAddButton = parametersLength > maxLimitParamatersAmount
  const clickAddParameterButtonHandler = useCallback(() => {
    onAdd?.()

    setTimeout(() => {
      const lastNameInput = lastNameInputRef.current
      const valueLength = lastNameInput?.value.length ?? 0

      lastNameInput?.focus()
      lastNameInput?.setSelectionRange(valueLength, valueLength)
    }, waitSliderAnimnationTime)
  }, [onAdd])

  useEffect(() => {
    if (!parametersLength) {
      clickAddParameterButtonHandler()
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  return {
    parametersKeys,
    lastNameInputRef,
    hasParametersFormErrorMessage,
    isShowBottomAddButton,
    clickAddParameterButtonHandler,
  }
}

export default useParametersSidebar
