import classNames from 'classnames'
import {memo, Suspense, useCallback, useEffect, useMemo, useRef} from 'react'

import {useAppSelector} from '../../../../../hooks/react-redux'
import {useBooleanQueryParam} from '../../../../../hooks/routes'
import {useIsStuck} from '../../../../../hooks/useIsStuck'
import {useBanners} from '../../contexts/Banners/BannersContext'
import {READONLY_MESSAGE, RELOAD_MESSAGE} from '../../contexts/Banners/BannersContext.types'
import {usePipelineId} from '../../hooks/pipeline'
import usePermissionCanEditPipeline from '../../hooks/usePermissionCanEditPipeline'
import Banners from '../../PipelineRunPage/PipelineTab/Banners/Banners'
import {AlertMessageType} from '../../types/AlertMessages'
import {useDebugJobActions} from '../EditPipelinePage.hooks'
import {getIsStoreInRepoEnabled} from '../EditPipelinePage.selectors'

import EditPipelineToggle from './EditPipelineToggle/EditPipelineToggle'
import EditPipelineYamlActions from './EditPipelineYamlActions/EditPipelineYamlActions'
import EditPipelineYamlCounters from './EditPipelineYamlCounters/EditPipelineYamlCounters'

import styles from './EditPipelineToolbar.module.css'

type Props = {
  className?: string
}

function EditPipelineToolbar({className}: Props) {
  const {canEditPipeline} = usePermissionCanEditPipeline()
  const id = usePipelineId()
  const isYaml = useBooleanQueryParam('yaml')
  const ref = useRef<HTMLDivElement>(null)
  const isStuck = useIsStuck(ref)
  const isCollisionApi = useAppSelector(state => state.pipelines.pipelineDraft[id]?.isCollisionApi)
  const {addBanner, removeBanner} = useBanners()
  const isStoreInRepoEnabled = useAppSelector(state =>
    getIsStoreInRepoEnabled(state, {pipelineId: id}),
  )
  const {onStopDebug} = useDebugJobActions()
  const reloadActions = useMemo(
    () => [
      {
        label: 'Reload',
        onClick: () => {
          onStopDebug()
          window.location.reload()
        },
      },
    ],
    [onStopDebug],
  )
  const bannerKey = `${id}-${RELOAD_MESSAGE}`
  const toggleWarningBanner = useCallback(
    (isShow: boolean) => {
      if (isShow) {
        addBanner(id, {
          key: bannerKey,
          message: 'This Pipeline was modified, reload the page to view updated settings',
          type: AlertMessageType.WARNING,
          actions: reloadActions,
        })
      } else if (!isCollisionApi) {
        removeBanner(id, bannerKey)
      }
    },
    [addBanner, bannerKey, id, isCollisionApi, reloadActions, removeBanner],
  )

  useEffect(() => {
    const isShowBanner = isCollisionApi === true && !isStoreInRepoEnabled

    toggleWarningBanner(isShowBanner)
  }, [isCollisionApi, isStoreInRepoEnabled, toggleWarningBanner])

  useEffect(() => {
    if (!canEditPipeline) {
      addBanner(id, {
        key: `${id}-${READONLY_MESSAGE}`,
        message:
          "You can edit some of this Pipeline's settings but can't save or run it with new changes. Copy the YAML to save your work, then contact a project admin.",
        type: AlertMessageType.INFO,
      })
    }
  }, [addBanner, canEditPipeline, id])

  return (
    <>
      <Banners />
      <div className={styles.psevdoPanel} ref={ref} />
      <div className={classNames(className, styles.panel, {[styles.stuck]: isStuck})}>
        <EditPipelineToggle />
        {isYaml && <EditPipelineYamlActions />}
        {isYaml && (
          <Suspense>
            <EditPipelineYamlCounters />
          </Suspense>
        )}
      </div>
    </>
  )
}

export default memo(EditPipelineToolbar)
