import {Size} from '@jetbrains/ring-ui-built/components/input/input'
import type {SelectItem} from '@jetbrains/ring-ui-built/components/select/select'
import Select from '@jetbrains/ring-ui-built/components/select/select'
import type {ControlProps, OwnPropsOfEnum, RankedTester} from '@jsonforms/core'
import {isEnumControl, rankWith} from '@jsonforms/core'
import type {TranslateProps} from '@jsonforms/react'
import {withJsonFormsEnumProps, withTranslateProps} from '@jsonforms/react'
import type {SyntheticEvent} from 'react'
import {memo, Fragment, useCallback, useMemo} from 'react'

import JsonFormHelpDetailsIcon from './JsonFormHelpDetailsIcon'

import styles from './styles.module.css'

type JsonFormEnumControlProps = {
  schema: {
    enumNames?: string[]
    enumDescription?: string[]
  }
} & ControlProps &
  OwnPropsOfEnum &
  TranslateProps

function JsonFormEnumControl({
  description,
  data,
  path,
  label,
  options,
  schema,
  handleChange,
  enabled,
  uischema,
}: JsonFormEnumControlProps) {
  const {hide} = uischema.options ?? {}
  const selectOptions = useMemo(() => {
    const enumNames = schema?.enumNames ?? []
    const enumDescription = schema?.enumDescription ?? []
    return options?.map(({value: key}, index) => ({
      key,
      label: enumNames[index],
      details: enumDescription[index],
    }))
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [options])
  const selectedOption = selectOptions?.find(({key}) => key === data)
  const selectedLabel = useMemo(
    () => (
      <Fragment>
        {label}
        {description && <JsonFormHelpDetailsIcon>{description}</JsonFormHelpDetailsIcon>}
      </Fragment>
    ),
    [description, label],
  )
  const selectHandler = useCallback(
    (selected: SelectItem | null, _?: Event | SyntheticEvent) => handleChange(path, selected?.key),
    [handleChange, path],
  )

  if (hide) {
    return null
  }

  return (
    <div className={styles.container}>
      <Select
        selectedLabel={selectedLabel}
        label={label}
        size={Size.FULL}
        data={selectOptions}
        selected={selectedOption}
        disabled={!enabled}
        onSelect={selectHandler}
      />
    </div>
  )
}

export const jsonFormEnumControlTester: RankedTester = rankWith(1, isEnumControl)

export default withJsonFormsEnumProps(withTranslateProps(memo(JsonFormEnumControl)), true)
