import Toggle from '@jetbrains/ring-ui-built/components/toggle/toggle'
import classNames from 'classnames'
import {memo} from 'react'

import Actions from '../../../../../components/Actions/Actions'

import type {PipelineTriggerProps} from './PipelineTrigger.types'

import styles from './PipelineTrigger.module.css'

function PipelineTrigger({
  label,
  details,
  onDisabled,
  onDelete,
  onEdit,
  disabled,
  errorMessage,
}: PipelineTriggerProps) {
  const triggerDetailsClassNames = classNames(styles.triggerDetail, {
    [styles.triggerDetailDisabled]: disabled,
  })

  return (
    <div className={styles.trigger}>
      <div className={styles.triggerLabel}>
        {label}
        <div className={triggerDetailsClassNames}>{details}</div>
      </div>
      <Toggle onChange={onDisabled} className={styles.triggerToggle} checked={!disabled} />
      <Actions className={styles.triggerActions} onDeleteClick={onDelete} onEditClick={onEdit} />
      {errorMessage && <div className={styles.errorMessage}>{errorMessage}</div>}
    </div>
  )
}

export default memo(PipelineTrigger)
