import type {ReactNode} from 'react'
import {useContext} from 'react'

import EditButton from '../../../../../components/EditButton/EditButton'
import SummaryDetailsCardWrapper from '../../../../../components/SummaryDetailsCardWrapper/SummaryDetailsCardWrapper'
import {DisabledContext} from '../../../../../contexts/DisabledContext'
import PipelineSecret from '../PipelineSecret/PipelineSecret'

import styles from './PipelineSecretsSettingsBlockSummaryDetails.module.css'

type PipelineSecretsSettingsBlockSummaryDetailsProps = {
  secretsKeys: string[]
  deleted?: string[]
  error?: ReactNode
  header?: ReactNode
  isBlockExpanded: boolean
  isShowMoreButton: boolean
  onEdit?: () => void
  onClickShowMore: () => void
  listItemLimit: number
}

function PipelineSecretsSettingsBlockSummaryDetails({
  secretsKeys,
  deleted,
  header,
  error,
  isBlockExpanded,
  isShowMoreButton,
  listItemLimit,
  onEdit,
  onClickShowMore,
}: PipelineSecretsSettingsBlockSummaryDetailsProps) {
  const isDisabled = useContext(DisabledContext)

  return (
    <SummaryDetailsCardWrapper
      actions={<EditButton title="Edit secrets" aria-label="Edit secrets" onClick={onEdit} />}
      error={error}
      header={header}
      expanded={isBlockExpanded}
      showMoreButton={isShowMoreButton}
      onClickShowMore={onClickShowMore}
    >
      <div className={styles.secretHeader}>
        <div className={styles.secretHeaderItem}>{'Name'}</div>
        <div className={styles.secretHeaderItem}>{'Value'}</div>
      </div>
      {secretsKeys.slice(0, listItemLimit).map(key => {
        const isDeleted = deleted?.includes(key)

        return (
          <PipelineSecret key={key} originalName={key} deleted={isDeleted} disabled={isDisabled} />
        )
      })}
    </SummaryDetailsCardWrapper>
  )
}

export default PipelineSecretsSettingsBlockSummaryDetails
