import type {ValidatorResult} from 'jsonschema'
import {ValidationError, Validator} from 'jsonschema'

const keyNoSpaceErrorMessage = 'Key should not contain spaces'

class JsonSchemaCustomValidator extends Validator {
  constructor() {
    super()
    this.customFormats.keyNoSpaces = (key: string) => !/\s/.test(key)
  }

  validate(instance: any, schema: any, options?: any, ctx?: any): ValidatorResult {
    const result = super.validate(instance, schema, options, ctx)
    const jobs = instance?.jobs

    if (jobs != null) {
      Object.keys(jobs).forEach(key => {
        const isNoSpaceValide = this.customFormats.keyNoSpaces(key)

        if (!isNoSpaceValide) {
          const keyNoSpaceError = new ValidationError(
            keyNoSpaceErrorMessage,
            jobs[key],
            schema,
            ['jobs', key],
            'keyNoSpaces',
            key,
          )

          result.errors.push(keyNoSpaceError)
        }
      })
    }

    return result
  }
}

export default JsonSchemaCustomValidator
