import chevronLeftIcon from '@jetbrains/icons/chevron-left'
import Button from '@jetbrains/ring-ui-built/components/button/button'
import classnames from 'classnames'
import type * as React from 'react'

import styles from './SidebarHeader.module.css'

type JobStepSidebarHeaderProps = {
  title?: string
  subTitle?: React.ReactNode
  border?: boolean
  onClick?: (e: React.MouseEvent<HTMLButtonElement>) => void
}

function SidebarHeader({title, subTitle, border, onClick}: JobStepSidebarHeaderProps) {
  return (
    <div className={classnames(styles.container, {[styles.border]: border})}>
      <Button
        onClick={onClick}
        className={styles.button}
        iconClassName={styles.chevron}
        icon={chevronLeftIcon}
        title={title}
      >
        {title}
      </Button>
      {subTitle && <div className={styles.subTitle}>{subTitle}</div>}
    </div>
  )
}

export default SidebarHeader
