import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import cn from 'classnames'
import type React from 'react'
import {useEffect, useCallback} from 'react'

import {Size} from '../../../../../components/Input'
import Input from '../../../../../components/Input/Input'
import PasswordInput from '../../../../../components/PasswordInput/PasswordInput'
import {useApplySecrets} from '../../../../EditPipelinePage.hooks'
import usePipelineSecretControl from '../usePipelineSecretControl'

import {hideDefaultSecretValue} from './PipelineSecretFormFieldset.const'

import styles from './PipelineSecretFormFieldset.module.css'

type PipelineSecretFormFieldsetProps = {
  savedName: string
  deletable?: boolean
  inputRef?: React.RefObject<HTMLTextAreaElement>
}

function PipelineSecretFormFieldset({
  savedName,
  inputRef,
  deletable,
}: PipelineSecretFormFieldsetProps) {
  const {
    secretName,
    secretValue,
    secretValueExisting,
    secretNameErrorMessage,
    secretValueErrorMessage,
    secretNameInputChangeHandler,
    secretValueInputChangeHandler,
    secretDeleteButtonClickHandler,
  } = usePipelineSecretControl(savedName)
  const inputValuePlaceholder = secretValueExisting ? hideDefaultSecretValue : 'Value'
  const applySecrets = useApplySecrets()
  const applySecretChange = useCallback(
    () => applySecrets(key => key === savedName),
    [applySecrets, savedName],
  )
  useEffect(
    () => () => {
      applySecretChange()
    },
    [applySecretChange],
  )

  return (
    <div className={styles.pipelineSecretWrapForm}>
      <div className={styles.pipelineSecretFormInput}>
        <Input
          placeholder={'Secret Name'}
          onChange={secretNameInputChangeHandler}
          value={secretName}
          size={Size.FULL}
          aria-label="Secret Name"
          error={secretNameErrorMessage}
          autoComplete="off"
          multiline
          inputClassName={styles.textArea}
          inputRef={inputRef}
        />
      </div>
      <div>{'='}</div>
      <div className={cn(styles.pipelineSecretFormInput)}>
        <PasswordInput
          placeholder={inputValuePlaceholder}
          onChange={secretValueInputChangeHandler}
          onBlur={applySecretChange}
          value={secretValue ?? ''}
          size={Size.FULL}
          aria-label="Value"
          error={secretValueErrorMessage}
          autoComplete="off"
          multiline
          inputClassName={styles.textArea}
          showEyeButton={secretValue != null && secretValue.length > 0}
        />
      </div>
      {deletable && (
        <IconButton
          className={styles.deleteButton}
          icon={'trash'}
          title={'Delete'}
          aria-label={'Delete'}
          onClick={secretDeleteButtonClickHandler}
        />
      )}
    </div>
  )
}

export default PipelineSecretFormFieldset
