import Toggle from '@jetbrains/ring-ui-built/components/toggle/toggle'
import type {ReactNode, ChangeEvent} from 'react'
import {Fragment, memo, useContext, useId} from 'react'

import {DisabledContext} from '../../../../../../contexts/DisabledContext'

import styles from './ToggleableProperty.module.css'

type Props = {
  className?: string
  label: string | undefined
  children: ReactNode
  details?: ReactNode
  checked?: boolean
  onChange: (event: ChangeEvent<HTMLInputElement>) => void
}

function ToggleableProperty({label, children, details, checked, onChange}: Props) {
  const isDisabled = useContext(DisabledContext)
  const id = useId()

  return (
    <Fragment>
      <Toggle className={styles.toggle} checked={checked} onChange={onChange} disabled={isDisabled}>
        <span id={id}>{label ?? 'Empty label'}</span>
        {details}
      </Toggle>
      {checked && children}
    </Fragment>
  )
}

export default memo(ToggleableProperty)
