import Button from '@jetbrains/ring-ui-built/components/button/button'
import ButtonGroup from '@jetbrains/ring-ui-built/components/button-group/button-group'
import {memo} from 'react'

import BranchSpecificationSelect from '../../../../../components/BranchSpecificationSelect/BranchSpecificationSelect'
import SidebarFooterContainer from '../../../SidebarFooterContainer/SidebarFooterContainer'
import SidebarHeader from '../../../SidebarSlider/Header/SidebarHeader'
import {ALL_BRANCHES, DEFAULT_BRANCH} from '../NotificationEditor.consts'

import CustomNotificationEvents from './CustomNotificationEvents/CustomNotificationEvents'
import {useNotificationEditorLogic} from './NotificationEditor.hooks'
import NotificationsUsersSelect from './UsersSelect/NotificationsUsersSelect'

import styles from './NotificationEditor.module.css'

function NotificationEditor() {
  const {
    emails,
    handleEmailsChange,
    isCustomEvents,
    setIsCustomEvents,
    customEvents,
    handleEventChange,
    updateNotification,
    branchSpecification,
    handleSelectBranchSpec,
  } = useNotificationEditorLogic()

  return (
    <div role="dialog" className={styles.sidebar}>
      <div className={styles.headerWrapper}>
        <SidebarHeader onClick={updateNotification} title="Email notification rule" />
      </div>
      <div className={styles.editorContainer}>
        <NotificationsUsersSelect
          label="Service email addresses"
          selectedEmails={emails ?? []}
          onChange={handleEmailsChange}
          className={styles.emailsSelect}
        />
        <label className={styles.label}>{'Branches to monitor'}</label>
        <BranchSpecificationSelect
          groupClassName={styles.branchSpecPolicy}
          specification={branchSpecification ?? ''}
          defaultBranch={DEFAULT_BRANCH}
          allBranches={ALL_BRANCHES}
          onSelectSpecification={handleSelectBranchSpec}
        />
        <div className={styles.eventsContainer}>
          <ButtonGroup label="Select an event to be notified of" className={styles.eventsSelect}>
            <Button
              className={styles.eventButton}
              active={!isCustomEvents}
              onClick={() => setIsCustomEvents(false)}
            >
              {'All new events'}
            </Button>
            <Button
              className={styles.eventButton}
              active={isCustomEvents}
              onClick={() => setIsCustomEvents(true)}
            >
              {'Custom set of events'}
            </Button>
          </ButtonGroup>
          {isCustomEvents && (
            <CustomNotificationEvents events={customEvents} updateEvents={handleEventChange} />
          )}
        </div>
      </div>
      <SidebarFooterContainer>
        <Button primary onClick={updateNotification} role={'dialog'}>
          {'Done'}
        </Button>
      </SidebarFooterContainer>
    </div>
  )
}

export default memo(NotificationEditor)
