import {useCallback, useState} from 'react'

import {useAppDispatch, useAppSelector} from '../../../../../../../../../hooks/react-redux'
import {emptyObject} from '../../../../../../../../../utils/empty'
import {usePipelineId} from '../../../../../../hooks/pipeline'
import {pipelinesApi} from '../../../../../../services/pipelinesApi'
import type {
  NewVcsRootDto,
  VersionedSettingsDto,
} from '../../../../../../services/pipelinesApi.types'
import {getDraft, getOriginalVersionedSettings} from '../../../../../EditPipelinePage.selectors'
import {pipelineDraft} from '../../../../../slices/EditPipelinePage.slices'

function useConfigurationStorageSection() {
  const pipelineId = usePipelineId()
  const vcsRoot =
    useAppSelector(state => getDraft(state, pipelineId)?.vcsRoot) ?? (emptyObject as NewVcsRootDto)
  const storedInRepo = !!useAppSelector(state => getDraft(state, pipelineId)?.versionedSettings)
    ?.storedInRepo
  const savedStoredInRepo = !!useAppSelector(getOriginalVersionedSettings(pipelineId))?.storedInRepo
  const [dialogVisible, setDialogVisible] = useState(false)
  const dispatch = useAppDispatch()
  const changeVersionedSettingsHandler = useCallback(
    (settings: VersionedSettingsDto) =>
      dispatch(
        pipelineDraft.actions.setVersionedSettings({
          id: pipelineId,
          ...settings,
        }),
      ),
    [dispatch, pipelineId],
  )
  const [checkVersionedSettings] = pipelinesApi.endpoints.checkVersionedSettings.useLazyQuery()
  const handleStorageChange = useCallback(
    async (settings: VersionedSettingsDto) => {
      changeVersionedSettingsHandler(settings)
      if (settings.storedInRepo && !savedStoredInRepo && vcsRoot.url) {
        const vcsRootId = vcsRoot.id
        if (vcsRootId) {
          const hasFileInRepo = await checkVersionedSettings({vcsRootId}).unwrap()
          setDialogVisible(hasFileInRepo)
        }
      }
    },
    [changeVersionedSettingsHandler, checkVersionedSettings, savedStoredInRepo, vcsRoot],
  )
  const handleVersionedSettingsChange = useCallback(
    (settings: VersionedSettingsDto) => {
      changeVersionedSettingsHandler(settings)
      setDialogVisible(false)
    },
    [changeVersionedSettingsHandler],
  )
  const onClose = useCallback(() => {
    setDialogVisible(false)
    changeVersionedSettingsHandler({storedInRepo: false})
  }, [changeVersionedSettingsHandler])

  return {
    storedInRepo,
    handleStorageChange,
    dialogVisible,
    handleVersionedSettingsChange,
    onClose,
  }
}

export default useConfigurationStorageSection
