import uniq from 'lodash/uniq'
import plur from 'plur'
import {memo, useMemo, useState, useEffect} from 'react'

import SettingsBlock from '../../../../components/SettingsBlock/SettingsBlock'
import usePermissionCanEditPipeline from '../../../../hooks/usePermissionCanEditPipeline'
import Notification from '../../Notifications/Notification'

import {EVENT_NAMES_AND_TYPES} from './PipelineNotifications.const'
import {usePipelineNotifications} from './PipelineNotifications.hooks'

import styles from './PipelineNotifiactions.module.css'

function PipelineNotifications() {
  const {canEditPipeline} = usePermissionCanEditPipeline()
  const {
    notifications,
    settingsBlockId,
    addNotification,
    cloneNotification,
    deleteNotification,
    restoreNotification,
    editNotification,
    onNotificationEnabledChange,
    deletedNotifications,
  } = usePipelineNotifications()

  const [toggleStates, setToggleStates] = useState<boolean[]>([])
  useEffect(() => {
    setToggleStates(notifications.map(n => n.enabled))
  }, [notifications])

  const count = notifications.length
  const notificationsTitle = count ? plur('Notification', count) : 'No Notifications'
  const collapseNote = useMemo(
    () =>
      uniq(
        notifications.map(
          notification =>
            `${notification.emails.join(', ')}${
              notification.branchSpecification
                ? notification.emails.length > 0
                  ? `, ${notification.branchSpecification}`
                  : notification.branchSpecification
                : ''
            }${notification.emails.length > 0 || notification.branchSpecification ? ', ' : ''}${notification.events
              .filter(e => e.enabled)
              .map(e => EVENT_NAMES_AND_TYPES[e.type as keyof typeof EVENT_NAMES_AND_TYPES])
              .join(', ')}`,
        ),
      ).join('; '),
    [notifications],
  )

  return (
    <>
      <SettingsBlock
        id={settingsBlockId}
        collapsible={count > 0 && canEditPipeline}
        collapsedDefault
        collapsedNote={collapseNote}
        title={notificationsTitle}
        onAddClick={canEditPipeline ? () => addNotification() : undefined}
        customActions={anchor => <div className={styles.addNotification}>{anchor}</div>}
      >
        {notifications
          .filter(n => !!n)
          .map((n, index) => (
            <Notification
              notificationId={index.toString()}
              key={n.id}
              branchFilter={n.branchSpecification}
              events={n.events}
              users={n.emails}
              onToggleChange={_ => {
                const newToggleStates = [...toggleStates]
                newToggleStates[index] = !toggleStates[index]
                setToggleStates(newToggleStates)

                onNotificationEnabledChange(index.toString(), n, newToggleStates[index])
              }}
              isActive={toggleStates[index] !== undefined ? toggleStates[index] : n.enabled}
              onDelete={deleteNotification}
              onRestore={restoreNotification}
              isDeleted={deletedNotifications?.includes(index.toString()) || false}
              onEdit={editNotification}
              onClone={() => cloneNotification(n)}
            />
          ))}
      </SettingsBlock>
    </>
  )
}

export default memo(PipelineNotifications)
