import EMailIcon from '@jetbrains/icons/e-mail-20px.svg'
import Toggle from '@jetbrains/ring-ui-built/components/toggle/toggle'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import cn from 'classnames'
import type {SyntheticEvent} from 'react'
import {useMemo, memo} from 'react'

import EditButton from '../../../components/EditButton/EditButton'
import type {Event} from '../../../services/pipelinesApi.types'
import {EVENT_NAMES_AND_TYPES} from '../PipelineSettingsSidebar/PipelineNotifications/PipelineNotifications.const'

import styles from './Notification.module.css'

type Props = {
  notificationId?: string
  branchFilter?: string
  users?: string[]
  events?: Event[]
  isActive?: boolean
  onToggleChange: (event: SyntheticEvent<HTMLInputElement>) => void
  onClone: () => void
  onEdit: (id: string) => void
  onDelete: (id: string) => void
  onRestore: (id: string) => void
  isDeleted: boolean
}

function Notification({
  notificationId,
  branchFilter = '',
  users = [],
  events = [],
  isActive,
  onToggleChange,
  onClone,
  onDelete,
  onRestore,
  onEdit,
  isDeleted,
}: Props) {
  const enabledEvents = useMemo(() => events?.filter(event => event.enabled), [events])
  return (
    <div className={cn(styles.container, {[styles.deleted]: isDeleted})}>
      <div className={styles.header}>
        <div className={styles.emailIcon}>
          <span role="presentation" className={styles.emailIconImage}>
            <EMailIcon />
          </span>
        </div>
        <div className={styles.title}>
          <p className={styles.notificationText}>{'Notification'}</p>
          <p className={styles.emailNotifierText}>{'Email notifier'}</p>
        </div>
        <div className={styles.buttonsWrapper}>
          {!isDeleted && <Toggle checked={isActive} onChange={onToggleChange} />}
          <div className={styles.controls}>
            <div className={styles.controlButtons}>
              <IconButton
                className={styles.actionButton}
                icon="duplicate"
                title="Clone"
                aria-label="Clone"
                onClick={() => onClone()}
                hidden={isDeleted}
              />
              {!isDeleted && (
                <EditButton
                  className={styles.actionButton}
                  title="Edit"
                  aria-label="Edit"
                  onClick={() => onEdit(notificationId ?? '0')}
                />
              )}
              <IconButton
                className={styles.actionButton}
                icon="trash"
                title="Delete"
                aria-label="Delete"
                onClick={() => onDelete(notificationId ?? '0')}
                hidden={isDeleted}
              />
              <IconButton
                className={styles.actionButton}
                icon="update"
                title="Restore"
                aria-label="Restore"
                onClick={() => {
                  onRestore(notificationId ?? '0')
                }}
                hidden={!isDeleted}
              />
            </div>
          </div>
        </div>
      </div>
      <div className={styles.details}>
        <p className={styles.detailText}>{`Sent to: ${users.join(',')}`}</p>
        <p className={styles.detailText}>{`Branch filter: ${branchFilter}`}</p>
        {enabledEvents.length === events?.length ? (
          <p className={styles.detailText}>{`Events: All Events`}</p>
        ) : (
          <p className={styles.detailText}>{`Events: ${enabledEvents
            .map(event => EVENT_NAMES_AND_TYPES[event.type as keyof typeof EVENT_NAMES_AND_TYPES])
            .join(', ')}`}</p>
        )}
      </div>
    </div>
  )
}

export default memo(Notification)
