import LoaderInline from '@jetbrains/ring-ui-built/components/loader-inline/loader-inline'
import {Directions} from '@jetbrains/ring-ui-built/components/popup/popup.consts'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import {useMemo, memo, Suspense} from 'react'
import {ErrorBoundary} from 'react-error-boundary'
import {graphql, useFragment, useLazyLoadQuery} from 'react-relay'

import BuildArtifactsPopup from '../../../../../../common/BuildArtifacts/BuildArtifactsPopup'
import type {pipelineHeadBuildTypeFragment$key} from '../../../../hooks/__generated__/pipelineHeadBuildTypeFragment.graphql'
import {useLastRun} from '../../../EditPipelinePage.hooks'

import type {JobDirectoryPopupLastRunFragment$key} from './__generated__/JobDirectoryPopupLastRunFragment.graphql'
import type {JobDirectoryPopupQuery} from './__generated__/JobDirectoryPopupQuery.graphql'
import {MAX_POPUP_HEIGHT, PATH_TO_CHECKOUT_DIRECTORY_FILE} from './JobDirectoryPopup.consts'
import JobDirectoryPopupContent from './JobDirectoryPopupContent'
import type {JobDirectoryType} from './JobDirectoryTree/JobDirectoryTree.types'

import styles from './JobDirectoryPopup.module.css'

const lastRunFragment = graphql`
  fragment JobDirectoryPopupLastRunFragment on Build {
    id
  }
`

const query = graphql`
  query JobDirectoryPopupQuery($buildLocator: String!, $path: String!) {
    fileMetadataOfBuild(buildLocator: $buildLocator, path: $path) {
      name
      size
    }
  }
`

interface Props {
  jobId: string
  pipelineHeadBuildTypeKey: pipelineHeadBuildTypeFragment$key | null
  onSelect: (type: JobDirectoryType, path: string) => void
  onlyDirectories?: boolean
  buttonClass?: string
}

function JobDirectoryPopup(props: {
  buildId: number
  onlyDirectories?: boolean
  onSelect: (type: JobDirectoryType, path: string) => void
}) {
  const {buildId, onlyDirectories, onSelect} = props
  const buildLocator = `id:${buildId}`
  const {fileMetadataOfBuild} = useLazyLoadQuery<JobDirectoryPopupQuery>(query, {
    buildLocator,
    path: PATH_TO_CHECKOUT_DIRECTORY_FILE,
  })

  const anchor = useMemo(
    () => (
      <IconButton
        className={styles.icon}
        title="Artifacts"
        target="_blank"
        rel="noreferrer"
        icon={'folder'}
      />
    ),
    [],
  )

  return (
    (fileMetadataOfBuild?.size ?? 0) > 0 && (
      <BuildArtifactsPopup
        popupOffset={4}
        maxHeight={MAX_POPUP_HEIGHT}
        popupDirection={[Directions.BOTTOM_LEFT, Directions.TOP_LEFT]}
        wrapperProps={{
          onClick: e => e.preventDefault(),
        }}
        hasArtifacts
        anchor={anchor}
      >
        {() => (
          <Suspense fallback={<LoaderInline>{'Loading...'}</LoaderInline>}>
            <JobDirectoryPopupContent
              buildLocator={buildLocator}
              onlyDirectories={onlyDirectories}
              onSelect={onSelect}
            />
          </Suspense>
        )}
      </BuildArtifactsPopup>
    )
  )
}

function JobDirectoryPopupContainer(props: Props) {
  const {jobId, onSelect, pipelineHeadBuildTypeKey, onlyDirectories, buttonClass} = props

  const runKey = useLastRun(jobId, pipelineHeadBuildTypeKey)
  const run = useFragment<JobDirectoryPopupLastRunFragment$key>(lastRunFragment, runKey)

  return (
    <ErrorBoundary fallbackRender={() => <></>}>
      <Suspense>
        {run?.id != null && (
          <div className={buttonClass}>
            <JobDirectoryPopup
              buildId={run.id}
              onlyDirectories={onlyDirectories}
              onSelect={onSelect}
            />
          </div>
        )}
      </Suspense>
    </ErrorBoundary>
  )
}

export default memo(JobDirectoryPopupContainer)
