import {useCallback, useMemo} from 'react'
import {useSearchParams} from 'react-router'

import {sideBarNavigatiobSearchParam} from '../../SettingsSidebarContent.const'
import useJobOutputParametersStore from '../JobOutputParameters/useJobOutputParametersStore'

function useJobOutputParametersSidebar() {
  const {
    jobOutputParameters,
    deletedJobOutputParameters,
    renamedJobOutputParameters,
    formSpotParamId,
    formErrorSpotId,
    jobOutputParametersFormErrorMessage,
    getIsJobOutputParametersValid,
    changeNameHandler,
    changeValueHandler,
    restoreParametersHandler,
    deleteParametersHandler,
    confirmParametersHandler,
    clearAddedJobOutputParametersHandler,
    jobOutputParameterMultiplyConfirmHandler,
    addJobOutputParameterHandler: clickAddParameterButtonHandler,
  } = useJobOutputParametersStore()
  const parametersControlValue = useMemo(
    () => ({
      formSpotParamId,
      formErrorSpotId,
      parameters: jobOutputParameters,
      renamedParameters: renamedJobOutputParameters,
      onNameChange: changeNameHandler,
      onValueChange: changeValueHandler,
      onRestore: restoreParametersHandler,
      onDelete: deleteParametersHandler,
      onConfirm: confirmParametersHandler,
    }),
    [
      changeNameHandler,
      changeValueHandler,
      confirmParametersHandler,
      deleteParametersHandler,
      formErrorSpotId,
      formSpotParamId,
      jobOutputParameters,
      renamedJobOutputParameters,
      restoreParametersHandler,
    ],
  )
  const [searchParams, setSearchParams] = useSearchParams()
  const sidebarNavigationBackHandler = useCallback(() => {
    searchParams.delete(sideBarNavigatiobSearchParam.outputParameters)

    const searchParamsObject = Object.fromEntries(searchParams.entries())

    setSearchParams(searchParamsObject)
  }, [searchParams, setSearchParams])
  const clickDoneButtonHandler = useCallback(() => {
    const parametersName = Object.values(renamedJobOutputParameters).join('')
    const parametersValue = Object.values(jobOutputParameters).join('')
    const isFormNotFiled = !parametersName && !parametersValue

    if (isFormNotFiled) {
      clearAddedJobOutputParametersHandler()
      sidebarNavigationBackHandler()
    } else {
      const isValid = getIsJobOutputParametersValid()

      if (isValid) {
        jobOutputParameterMultiplyConfirmHandler()
        sidebarNavigationBackHandler()
      }
    }
  }, [
    renamedJobOutputParameters,
    jobOutputParameters,
    clearAddedJobOutputParametersHandler,
    sidebarNavigationBackHandler,
    getIsJobOutputParametersValid,
    jobOutputParameterMultiplyConfirmHandler,
  ])

  return {
    jobOutputParameters,
    deletedJobOutputParameters,
    parametersControlValue,
    jobOutputParametersFormErrorMessage,
    clickDoneButtonHandler,
    clickAddParameterButtonHandler,
  }
}

export default useJobOutputParametersSidebar
