import cloneDeep from 'lodash/cloneDeep'
import {useMemo} from 'react'
import {usePreloadedQuery} from 'react-relay'
import type {PreloadedQuery} from 'react-relay/relay-hooks/EntryPointTypes'

import {emptyArray} from '../../../../../../../utils/empty'
import {usePipelineAdditionalVcsRootsOrDraft} from '../../../EditPipelinePage.hooks'
import {getCustomAgents} from '../../../EditPipelinePage.utils'
import type {JobAgentRequirementsCloudImagesQuery} from '../../../SettingsSidebarContent/JobSettingsSidebar/JobAgentRequirements/__generated__/JobAgentRequirementsCloudImagesQuery.graphql'
import {cloudImagesQuery} from '../../../SettingsSidebarContent/JobSettingsSidebar/JobAgentRequirements/JobAgentRequirements.queries'
import schemaJson from '../schema.json'
import getJsonSchemaJobs from '../utils/getJsonSchemaJobs'
import JsonSchemaCustomValidator from '../utils/JsonSchemaCustomValidator'

function useYamlSchema(
  currentYaml: string,
  cloudImagesQueryRef: PreloadedQuery<JobAgentRequirementsCloudImagesQuery>,
) {
  const additionalVcsRoots = usePipelineAdditionalVcsRootsOrDraft()
  const cloudImage =
    usePreloadedQuery(cloudImagesQuery, cloudImagesQueryRef)?.cloudImages?.cloudImage ?? emptyArray
  const schema = useMemo(() => {
    const clonedSchemaJson = cloneDeep(schemaJson)
    const customAgents = [...cloudImage, ...getCustomAgents()].map(({name}) => name)
    const additionalVcsRootNames = additionalVcsRoots.reduce((acc, {url}) => {
      const jsonSchemaAdditionalVcsRoot = {
        [url]: {
          ...clonedSchemaJson.definitions.repositories.properties.main,
        },
      }

      return {
        ...acc,
        ...jsonSchemaAdditionalVcsRoot,
      }
    }, {})
    const {jobs, filesPublication} = getJsonSchemaJobs(currentYaml)

    // Add enum files
    if (filesPublication.length) {
      clonedSchemaJson.definitions.files.enum = filesPublication
        .map(item => (typeof item === 'string' ? item : item.path))
        .filter(Boolean)
    }

    // Add repositories
    clonedSchemaJson.definitions.repositories.properties = {
      ...clonedSchemaJson.definitions.repositories.properties,
      ...additionalVcsRootNames,
    }

    // Add enum of agents
    if (customAgents.length) {
      if (clonedSchemaJson.definitions.runOn.anyOf[0].enum) {
        clonedSchemaJson.definitions.runOn.anyOf[0].enum = [
          ...clonedSchemaJson.definitions.runOn.anyOf[0].enum,
          ...customAgents,
        ]
      }
    }

    // Add jobs
    clonedSchemaJson.properties.jobs.properties = {
      ...clonedSchemaJson.properties.jobs.properties,
      ...jobs,
    }

    return clonedSchemaJson
  }, [additionalVcsRoots, cloudImage, currentYaml])

  const validator = useMemo(() => {
    const newValidator = new JsonSchemaCustomValidator()
    newValidator.addSchema(schema)

    return newValidator
  }, [schema])

  return {validator, schema}
}

export default useYamlSchema
