import type {Draft} from 'immer'
import {produce} from 'immer'

import {useCallback, useMemo} from 'react'
import {useSearchParams} from 'react-router'

import {useAppDispatch, useAppSelector} from '../../../../../../../hooks/react-redux'
import {useStoredSettingsValue} from '../../../../contexts/StoredSettingsValue/StoredSettingsValueContext'
import type {pipelineHeadBuildTypeFragment$key} from '../../../../hooks/__generated__/pipelineHeadBuildTypeFragment.graphql'
import {usePipelineId} from '../../../../hooks/pipeline'
import {pipelinesApi} from '../../../../services/pipelinesApi'
import type {Step} from '../../../../types'
import {validateField} from '../../../EditPipelinePage.actions'
import {useDraftStepError, useJobId} from '../../../EditPipelinePage.hooks'
import {getSteps, validatorSelectors} from '../../../EditPipelinePage.selectors'
import {pipelineDraft, pipelineErrors, suggestions} from '../../../slices/EditPipelinePage.slices'
import {FormType} from '../../../slices/EditPipelinePage.slices.types'
import {sideBarNavigatiobSearchParam} from '../../SettingsSidebarContent.const'
import useJobStepsStoredValue from '../JobSteps/hooks/useJobStepsStoredValue'
import {jsonFormRunnersAvailableSet} from '../JobSteps/JobStep/JobStepJsonForm/JobStepJsonForm.const'
import {getStepPreset} from '../JobSteps/JobSteps.utils'

import {WORKING_DIRECTORY} from './JobStepSidebar.consts'

function useJobStepSidebar(
  stepIndex: number,
  pipelineHeadBuildTypeKey: pipelineHeadBuildTypeFragment$key | null,
) {
  const jobId = useJobId()!
  const pipelineId = usePipelineId()
  const dispatch = useAppDispatch()
  const storedNameKey = `${jobId}_${stepIndex}_name`
  const [searchParams, setSearchParams] = useSearchParams()
  const {setValueToStoredSettings, getValueFromStoredSettings} = useStoredSettingsValue()
  const {jobRunners} = pipelinesApi.endpoints.getPipelineRunnersJsonFromXMLs.useQuery(undefined, {
    selectFromResult: ({data}) => ({
      jobRunners: data,
    }),
  })
  const jobRunnersKey = jobRunners ? Object.keys(jobRunners) : undefined
  const jobRunnersSet = new Set(jobRunnersKey)
  const clickButtonBackHandler = () => {
    searchParams.delete(sideBarNavigatiobSearchParam.step)

    const searchParamsObject = Object.fromEntries(searchParams.entries())

    setSearchParams(searchParamsObject)
  }
  const clickJobDoneButtonHandler = () => {
    const valideFormState = Object.keys(validatorSelectors[FormType.STEP] ?? {})
      .map(fieldName =>
        dispatch(validateField({pipelineId, jobId, type: FormType.STEP, id: stepIndex}, fieldName)),
      )
      .find(check => !check)

    if (valideFormState === undefined) {
      clickButtonBackHandler()
    }
  }
  const clickDeleteButtonHandler = () => {
    dispatch(pipelineDraft.actions.deleteStep({id: pipelineId, jobId, index: stepIndex}))
    dispatch(
      pipelineErrors.actions.clear({
        pipelineId,
        jobId,
        formType: FormType.STEP,
        formId: stepIndex,
      }),
    )
    clickButtonBackHandler()
  }
  const jobStepListStore = useAppSelector(state => getSteps(state, pipelineId, jobId))
  const stepList = useMemo(() => jobStepListStore ?? [], [jobStepListStore])
  const currentStep = stepList[stepIndex]
  const currenStepType = currentStep?.type?.toLocaleLowerCase()
  const generatedStepName = `Step ${stepIndex + 1}`
  const currentStepName = currentStep?.name
  const jobSidebarTitle = currentStepName
    ? `${generatedStepName}: ${currentStepName}`
    : generatedStepName
  const {addStoredJobStep, getStoredJobStep} = useJobStepsStoredValue(stepList, jobId)
  const updateSteps = useCallback(
    (recipe: (draft: Draft<Step[]>) => void, index: number) => {
      const steps = produce(stepList ?? [], recipe)
      const storedStep = steps[index]

      addStoredJobStep(storedStep, index)

      dispatch(
        pipelineDraft.actions.setSteps({
          id: pipelineId,
          jobId,
          steps,
        }),
      )
    },
    [stepList, addStoredJobStep, dispatch, pipelineId, jobId],
  )
  const onStepPropertiesChange = useCallback(
    (index: number, properties: Array<{name: string; value: string | null}>) => {
      updateSteps((draft: Draft<Step[]>) => {
        const step = draft[index]

        for (const {name, value} of properties) {
          if (value == null) {
            delete step[name]
            dispatch(
              pipelineErrors.actions.clear({
                pipelineId,
                jobId,
                formType: FormType.STEP,
                formId: index,
                fieldName: name,
              }),
            )
          } else {
            step[name] = value
          }
        }
      }, index)
    },
    [dispatch, jobId, pipelineId, updateSteps],
  )
  const onStepPropertyChange = useCallback(
    (index: number, name: string, value: string | null) => {
      onStepPropertiesChange(index, [{name, value}])
      dispatch(validateField({pipelineId, jobId, type: FormType.STEP, id: index}, name))
    },
    [dispatch, jobId, onStepPropertiesChange, pipelineId],
  )
  const changeNameInputHandler = useCallback(
    ({currentTarget}: React.ChangeEvent<HTMLInputElement>) => {
      onStepPropertyChange(stepIndex, 'name', currentTarget.value)
      setValueToStoredSettings(storedNameKey, currentTarget.value)
    },
    [onStepPropertyChange, setValueToStoredSettings, stepIndex, storedNameKey],
  )
  const onStepTypeChange = useCallback(
    (index: number, type: string) => {
      const stepId = `step-${jobId}-${index + 1}`
      const stepName = (getValueFromStoredSettings(storedNameKey) as string) ?? ''
      dispatch(suggestions.actions.hideSuccessMessage({id: stepId}))
      updateSteps((draft: Draft<Step[]>) => {
        const prevWorkingDirectory = draft[index][WORKING_DIRECTORY]
        const prevStep = getStoredJobStep(type, index)
        const stepPreset = getStepPreset(type)
        let step: Step = prevStep ? prevStep : {type, [WORKING_DIRECTORY]: prevWorkingDirectory}

        if (!prevStep && stepPreset) {
          step = {
            ...step,
            ...stepPreset,
          }
        }

        draft[index] = {...step, name: stepName}
      }, index)
      dispatch(
        pipelineErrors.actions.clear({
          pipelineId,
          jobId,
          formType: FormType.STEP,
          formId: index,
        }),
      )
    },
    [
      dispatch,
      getStoredJobStep,
      getValueFromStoredSettings,
      jobId,
      pipelineId,
      storedNameKey,
      updateSteps,
    ],
  )
  const errorMessage = useDraftStepError({
    stepIndex,
  })
  const isApiRunnersAvailable =
    jobRunnersSet.has(currenStepType) && jsonFormRunnersAvailableSet.has(currenStepType)
  const valueProvider = useMemo(
    () => ({
      autoFocus: false,
      pipelineHeadBuildTypeKey,
      jobRunners: jobRunners ?? {},
      jobId,
      stepIndex,
      originalIndex: stepIndex,
      step: currentStep,
      onStepPropertiesChange,
    }),
    [pipelineHeadBuildTypeKey, jobRunners, jobId, stepIndex, currentStep, onStepPropertiesChange],
  )

  return {
    jobRunnersKey,
    valueProvider,
    jobSidebarTitle,
    onStepTypeChange,
    currenStepType,
    currentStepName,
    currentStep,
    errorMessage,
    isApiRunnersAvailable,
    changeNameInputHandler,
    clickJobDoneButtonHandler,
    clickButtonBackHandler,
    clickDeleteButtonHandler,
  }
}

export default useJobStepSidebar
