import ParametersSidebar from '../../../../components/ParametersSidebar/ParametersSidebar'
import ParametersControlProvider from '../../../../contexts/ParametersControl/ParametersControlContext'

import JobOutputParametersSidebarHeaderInfo from './JobOutputParametersSidebarHeaderInfo'
import useJobOutputParametersSidebar from './useJobOutputParametersSidebar'

function JobOutputParametersSidebar() {
  const {
    jobOutputParameters,
    deletedJobOutputParameters,
    parametersControlValue,
    jobOutputParametersFormErrorMessage,
    clickDoneButtonHandler,
    clickAddParameterButtonHandler,
  } = useJobOutputParametersSidebar()

  return (
    <ParametersControlProvider value={parametersControlValue}>
      <ParametersSidebar
        title="Output parameters"
        subTitle={<JobOutputParametersSidebarHeaderInfo />}
        parameters={jobOutputParameters}
        deleted={deletedJobOutputParameters}
        errorMessage={jobOutputParametersFormErrorMessage}
        onDone={clickDoneButtonHandler}
        onAdd={clickAddParameterButtonHandler}
      />
    </ParametersControlProvider>
  )
}

export default JobOutputParametersSidebar
