import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import {memo} from 'react'

import type {pipelineParentProjectFragment$key} from '../../../../hooks/__generated__/pipelineParentProjectFragment.graphql'
import SidebarFooter from '../../SidebarFooter/SidebarFooter'

import {usePipelineSettingsFooter} from './PipelineSettingsFooter.hooks'

import ConfirmationDialog from 'src/components/common/ConfirmationDialog/ConfirmationDialog'

type Props = {
  pipelineParentProjectKey: pipelineParentProjectFragment$key | null
}
function PipelineSettingsFooter({pipelineParentProjectKey}: Props) {
  const title = 'Delete pipeline'
  const {
    name,
    isLoading,
    isDialogShown,
    isReadonly,
    showDialog,
    hideDialog,
    handlerConfirmDeletePipelineButtonClick,
  } = usePipelineSettingsFooter(pipelineParentProjectKey)

  return (
    <SidebarFooter>
      <IconButton title={title} icon={'trash'} disabled={isReadonly} onClick={showDialog} danger>
        {title}
      </IconButton>
      <ConfirmationDialog
        show={isDialogShown}
        title={`Delete pipeline ${name}?`}
        confirmButtonText={'Delete'}
        onConfirm={handlerConfirmDeletePipelineButtonClick}
        onCancel={hideDialog}
        loader={isLoading}
      />
    </SidebarFooter>
  )
}

export default memo(PipelineSettingsFooter)
