import {useSearchParams} from 'react-router'

import {useAppDispatch, useAppSelector} from '../../../../../../../../hooks/react-redux'
import {usePipelineId} from '../../../../../hooks/pipeline'
import {getPipelineErrorMessage} from '../../../../EditPipelinePage.selectors'
import {pipelineForm} from '../../../../slices/EditPipelinePage.slices'
import {FormType} from '../../../../slices/EditPipelinePage.slices.types'
import {
  ALL_BRANCHES,
  DEFAULT_BRANCH,
} from '../../../PipelineSettingsTriggerSidebar/PipelineOnChangesTriggerForm/PipelineOnChangesTriggerForm.const'
import {sideBarNavigatiobSearchParam} from '../../../SettingsSidebarContent.const'

function usePipelineOnChangesTrigger(
  index: number,
  triggerBranches?: boolean,
  triggerPullRequests?: boolean,
  branchFilter?: string,
) {
  const pipelineId = usePipelineId()
  const formParams = {pipelineId, type: FormType.TRIGGER, id: index}
  const [searchParams, setSearchParams] = useSearchParams()
  const dispatch = useAppDispatch()
  const branchSpecLabel =
    branchFilter == null || branchFilter === ALL_BRANCHES
      ? 'in All branches'
      : branchFilter === DEFAULT_BRANCH
        ? 'in Default branch'
        : `in Specific branches`

  const pullRequestsLabel = triggerPullRequests
    ? triggerBranches
      ? 'including Pull requests'
      : 'in Pull requests'
    : 'excluding Pull requests'
  const detailsLabel = `Start builds on new changes ${triggerBranches ? branchSpecLabel : ''} ${pullRequestsLabel}`

  const errorMessage = useAppSelector(
    getPipelineErrorMessage({
      pipelineId,
      formType: FormType.TRIGGER,
    }),
  )

  const handlerEditButtonClick = () => {
    dispatch(pipelineForm.actions.open(formParams))
    const searchParamsObject = Object.fromEntries(searchParams.entries())
    setSearchParams({
      ...searchParamsObject,
      [sideBarNavigatiobSearchParam.trigger]: `${index}`,
    })
  }

  return {
    detailsLabel,
    errorMessage,
    handlerEditButtonClick,
  }
}

export default usePipelineOnChangesTrigger
