import {useCallback, useMemo} from 'react'
import {useSearchParams} from 'react-router'

import {HighlightSpotId} from '../../../components/HighlighterTextField/HighlighterTextFieldContext.types'
import usePipelineParametersStore from '../PipelineSettingsSidebar/PipelineParameters/usePipelineParametersStore'
import {sideBarNavigatiobSearchParam} from '../SettingsSidebarContent.const'

function usePipelineSettingsParametersSidebar() {
  const {
    parameters,
    deletedParameters,
    renamedParameters,
    formSpotParamId,
    formErrorSpotId,
    parametersFormErrorMessage,
    getIsParametersValid,
    changeNameHandler,
    changeValueHandler,
    restoreParametersHandler,
    deleteParametersHandler,
    confirmParametersHandler,
    parameterMultiplyConfirmHandler,
    clearAddedParametersHandler,
    addParameterHandler: clickAddParameterButtonHandler,
  } = usePipelineParametersStore()
  const [searchParams, setSearchParams] = useSearchParams()
  const parametersControlValue = useMemo(
    () => ({
      parameters,
      renamedParameters,
      formSpotParamId,
      formErrorSpotId,
      valueHighlightSpotId: HighlightSpotId.PIPELINEPARAMETER,
      onNameChange: changeNameHandler,
      onValueChange: changeValueHandler,
      onRestore: restoreParametersHandler,
      onDelete: deleteParametersHandler,
      onConfirm: confirmParametersHandler,
    }),
    [
      changeNameHandler,
      changeValueHandler,
      confirmParametersHandler,
      deleteParametersHandler,
      formErrorSpotId,
      formSpotParamId,
      parameters,
      renamedParameters,
      restoreParametersHandler,
    ],
  )
  const sidebarNavigationBackHandler = useCallback(() => {
    searchParams.delete(sideBarNavigatiobSearchParam.parameters)

    const searchParamsObject = Object.fromEntries(searchParams.entries())

    setSearchParams(searchParamsObject)
  }, [searchParams, setSearchParams])
  const clickDoneButtonHandler = useCallback(() => {
    const parametersName = Object.values(renamedParameters).join('')
    const parametersValue = Object.values(parameters).join('')
    const isFormNotFiled = !parametersName && !parametersValue

    if (isFormNotFiled) {
      clearAddedParametersHandler()
      sidebarNavigationBackHandler()
    } else {
      const isValid = getIsParametersValid()

      if (isValid) {
        parameterMultiplyConfirmHandler()
        sidebarNavigationBackHandler()
      }
    }
  }, [
    renamedParameters,
    parameters,
    clearAddedParametersHandler,
    sidebarNavigationBackHandler,
    getIsParametersValid,
    parameterMultiplyConfirmHandler,
  ])

  return {
    parameters,
    deletedParameters,
    parametersControlValue,
    parametersFormErrorMessage,
    clickDoneButtonHandler,
    clickAddParameterButtonHandler,
  }
}

export default usePipelineSettingsParametersSidebar
