import Button from '@jetbrains/ring-ui-built/components/button/button'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'

import SidebarFooterContainer from '../../../SidebarFooterContainer/SidebarFooterContainer'

import styles from './JobStepSidebarFooter.module.css'

type JobStepSidebarFooterProps = {
  onDone: () => void
  onDelete: () => void
  errorMessage?: string | null
}

function JobStepSidebarFooter({onDone, onDelete, errorMessage}: JobStepSidebarFooterProps) {
  const deleteStepTitle = 'Delete step'
  const hasErrorMessage = Boolean(errorMessage)

  return (
    <SidebarFooterContainer>
      <div className={styles.leftSide}>
        <Button primary disabled={hasErrorMessage} onClick={onDone}>
          {'Done'}
        </Button>
      </div>
      <IconButton title={deleteStepTitle} icon={'trash'} onClick={onDelete} danger>
        {deleteStepTitle}
      </IconButton>
    </SidebarFooterContainer>
  )
}

export default JobStepSidebarFooter
