import Button from '@jetbrains/ring-ui-built/components/button/button'
import classNames from 'classnames'

import styles from './InfoMessageContainer.module.css'

type InfoMessageContainerProps = {
  children: React.ReactNode
  onClick?: () => void
  clssName?: string
}

function InfoMessageContainer({children, onClick, clssName}: InfoMessageContainerProps) {
  const containerClassNamea = classNames(styles.container, clssName)

  return (
    <div className={containerClassNamea}>
      <div className={styles.text}>{children}</div>
      <Button inline primary onClick={onClick}>
        {'Got it'}
      </Button>
    </div>
  )
}

export default InfoMessageContainer
