import {useEffect, useMemo, useRef} from 'react'

import {focusSelfOrChildLink} from '../../../../../../../../utils/dom'
import {useSandbox} from '../../../../../../../../utils/fastdom'
import FileTreeNode, {
  ITEM_SELECTOR,
} from '../../../../../../../common/BuildArtifactsTree/FileTreeNode/FileTreeNode'

import type {JobDirectory, JobFile} from './JobDirectoryTree.types'
import {JobDirectoryType} from './JobDirectoryTree.types'
import {sortFileTreeNode} from './JobDirectoryTree.utils'

import styles from './JobDirectoryTree.module.css'

type Props = {
  compact?: boolean
  level?: number
  parentPath?: string
  onlyDirectories?: boolean
  entities: (JobDirectory | JobFile)[]
  onSelect: (type: JobDirectoryType, path: string) => void
}

export default function JobDirectoryTree({
  entities,
  parentPath = '',
  onSelect,
  compact,
  onlyDirectories,
  level = 0,
}: Props) {
  const {files, directories} = useMemo(
    () => ({
      files: entities
        .filter((entity): entity is JobFile => entity.type === JobDirectoryType.FILE)
        .sort(sortFileTreeNode),
      directories: entities
        .filter((entity): entity is JobDirectory => entity.type === JobDirectoryType.DIRECTORY)
        .sort(sortFileTreeNode),
    }),
    [entities],
  )

  const ref = useRef<HTMLUListElement>(null)
  const sandbox = useSandbox()

  useEffect(() => {
    if (level === 0) {
      const element = ref.current

      if (element == null) {
        return
      }

      const firstItem = element.querySelector(ITEM_SELECTOR)
      sandbox.mutate(() => {
        const {documentElement} = document
        const prevScroll = documentElement?.scrollTop
        focusSelfOrChildLink(firstItem)

        if (documentElement && prevScroll != null) {
          documentElement.scrollTop = prevScroll
        }
      })
    }
  }, [level, sandbox])

  return (
    <ul ref={ref} role={level === 0 ? 'tree' : 'group'} className={styles.list}>
      {directories.map(directory => {
        const expandable = onlyDirectories
          ? directory.files.some(file => file.type === JobDirectoryType.DIRECTORY)
          : directory.files.length > 0

        return (
          <FileTreeNode
            href={''}
            key={directory.name}
            compact={compact}
            level={level}
            expandable={expandable}
            name={directory.name}
            icon="folder"
            onSelect={() => onSelect(directory.type, `${parentPath}/${directory.name}`)}
          >
            <JobDirectoryTree
              parentPath={`${parentPath}/${directory.name}`}
              entities={directory.files}
              compact={compact}
              level={level + 1}
              onlyDirectories={onlyDirectories}
              onSelect={onSelect}
            />
          </FileTreeNode>
        )
      })}
      {!onlyDirectories &&
        files.map(file => (
          <FileTreeNode
            href={''}
            key={file.name}
            level={level}
            compact={compact}
            name={file.name}
            icon="file"
            onSelect={() => onSelect(file.type, `${parentPath}/${file.name}`)}
          />
        ))}
    </ul>
  )
}
