import {memo} from 'react'

import PipelineTrigger from '../PipelineTrigger/PipelineTrigger'

import usePipelineOnChangesTrigger from './PipelineOnChangesTrigger.hooks'

type Props = {
  index: number
  disabled?: boolean
  unsaved?: boolean
  triggerBranches?: boolean
  triggerPullRequests?: boolean
  branchFilter?: string
  onDisabled: (event: React.ChangeEvent<HTMLInputElement>) => void
  onDelete: () => void
}

function PipelineOnChangesTrigger({
  index,
  disabled,
  triggerBranches,
  triggerPullRequests,
  branchFilter,
  onDisabled,
  onDelete,
}: Props) {
  const {detailsLabel, errorMessage, handlerEditButtonClick} = usePipelineOnChangesTrigger(
    index,
    triggerBranches,
    triggerPullRequests,
    branchFilter,
  )

  return (
    <PipelineTrigger
      label={'On new changes'}
      details={detailsLabel}
      onDelete={onDelete}
      onEdit={handlerEditButtonClick}
      onDisabled={onDisabled}
      disabled={disabled}
      errorMessage={errorMessage}
    />
  )
}

export default memo(PipelineOnChangesTrigger)
