import plur from 'plur'
import {useMemo} from 'react'
import {useSearchParams} from 'react-router'

import {useAppDispatch, useAppSelector} from '../../../../../../../../hooks/react-redux'
import {usePipelineId} from '../../../../../hooks/pipeline'
import {isPullRequestsFeatureEnabled} from '../../../../../utils/featureToggles'
import {isPipelineFormAdd, isPipelineFormOpened} from '../../../../EditPipelinePage.selectors'
import {pipelineForm} from '../../../../slices/EditPipelinePage.slices'
import {FormType} from '../../../../slices/EditPipelinePage.slices.types'
import {sideBarNavigatiobSearchParam} from '../../../SettingsSidebarContent.const'
import {currentTimeZone} from '../PipelineTrigger/PipelineTrigger.consts'
import {
  getDaysOfWeekLabel,
  getNextTriggerDate,
  getTimeLabel,
} from '../PipelineTrigger/PipelineTrigger.utils'
import {amountDaysOfWeek} from '../PipelineTriggerForm/PipelineTriggerForm.consts'
import {TriggerSchedulingPolicy} from '../PipelineTriggers.consts'

function usePipelineScheduleTrigger(parameters: Record<string, string>, index: number) {
  const pipelineId = usePipelineId()
  const formParams = {pipelineId, type: FormType.TRIGGER, id: index}
  const isShowTriggerForm = useAppSelector(state => isPipelineFormOpened(state, formParams))
  const isAdd = useAppSelector(state => isPipelineFormAdd(state, formParams))
  const {
    daysOfWeek: parameterDaysOfWeek = '',
    hour: parameterHour = '00',
    minute: parameterMinute = '00',
    timezone = currentTimeZone,
    schedulingPolicy = TriggerSchedulingPolicy.DAILY,
  } = parameters
  const daysOfWeek = useMemo(() => {
    if (!parameterDaysOfWeek) {
      return []
    }
    return parameterDaysOfWeek.split(',')
  }, [parameterDaysOfWeek])
  const isEveryDay = daysOfWeek.length === amountDaysOfWeek || !daysOfWeek.length
  const detailWhenTriggerLabel = useMemo(() => {
    const {days, hours, minutes} = getNextTriggerDate(
      daysOfWeek,
      Number(parameterHour),
      Number(parameterMinute),
      isEveryDay,
      timezone,
    )
    const isNow = !days && !hours && !minutes
    const daysText = days ? `${days} ${plur('day', days)}` : ''
    const hoursText = hours ? `${hours} ${plur('hour', hours)}` : ''
    const minutesText = minutes ? `${minutes} ${plur('minute', minutes)}` : ''

    if (isNow) {
      return 'Will be triggered now'
    }

    return `Will be triggered in ${daysText} ${hoursText} ${minutesText}`
  }, [daysOfWeek, parameterHour, parameterMinute, isEveryDay, timezone])
  const dispatch = useAppDispatch()
  const [searchParams, setSearchParams] = useSearchParams()
  const handlerEditButtonClick = () => {
    dispatch(pipelineForm.actions.open(formParams))
    if (isPullRequestsFeatureEnabled) {
      const searchParamsObject = Object.fromEntries(searchParams.entries())
      setSearchParams({
        ...searchParamsObject,
        [sideBarNavigatiobSearchParam.trigger]: `${index}`,
      })
    }
  }
  const handlerJobTriggerFormClose = () => {
    dispatch(pipelineForm.actions.close(formParams))
    if (isPullRequestsFeatureEnabled) {
      searchParams.delete(sideBarNavigatiobSearchParam.trigger)
      const searchParamsObject = Object.fromEntries(searchParams.entries())
      setSearchParams(searchParamsObject)
    }
  }
  const triggerPolicyLabel = schedulingPolicy === TriggerSchedulingPolicy.DAILY ? 'Daily' : `Weekly`

  return {
    isShowTriggerForm,
    daysOfWeekLabel: getDaysOfWeekLabel(parameterDaysOfWeek),
    detailWhenTriggerLabel,
    timeLabel: getTimeLabel(parameters),
    timezone,
    parameterHour,
    parameterMinute,
    daysOfWeek,
    schedulingPolicy,
    triggerPolicyLabel,
    handlerJobTriggerFormClose,
    handlerEditButtonClick,
    isAdd,
  }
}

export default usePipelineScheduleTrigger
