import InfoIcon from '@jetbrains/icons/info.svg'
import Button from '@jetbrains/ring-ui-built/components/button/button'
import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import cn from 'classnames'
import * as React from 'react'

import styles from './InfoCollapsibleDetails.module.css'

type InfoCollapsibleDetailsProps = {
  title: string
  buttonCloseTitle?: string
  children?: React.ReactNode
  className?: string
}

const defaultButtonCloseTitle = 'Got it'

function InfoCollapsibleDetails({
  title,
  children,
  buttonCloseTitle = defaultButtonCloseTitle,
  className,
}: InfoCollapsibleDetailsProps) {
  const [isExpanded, setExpanded] = React.useState(false)
  const clickToggleBlockHandler = () => setExpanded(!isExpanded)
  const chevronIcon = isExpanded ? 'chevron-up' : 'chevron-down'

  return (
    <div className={cn(styles.container, className)}>
      <div role="presentation" className={styles.header} onClick={clickToggleBlockHandler}>
        <div className={styles.titleIcon}>
          <InfoIcon />
          <div className={styles.title}>{title}</div>
        </div>
        <SvgIcon className={styles.chevronIcon} icon={chevronIcon} />
      </div>
      {isExpanded && <div className={styles.content}>{children}</div>}
      {isExpanded && (
        <div className={styles.bottomActions}>
          <Button inline onClick={clickToggleBlockHandler}>
            {buttonCloseTitle}
          </Button>
        </div>
      )}
    </div>
  )
}

export default InfoCollapsibleDetails
