import plur from 'plur'
import {useCallback, useMemo, useState} from 'react'
import {useSearchParams} from 'react-router'

import {maxListItemLimitAmount} from '../../../../components/PipelineParametersSettingsBlock/PipelineParametersSettingsBlock.consts'
import usePermissionCanEditPipeline from '../../../../hooks/usePermissionCanEditPipeline'
import {sideBarNavigatiobSearchParam} from '../../SettingsSidebarContent.const'

import usePipelineSecretsStore from './usePipelineSecretsStore'

function usePipelineSecrets() {
  const {
    pipelineSecretsLength,
    pipelineSecretsKeys,
    pipelineSecretsKeysLength,
    pipelineRenamedSecrets,
    pipelineDeletedSecrets,
    pipelineSecretsFormErrorMessage,
  } = usePipelineSecretsStore()
  const {canEditPipeline} = usePermissionCanEditPipeline()
  const isSettingsBlockCollapsible = pipelineSecretsKeysLength > 0 && canEditPipeline
  const [listItemLimit, setListItemLimit] = useState<number>(maxListItemLimitAmount)
  const isShowMoreButton = pipelineSecretsKeysLength > maxListItemLimitAmount
  const isBlockExpanded = listItemLimit === pipelineSecretsKeysLength
  const [searchParams, setSearchParams] = useSearchParams()
  const searchParamsObject = Object.fromEntries(searchParams.entries())
  const settingsBlockTitle = pipelineSecretsLength
    ? plur('Secret', pipelineSecretsLength)
    : 'No Secrets'
  const settingsBlockCollapsedNote = useMemo(
    () =>
      pipelineSecretsKeys
        .filter(key => !pipelineDeletedSecrets?.includes(key))
        .map(key => `${pipelineRenamedSecrets?.[key] ?? key}`)
        .join(', '),
    [pipelineDeletedSecrets, pipelineRenamedSecrets, pipelineSecretsKeys],
  )
  const clickShowMoreButtonHandler = useCallback(() => {
    const itemLimit =
      listItemLimit === maxListItemLimitAmount ? pipelineSecretsKeysLength : maxListItemLimitAmount

    setListItemLimit(itemLimit)
  }, [listItemLimit, pipelineSecretsKeysLength])
  const clickEditSecretsHandler = canEditPipeline
    ? () =>
        setSearchParams({
          ...searchParamsObject,
          [sideBarNavigatiobSearchParam.secrets]: 'true',
        })
    : undefined

  return {
    settingsBlockCollapsedNote,
    listItemLimit,
    pipelineSecretsKeys,
    pipelineDeletedSecrets,
    pipelineSecretsFormErrorMessage,
    isSettingsBlockCollapsible,
    isBlockExpanded,
    isShowMoreButton,
    settingsBlockTitle,
    clickEditSecretsHandler,
    clickShowMoreButtonHandler,
  }
}

export default usePipelineSecrets
