import Checkbox from '@jetbrains/ring-ui-built/components/checkbox/checkbox'

import type {PipelineId} from '../../../../../../../../../types'
import type {Event} from '../../../../../../services/pipelinesApi.types'
import {EVENT_NAMES_AND_TYPES} from '../../PipelineNotifications.const'

import styles from './CustomNotificationEvents.module.css'

type Props = {
  events: Event[]
  updateEvents: (events: Event[]) => void
  pipelineId?: PipelineId
}

function CustomNotificationEvents({events, updateEvents, pipelineId}: Props) {
  const handleCheckboxChange = (name: string, checked: boolean) => {
    if (!checked && events.filter(item => item.enabled).length === 1) {
      return
    }
    const updatedCheckedItems = events.map(item =>
      item.type === name ? {...item, enabled: checked} : item,
    )

    updateEvents(updatedCheckedItems)
  }

  return (
    <div className={styles.container} key={pipelineId}>
      <div className={styles.checkboxGroup}>
        {events?.map((item, index) => (
          <div key={item.type} className={index === 1 || index === 2 ? styles.offset : ''}>
            <Checkbox
              label={EVENT_NAMES_AND_TYPES[item.type as keyof typeof EVENT_NAMES_AND_TYPES]}
              checked={item.enabled}
              onChange={event => handleCheckboxChange(item.type, event.target.checked)}
            />
          </div>
        ))}
      </div>
    </div>
  )
}

export default CustomNotificationEvents
