import {Suspense} from 'react'

import type {pipelineParentProjectFragment$key} from '../../../hooks/__generated__/pipelineParentProjectFragment.graphql'
import {
  isNotificationsFeatureEnabled,
  isPipelineNotificationsEnabled,
} from '../../../utils/featureToggles'

import PipelineIntegrations from './PipelineIntegrations/PipelineIntegrations'
import PipelineName from './PipelineName/PipelineName'
import PipelineNotifications from './PipelineNotifications/PipelineNotifications'
import PipelineParameters from './PipelineParameters/PipelineParameters'
import PipelineRepositories from './PipelineRepositories/PipelineRepositories'
import PipelineSecrets from './PipelineSecrets/PipelineSecrets'
import PipelineSettingsFooter from './PipelineSettingsFooter/PipelineSettingsFooter'
import PipelineTriggers from './PipelineTriggers/PipelineTriggers'

type Props = {
  pipelineParentProjectKey: pipelineParentProjectFragment$key | null
}

export default function PipelineSettingsSidebar({pipelineParentProjectKey}: Props) {
  return (
    <>
      <PipelineName />
      <PipelineParameters />
      <PipelineSecrets />
      <PipelineTriggers />
      <PipelineRepositories pipelineParentProjectKey={pipelineParentProjectKey} />
      <PipelineIntegrations />
      {isNotificationsFeatureEnabled && isPipelineNotificationsEnabled && <PipelineNotifications />}
      <Suspense>
        <PipelineSettingsFooter pipelineParentProjectKey={pipelineParentProjectKey} />
      </Suspense>
    </>
  )
}
