import ParametersSidebar from '../../../components/ParametersSidebar/ParametersSidebar'
import ParametersControlProvider from '../../../contexts/ParametersControl/ParametersControlContext'

import usePipelineSettingsParametersSidebar from './usePipelineSettingsParametersSidebar'

function PipelineSettingsParametersSidebar() {
  const {
    parameters,
    deletedParameters,
    parametersControlValue,
    parametersFormErrorMessage,
    clickDoneButtonHandler,
    clickAddParameterButtonHandler,
  } = usePipelineSettingsParametersSidebar()

  return (
    <ParametersControlProvider value={parametersControlValue}>
      <ParametersSidebar
        title="Adding parameters"
        parameters={parameters}
        deleted={deletedParameters}
        errorMessage={parametersFormErrorMessage}
        onDone={clickDoneButtonHandler}
        onAdd={clickAddParameterButtonHandler}
      />
    </ParametersControlProvider>
  )
}

export default PipelineSettingsParametersSidebar
