import {produce} from 'immer'

import type {ControlProps, RankedTester} from '@jsonforms/core'
import {rankWith, uiTypeIs} from '@jsonforms/core'
import {withJsonFormsControlProps} from '@jsonforms/react'
import {useCallback, useMemo} from 'react'
import * as React from 'react'

import {useAppDispatch, useAppSelector} from '../../../../../../../../../../../hooks/react-redux'
import InfoMessageContainer from '../../../../../../../../components/InfoMessageContainer/InfoMessageContainer'
import JavaVersionPicker from '../../../../../../../../components/JavaVersionPicker/JavaVersionPicker'
import {usePipelineId} from '../../../../../../../../hooks/pipeline'
import {SuggestionType} from '../../../../../../../../types'
import {
  getDraftJobs,
  getSkippedSuggestions,
  isSuggestionSkipped,
} from '../../../../../../../EditPipelinePage.selectors'
import {suggestions} from '../../../../../../../slices/EditPipelinePage.slices'
import {useJobStepFormContext} from '../../../JobStepFormContext/JobStepFormContext'

import JsonFormHelpDetailsIcon from './JsonFormHelpDetailsIcon'

import styles from './styles.module.css'

function JsonFormJavaVersionPickerControl(props: ControlProps) {
  const {id, handleChange, path, description, label, visible, data} = props
  const {stepIndex, jobId} = useJobStepFormContext()
  const pipelineId = usePipelineId()
  const value = data != null ? data : undefined
  const javaVersionPickerChangeHandler = useCallback(
    (newValue: string | null) => handleChange(path, newValue),
    [handleChange, path],
  )
  const stepList = useAppSelector(state => getDraftJobs(state, pipelineId)?.[jobId]?.steps)
  const currentStep = stepList?.[stepIndex]
  const isRunInDockerSelcted = currentStep?.['docker-image'] != null
  const stepId = `step-${jobId}-${stepIndex + 1}`
  const isDockerSuggestionSkipped = useAppSelector(state =>
    isSuggestionSkipped(state, stepId, SuggestionType.JDK_DOCKER_INFO),
  )
  const skippedSuggestionList = useAppSelector(state => getSkippedSuggestions(state, stepId))
  const isShowJdkDockerSuggestionInfo = isRunInDockerSelcted && !isDockerSuggestionSkipped
  const dispatch = useAppDispatch()
  const infoMessageContainerClickHandler = useCallback(() => {
    dispatch(
      suggestions.actions.skip({
        id: stepId,
        values: produce(skippedSuggestionList ?? [], draft => {
          if (isShowJdkDockerSuggestionInfo) {
            draft.push(SuggestionType.JDK_DOCKER_INFO)
          }
        }),
      }),
    )
  }, [dispatch, isShowJdkDockerSuggestionInfo, skippedSuggestionList, stepId])
  const javaVersionPickerLabel = useMemo(
    () => (
      <React.Fragment>
        {label}
        {description && <JsonFormHelpDetailsIcon>{description}</JsonFormHelpDetailsIcon>}
      </React.Fragment>
    ),
    [description, label],
  )

  if (!visible) {
    return null
  }

  return (
    <div className={styles.container}>
      <JavaVersionPicker
        id={id}
        value={value}
        onChange={javaVersionPickerChangeHandler}
        label={javaVersionPickerLabel}
      />
      {isShowJdkDockerSuggestionInfo && (
        <InfoMessageContainer
          clssName={styles.infoMessage}
          onClick={infoMessageContainerClickHandler}
        >
          {
            'The selected Java version may not match because you selected the container configuration in Docker.'
          }
        </InfoMessageContainer>
      )}
    </div>
  )
}

export const jsonFormJavaVersionPickerControlTester: RankedTester = rankWith(
  1,
  uiTypeIs('JavaVersionPickerControl'),
)

export default withJsonFormsControlProps(JsonFormJavaVersionPickerControl)
