import {isDateControl, isStringControl, isTimeControl, or, rankWith} from '@jsonforms/core'
import type {RankedTester} from '@jsonforms/core'
import {withJsonFormsControlProps} from '@jsonforms/react'

import type {JsonFormTextControlProps} from './JsonFormInputControl/JsonFormInputControl'
import JsonFormInputControl from './JsonFormInputControl/JsonFormInputControl'

import styles from './styles.module.css'

function JsonFormTextControl(props: JsonFormTextControlProps) {
  const isHidden = props.uischema.options?.hide

  if (isHidden) {
    return null
  }

  return (
    <div className={styles.container}>
      <JsonFormInputControl {...props} />
    </div>
  )
}

export const jsonFormTextControlTester: RankedTester = rankWith(
  1,
  or(isDateControl, isStringControl, isTimeControl),
)
export default withJsonFormsControlProps(JsonFormTextControl)
