import Select from '@jetbrains/ring-ui-built/components/select/select'

import EditSettingsForm from '../../../../../components/EditSettingsForm/EditSettingsForm'
import {TriggerSchedulingPolicy} from '../PipelineTriggers.consts'

import {
  currentTimeZone,
  daysOfWeek as daysOfWeekConstant,
  defaultHour,
  defaultMinute,
  timeZoneList,
} from './PipelineTriggerForm.consts'
import usePipelineTriggerForm from './PipelineTriggerForm.hooks'
import type {JobTriggerFormProps} from './PipelineTriggerForm.types'

import styles from './PipelineTriggerForm.module.css'

import Input, {Size} from 'src/components/pages/PipelinesPages/components/Input'

function PipelineTriggerForm({
  hour = defaultHour,
  minute = defaultMinute,
  daysOfWeek = [],
  timezone = currentTimeZone,
  schedulingPolicy = TriggerSchedulingPolicy.DAILY,
  onApply,
  onDelete,
  index,
  isAdd,
}: JobTriggerFormProps) {
  const time = `${hour}:${minute}`
  const {
    handlerTimeZoneChange,
    handlerDayChange,
    handlerTimeChange,
    timeZoneSelected,
    selectedDaysOfWeek,
  } = usePipelineTriggerForm(daysOfWeek, index, timezone, hour, minute, schedulingPolicy)

  return (
    <EditSettingsForm
      onConfirmClick={onApply}
      onDeleteClick={onDelete}
      title={`${isAdd ? 'Adding' : 'Editing'} Schedule`}
    >
      <div className={styles.content}>
        <Select
          label="Select day"
          multiple={{
            selectAll: true,
            selectAllLabel: 'Every day',
          }}
          size={Size.AUTO}
          onChange={handlerDayChange}
          selected={selectedDaysOfWeek}
          data={daysOfWeekConstant}
        />
        <div className={styles.timeSettings}>
          <Input
            label="Time"
            size={Size.AUTO}
            value={time}
            onChange={handlerTimeChange}
            inputClassName={styles.inputTime}
            min="00:00"
            max="23:59"
            type="time"
          />
          <div className={styles.selectTimeZoneWrapper}>
            <Select
              selectedLabel="Time zone"
              label="Select time zone"
              clear
              filter
              className={styles.selectTimeZone}
              size={Size.AUTO}
              onChange={handlerTimeZoneChange}
              selected={timeZoneSelected}
              data={timeZoneList}
            />
          </div>
        </div>
      </div>
    </EditSettingsForm>
  )
}

export default PipelineTriggerForm
