import Select from '@jetbrains/ring-ui-built/components/select/select'
import type * as React from 'react'

import HighlighterTextInput from '../HighlighterTextField/HighlighterTextInput'
import {Size} from '../Input'

import useJavaVersionPicker from './useJavaVersionPicker'

import styles from './JavaVersionPicker.module.css'

type JavaVersionPickerProps = {
  id?: string
  value?: string
  onChange: (value: string | null) => void
  label?: React.ReactNode
}

const inputPlaceholder = 'The path on the agent machine to the Java folder'

function JavaVersionPicker({id, value, label, onChange}: JavaVersionPickerProps) {
  const {
    selectedOption,
    jdkSelectOptions,
    isCustomSelected,
    isLoadingProviderJdk,
    selectChangeHandler,
    inputChangeHandler,
  } = useJavaVersionPicker(onChange, value)
  const jdkHomeInputLabel = 'JDK home path'
  const selectLabel = label ?? 'JDK'
  const selectClassName = isCustomSelected ? styles.selectCustom : null

  return (
    <div className={styles.container}>
      <Select
        id={id}
        loading={isLoadingProviderJdk}
        className={selectClassName}
        selectedLabel={selectLabel}
        label="JDK"
        selected={selectedOption}
        size={Size.FULL}
        data={jdkSelectOptions}
        onSelect={selectChangeHandler}
        compact
      />
      {isCustomSelected && (
        <div className={styles.inputCustom}>
          <HighlighterTextInput
            value={value}
            spellCheck={false}
            aria-label={jdkHomeInputLabel}
            onChange={inputChangeHandler}
            placeholder={inputPlaceholder}
            label={jdkHomeInputLabel}
          />
        </div>
      )}
    </div>
  )
}

export default JavaVersionPicker
