import AddIcon from '@jetbrains/icons/add.svg'
import Button from '@jetbrains/ring-ui-built/components/button/button'

import styles from '../../../components/ParametersSidebar/ParametersSidebar.module.css'
import ParametersSidebarFooter from '../../../components/ParametersSidebar/ParametersSidebarFooter/ParametersSidebarFooter'
import PipelineSecret from '../PipelineSettingsSidebar/PipelineSecrets/PipelineSecret/PipelineSecret'
import SidebarHeader from '../SidebarSlider/Header/SidebarHeader'

import {
  addSecretButtonTitle,
  sidebarHeaderSubTitle,
  sidebarHeaderTitle,
} from './PipelineSettingsSecretsSidebar.const'
import usePipelineSettingsSecretsSidebar from './usePipelineSettingsSecretsSidebar'

function PipelineSettingsSecretsSidebar() {
  const {
    pipelineSecretsKeys,
    pipelineDeletedSecrets,
    isShowBottomAddButton,
    hasParametersFormErrorMessage,
    lastNameInputRef,
    clickAddSecretButtonHandler,
    clickDoneButtonHandler,
  } = usePipelineSettingsSecretsSidebar()

  return (
    <div className={styles.sidebar}>
      <div className={styles.content}>
        <SidebarHeader
          title={sidebarHeaderTitle}
          subTitle={sidebarHeaderSubTitle}
          border
          onClick={clickDoneButtonHandler}
        />
        <div className={styles.continater}>
          <Button
            icon={AddIcon}
            title={addSecretButtonTitle}
            onClick={clickAddSecretButtonHandler}
            className={styles.addParameterButton}
          >
            {addSecretButtonTitle}
          </Button>
          <div className={styles.parameters}>
            {pipelineSecretsKeys.map(key => {
              const isDeleted = pipelineDeletedSecrets?.includes(key)

              return (
                <PipelineSecret
                  isEditMode
                  key={key}
                  originalName={key}
                  inputRef={lastNameInputRef}
                  deleted={isDeleted}
                />
              )
            })}
          </div>
          {isShowBottomAddButton && (
            <Button
              icon={AddIcon}
              title={addSecretButtonTitle}
              onClick={clickAddSecretButtonHandler}
              className={styles.addParameterButton}
            >
              {addSecretButtonTitle}
            </Button>
          )}
        </div>
      </div>
      <ParametersSidebarFooter
        onDone={clickDoneButtonHandler}
        hasErrorMessage={hasParametersFormErrorMessage}
      />
    </div>
  )
}

export default PipelineSettingsSecretsSidebar
