import type {Day} from 'date-fns'
import {isAfter} from 'date-fns'
import {nextDay} from 'date-fns/nextDay'

import {getTimeDifference} from '../../../../../../../../utils/dateTimeUtils'
import {amountDaysOfWeek, weekDaysShort} from '../PipelineTriggerForm/PipelineTriggerForm.consts'

import {dayLabel} from './PipelineTrigger.consts'

const MILLISECONDS_IN_HOUR = 3600000
const HOURS_IN_DAY = 24

export function getNextTriggerDate(
  daysOfWeek: string[],
  hour: number,
  minutes: number,
  isEveryDay: boolean,
  timezone: string,
) {
  const [firstDay] = daysOfWeek
  const currentDate = new Date()
  const currentYear = currentDate.getFullYear()
  const currentMonth = currentDate.getMonth()
  const currentDay = currentDate.getDate()
  const now = new Date()
  const localTime = new Date(
    now.toLocaleString('en-US', {timeZone: new Intl.DateTimeFormat().resolvedOptions().timeZone}),
  )
  const targetTime = new Date(now.toLocaleString('en-US', {timeZone: timezone}))
  const offsetHours = Math.round(
    (targetTime.getTime() - localTime.getTime()) / MILLISECONDS_IN_HOUR,
  )
  const adjustedHour = hour + offsetHours
  const normalizedHour = ((adjustedHour % HOURS_IN_DAY) + HOURS_IN_DAY) % HOURS_IN_DAY
  const triggerDayWeekNumber = weekDaysShort.findIndex(day => day === firstDay)
  const triggerDate = new Date(currentYear, currentMonth, currentDay, normalizedHour, minutes)
  const isToday = triggerDayWeekNumber === currentDate.getDay() && isAfter(triggerDate, currentDate)
  const triggerNextDayNumber = isEveryDay ? currentDate.getDay() + 1 : triggerDayWeekNumber
  const triggerNextDayDate = isToday
    ? triggerDate
    : nextDay(triggerDate, triggerNextDayNumber as Day)

  return getTimeDifference(currentDate, triggerNextDayDate)
}

export function getDaysOfWeekLabel(parameterDaysOfWeek?: string) {
  const daysOfWeek = parameterDaysOfWeek ? parameterDaysOfWeek.split(',') : []
  const isEveryDay = daysOfWeek.length === amountDaysOfWeek || !daysOfWeek.length

  if (isEveryDay) {
    return dayLabel
  } else {
    return daysOfWeek.join(', ')
  }
}

export function getTimeLabel(parameters: Record<string, string>) {
  const {hour: parameterHour = '00', minute: parameterMinute = '00'} = parameters
  return `${parameterHour}:${parameterMinute}`
}
