import type {SelectItem} from '@jetbrains/ring-ui-built/components/select/select'
import {useRef} from 'react'

function useHighlighterTextInput() {
  const richInputRef = useRef<HTMLInputElement | null>(null)
  const selectHighlighterTextFieldTokenHandler = (content: string) => (item: SelectItem) => {
    if (richInputRef.current != null) {
      const contentLength = content.length
      const {selectionEnd} = richInputRef.current
      const itemLabel = `%${item.key}%`
      const selectionStart = richInputRef.current?.selectionStart ?? 0
      const startInsertPosition = selectionStart - contentLength

      richInputRef.current.setRangeText(itemLabel, startInsertPosition, selectionEnd ?? 0, 'end')
      richInputRef.current.selectionStart = startInsertPosition + itemLabel.length
      richInputRef.current.focus()
    }
  }

  return {
    richInputRef,
    selectHighlighterTextFieldTokenHandler,
  }
}

export default useHighlighterTextInput
