import Dropdown from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import PopupMenu from '@jetbrains/ring-ui-built/components/popup-menu/popup-menu'
import Toggle from '@jetbrains/ring-ui-built/components/toggle/toggle'
import isEqual from 'lodash/isEqual'
import {memo, useRef} from 'react'

import SettingsBlock from '../../../../components/SettingsBlock/SettingsBlock'
import usePermissionCanEditPipeline from '../../../../hooks/usePermissionCanEditPipeline'
import {isPullRequestsFeatureEnabled} from '../../../../utils/featureToggles'

import PipelineOnChangesTrigger from './PipelineOnChangesTrigger/PipelineOnChangesTrigger'
import PipelineScheduleTrigger from './PipelineScheduleTrigger/PipelineScheduleTrigger'
import {getDaysOfWeekLabel, getTimeLabel} from './PipelineTrigger/PipelineTrigger.utils'
import {TriggerType} from './PipelineTriggers.consts'
import usePipelineTriggers from './PipelineTriggers.hooks'

import styles from './PipelineTriggers.module.css'

function PipelineTriggers() {
  const {canEditPipeline} = usePermissionCanEditPipeline()
  const {
    triggers,
    sevedTriggers,
    handlerDisabledToggleChange,
    handlerAddJobOnChangesTriggerButtonClick,
    handlerAddJobScheduleTriggerButtonClick,
    handlerTriggerDelete,
  } = usePipelineTriggers()
  const ref = useRef<HTMLDivElement>(null)
  const onAddClick = isPullRequestsFeatureEnabled
    ? () => ref?.current?.click()
    : handlerAddJobScheduleTriggerButtonClick
  const enabledTriggers = triggers?.filter(({disabled}) => !disabled) ?? []
  return (
    <SettingsBlock
      id="triggers"
      collapsible={!!triggers?.length && canEditPipeline}
      title="Auto-Run Pipeline"
      collapsedDefault
      collapsedNote={
        enabledTriggers.length > 0
          ? enabledTriggers
              .map(({type, parameters = {}}) =>
                type === TriggerType.VCS
                  ? 'On new changes'
                  : `every ${getDaysOfWeekLabel(parameters.daysOfWeek)} at ${getTimeLabel(parameters)}`,
              )
              .join(', ')
          : 'Never'
      }
      onAddClick={canEditPipeline ? onAddClick : undefined}
      customActions={
        isPullRequestsFeatureEnabled
          ? anchor => (
              <Dropdown className={styles.addTrigger} anchor={<div ref={ref}>{anchor}</div>}>
                <PopupMenu
                  data={[
                    {
                      label: 'On new changes trigger',
                      onClick: handlerAddJobOnChangesTriggerButtonClick,
                      disabled: triggers?.find(({type}) => type === TriggerType.VCS) != null,
                    },
                    {
                      label: 'Schedule trigger',
                      onClick: handlerAddJobScheduleTriggerButtonClick,
                    },
                  ]}
                  closeOnSelect
                />
              </Dropdown>
            )
          : undefined
      }
    >
      {triggers?.map((trigger, index) => {
        const {disabled, type, parameters, triggerBranches, triggerPullRequests} = trigger
        const sevedTrigger = sevedTriggers[index]
        const isVcsTrigger = type === TriggerType.VCS
        const key = `${index}_${type}`
        const isUnsaved = !isEqual(trigger, sevedTrigger)

        if (isVcsTrigger) {
          return isPullRequestsFeatureEnabled ? (
            <PipelineOnChangesTrigger
              key={key}
              index={index}
              disabled={disabled}
              triggerBranches={triggerBranches}
              triggerPullRequests={triggerPullRequests}
              branchFilter={parameters?.branchFilter}
              onDelete={handlerTriggerDelete(index)}
              onDisabled={handlerDisabledToggleChange(index)}
            />
          ) : (
            <div key={key} className={styles.triggerNewChangesToggleWrapper}>
              <Toggle
                title="On new changes"
                onChange={handlerDisabledToggleChange(index)}
                checked={!disabled}
              >
                {'On new changes'}
              </Toggle>
            </div>
          )
        }

        return (
          <PipelineScheduleTrigger
            onDisabled={handlerDisabledToggleChange(index)}
            onDelete={handlerTriggerDelete(index)}
            key={key}
            index={index}
            parameters={parameters}
            disabled={disabled}
            unsaved={isUnsaved}
          />
        )
      })}
    </SettingsBlock>
  )
}

export default memo(PipelineTriggers)
