import Confirm from '@jetbrains/ring-ui-built/components/confirm/confirm'
import * as React from 'react'

import SettingsBlock from '../../../../components/SettingsBlock/SettingsBlock'
import type {pipelineParentProjectFragment$key} from '../../../../hooks/__generated__/pipelineParentProjectFragment.graphql'
import {isPullRequestsFeatureEnabled} from '../../../../utils/featureToggles'

import {
  pipelineRepositorySettingsBlockId,
  usePipelineRepositories,
} from './PipelineRepositories.hooks'
import PipelineRepository from './PipelineRepository/PipelineRepository'

import styles from './PipelineRepositories.module.css'

type Props = {
  pipelineParentProjectKey: pipelineParentProjectFragment$key | null
}

function PipelineRepositories({pipelineParentProjectKey}: Props) {
  const {
    additionalVcsRoots,
    deletedRepositoriesSet,
    deletedIncompleteRepositoriesSet,
    shortRepositories,
    mainRepository,
    isShowDeleteJobConfirmPopup,
    confirmDeleteJobDescription,
    errorMessage,
    addRepositoryHandler,
    deleteRepositoryHandler,
    restoreRepositoryHandler,
    clickConfirmDeleteJobButtonHandler,
    clickRejectDeleteJobButtonHandler,
    canEditPipeline,
  } = usePipelineRepositories(pipelineParentProjectKey)

  return (
    <React.Fragment>
      <Confirm
        description={confirmDeleteJobDescription}
        confirmLabel="Agree"
        rejectLabel="Cancel"
        show={isShowDeleteJobConfirmPopup}
        onConfirm={clickConfirmDeleteJobButtonHandler}
        onReject={clickRejectDeleteJobButtonHandler}
      />
      <SettingsBlock
        id={pipelineRepositorySettingsBlockId}
        title="Repository"
        collapsible={canEditPipeline}
        collapsedNote={shortRepositories}
        onAddClick={addRepositoryHandler}
      >
        <PipelineRepository
          isRoot
          className={isPullRequestsFeatureEnabled ? undefined : styles.settingsFormContainer}
          branch={mainRepository.branch}
          branchSpec={mainRepository.branchSpecification}
          repositoryUrl={mainRepository.url ?? mainRepository.port}
          vcsProviderType={mainRepository.vcsProviderType}
          vcsName={mainRepository.vcsName}
          name={mainRepository.isExternal ? mainRepository.name : undefined}
          isExternalVcsRoot={mainRepository?.isExternal}
          isStatusPublishingEnabled={mainRepository.isStatusPublishingEnabled}
          trackPullRequests={mainRepository.trackPullRequests}
        />
        {additionalVcsRoots?.map((vcsRoot, index) => {
          const {
            url,
            port,
            branch,
            name,
            vcsName,
            isExternal,
            branchSpecification,
            vcsProviderType,
            isStatusPublishingEnabled,
            trackPullRequests,
          } = vcsRoot
          const isDeleted = deletedRepositoriesSet.has(url)
          const key = `key-${index}`

          if (!url && deletedIncompleteRepositoriesSet.has(index)) {
            return null
          }

          return (
            <PipelineRepository
              index={index}
              key={key}
              name={isExternal ? name : undefined}
              branch={branch}
              branchSpec={branchSpecification}
              vcsName={vcsName}
              vcsProviderType={vcsProviderType}
              repositoryUrl={url ?? port}
              isDeleted={isDeleted}
              isExternalVcsRoot={isExternal}
              isStatusPublishingEnabled={isStatusPublishingEnabled}
              trackPullRequests={trackPullRequests}
              onRestore={restoreRepositoryHandler(url)}
              onDelete={deleteRepositoryHandler(url, index)}
            />
          )
        })}
        {errorMessage && <div className={styles.errorMessage}>{errorMessage}</div>}
      </SettingsBlock>
    </React.Fragment>
  )
}

export default PipelineRepositories
