import Button from '@jetbrains/ring-ui-built/components/button/button'
import ButtonGroup from '@jetbrains/ring-ui-built/components/button-group/button-group'
import {Markdown, LinkOpenPolicy} from '@jetbrains/teamcity-ui/dist/components'
import type {ChangeEvent} from 'react'
import {useState, memo, useCallback} from 'react'

import {useStoredSettingsValue} from '../../../../../../contexts/StoredSettingsValue/StoredSettingsValueContext'
import ToggleableProperty from '../ToggleableProperty/ToggleableProperty'

import {
  DESCRIPTION,
  DOCKER_IMAGE_PROPERTY_NAME,
  DOCKERFILE_PATH_PROPERTY_NAME,
  DOCKERFILE_SOURCE_PROPERTY_NAME,
  LABEL,
} from './JobStepRunInDocker.consts'
import {useStoredDockerData} from './JobStepRunInDocker.hooks'
import type {JobStepRunInDockerProps} from './JobStepRunInDocker.types'
import {getDockerValues} from './JobStepRunInDocker.utils'
import JobStepRunInDockerDockerfile from './JobStepRunInDockerDockerfile/JobStepRunInDockerDockerfile'
import JobStepRunInDockerImageSelect from './JobStepRunInDockerImageSelect/JobStepRunInDockerImageSelect'

import styles from './JobStepRunInDocker.module.css'

import HelpDetails from 'src/components/common/HelpDetails/HelpDetails'
import {StepTypes} from 'src/components/pages/PipelinesPages/types'

function JobStepRunInDocker(props: JobStepRunInDockerProps) {
  const {step, stepIndex, onStepPropertiesChange} = props
  const type = step?.type
  const toggleable = step.type !== StepTypes.NODE
  const {setValueToStoredSettings} = useStoredSettingsValue()
  const {
    storedDockerImageKey,
    storedDockerfileSourceKey,
    storedDockerfilePathKey,
    storedDockerImageValue,
    storedDockerfileSourceValue,
    storedDockerfilePathValue,
  } = useStoredDockerData(type, stepIndex)
  const {dockerImageValue, dockerfileSourceValue, dockerfilePathValue} = getDockerValues(step)
  const defaultToggleChecked =
    dockerImageValue != null || dockerfileSourceValue != null || dockerfilePathValue != null
  const [isToggleChecked, setToggleChecked] = useState(defaultToggleChecked)
  const defaultImageMode = dockerfileSourceValue == null && dockerfilePathValue == null
  const [isImageMode, setImageMode] = useState(defaultImageMode)
  const onToggleImageMode = useCallback(() => {
    setValueToStoredSettings(
      storedDockerfilePathKey,
      dockerfilePathValue ?? storedDockerfilePathValue,
    )
    setValueToStoredSettings(
      storedDockerfileSourceKey,
      dockerfileSourceValue ?? storedDockerfileSourceValue,
    )
    onStepPropertiesChange(stepIndex, [
      {name: DOCKER_IMAGE_PROPERTY_NAME, value: storedDockerImageValue},
      {name: DOCKERFILE_PATH_PROPERTY_NAME, value: null},
      {name: DOCKERFILE_SOURCE_PROPERTY_NAME, value: null},
    ])
    setImageMode(true)
  }, [
    dockerfilePathValue,
    dockerfileSourceValue,
    onStepPropertiesChange,
    setValueToStoredSettings,
    stepIndex,
    storedDockerImageValue,
    storedDockerfilePathKey,
    storedDockerfilePathValue,
    storedDockerfileSourceKey,
    storedDockerfileSourceValue,
  ])

  const onToggleDockerfileMode = useCallback(() => {
    const properties = []

    setValueToStoredSettings(storedDockerImageKey, dockerImageValue ?? storedDockerImageValue)
    properties.push({name: DOCKER_IMAGE_PROPERTY_NAME, value: null})

    if (storedDockerfilePathValue && !storedDockerfileSourceValue) {
      properties.push({name: DOCKERFILE_PATH_PROPERTY_NAME, value: storedDockerfilePathValue})
    } else if (storedDockerfileSourceValue) {
      properties.push({name: DOCKERFILE_SOURCE_PROPERTY_NAME, value: storedDockerfileSourceValue})
    }
    if (properties.length) {
      onStepPropertiesChange(stepIndex, properties)
    }

    setImageMode(false)
  }, [
    dockerImageValue,
    onStepPropertiesChange,
    setValueToStoredSettings,
    stepIndex,
    storedDockerImageKey,
    storedDockerImageValue,
    storedDockerfilePathValue,
    storedDockerfileSourceValue,
  ])

  const renderDetails = (
    <HelpDetails>
      <Markdown className={styles.description} linkOpenPolicy={LinkOpenPolicy.ALL_IN_NEW_TAB}>
        {DESCRIPTION}
      </Markdown>
    </HelpDetails>
  )

  const renderContent = (
    <>
      <ButtonGroup className={styles.modeToggle}>
        <Button
          className={styles.modeToggleButton}
          active={isImageMode}
          onClick={onToggleImageMode}
        >
          {'Docker Image'}
        </Button>
        <Button
          className={styles.modeToggleButton}
          active={!isImageMode}
          onClick={onToggleDockerfileMode}
        >
          {'Dockerfile'}
        </Button>
      </ButtonGroup>

      {isImageMode ? (
        <JobStepRunInDockerImageSelect {...props} />
      ) : (
        <JobStepRunInDockerDockerfile {...props} />
      )}
    </>
  )

  const onToggleChange = useCallback(
    ({currentTarget}: ChangeEvent<HTMLInputElement>) => {
      const {checked} = currentTarget
      const properties = []

      if (!checked) {
        setValueToStoredSettings(
          storedDockerImageKey,
          dockerImageValue ?? storedDockerImageValue ?? null,
        )
        setValueToStoredSettings(
          storedDockerfileSourceKey,
          dockerfileSourceValue ?? storedDockerfileSourceValue ?? null,
        )
        setValueToStoredSettings(
          storedDockerfilePathKey,
          dockerfilePathValue ?? storedDockerfilePathValue ?? null,
        )
        properties.push(
          {name: DOCKER_IMAGE_PROPERTY_NAME, value: null},
          {name: DOCKERFILE_SOURCE_PROPERTY_NAME, value: null},
          {name: DOCKERFILE_PATH_PROPERTY_NAME, value: null},
        )
      } else if (storedDockerImageValue) {
        properties.push({name: DOCKER_IMAGE_PROPERTY_NAME, value: storedDockerImageValue})
      } else if (storedDockerfileSourceValue) {
        properties.push({name: DOCKERFILE_SOURCE_PROPERTY_NAME, value: storedDockerfileSourceValue})
      } else if (storedDockerfilePathValue) {
        properties.push({name: DOCKERFILE_PATH_PROPERTY_NAME, value: storedDockerfilePathValue})
      }

      onStepPropertiesChange(stepIndex, properties)
      setToggleChecked(!isToggleChecked)
    },
    [
      dockerImageValue,
      dockerfilePathValue,
      dockerfileSourceValue,
      isToggleChecked,
      onStepPropertiesChange,
      setValueToStoredSettings,
      stepIndex,
      storedDockerImageKey,
      storedDockerImageValue,
      storedDockerfilePathKey,
      storedDockerfilePathValue,
      storedDockerfileSourceKey,
      storedDockerfileSourceValue,
    ],
  )

  return (
    <div className={styles.container}>
      {toggleable ? (
        <ToggleableProperty
          label={LABEL}
          details={renderDetails}
          onChange={onToggleChange}
          checked={isToggleChecked}
        >
          {renderContent}
        </ToggleableProperty>
      ) : (
        renderContent
      )}
    </div>
  )
}

export default memo(JobStepRunInDocker)
