import searchIcon from '@jetbrains/icons/search.svg'
import LoaderInline from '@jetbrains/ring-ui-built/components/loader-inline/loader-inline'
import {Directions} from '@jetbrains/ring-ui-built/components/popup/popup.consts'
import type {SelectItem} from '@jetbrains/ring-ui-built/components/select/select'
import Select from '@jetbrains/ring-ui-built/components/select/select'
import debounce from 'lodash/debounce'
import {memo, useCallback, useContext, useEffect, useMemo, useRef, useState} from 'react'

import {restApi} from '../../../../../../../../../../services/rest'
import {emptyArray} from '../../../../../../../../../../utils/empty'
import {DisabledContext} from '../../../../../../../contexts/DisabledContext'
import {useDraftStepError} from '../../../../../../EditPipelinePage.hooks'
import {DOCKER_IMAGE_PROPERTY_NAME} from '../JobStepRunInDocker.consts'
import type {JobStepRunInDockerProps} from '../JobStepRunInDocker.types'
import {getDockerValues} from '../JobStepRunInDocker.utils'

import {
  getSelectImagesOptions,
  getSelectTagsOptions,
  parseDockerImage,
} from './JobStepRunInDockerImageSelect.utils'

import styles from './JobStepRunInDockerImageSelect.module.css'

const THROTTLE_TIME = 900

function ErrorMessage() {
  return (
    <div className={styles.errorMessage}>
      {"Something went wrong and we couldn't get the Docker image from hub.docker.com. "}
      {'Сlear the search  and try again'}
    </div>
  )
}

function NotFoundMessage({image}: {image: string}) {
  return (
    <div className={styles.notFoundMessage}>
      {'There are no results for '}
      <span className={styles.notFoundMessageCurrentValue}>{`"${image}" `}</span>
      {'in Docker Hub. '}
      {'Your build will probably fail if you use this image. '}
      {'Choose a different one from Docker Hub list'}
    </div>
  )
}

function JobStepRunInDocker({step, stepIndex, onStepPropertyChange}: JobStepRunInDockerProps) {
  const [isTypingEvent, setTypingEvent] = useState<boolean>(false)
  const filterRef = useRef<HTMLInputElement>(null)
  const {dockerImageValue: value} = getDockerValues(step)
  const [fetchDockerImages, {images, imagesLoading, imagesError}] =
    restApi.endpoints.getDockerImages.useLazyQuery({
      selectFromResult: ({currentData, isFetching, error}) => ({
        images: currentData?.images ?? emptyArray,
        imagesLoading: isFetching,
        imagesError: error,
      }),
    })
  const [fetchDockerTags, {tags, tagsLoading, tagsError}] =
    restApi.endpoints.getDockerTags.useLazyQuery({
      selectFromResult: ({data, isFetching, error}) => ({
        tags: data?.tags ?? emptyArray,
        tagsLoading: isFetching,
        tagsError: error,
      }),
    })
  const {imageName: parsedImageName, tag: parsedTag} = parseDockerImage(value)
  const isTagMode =
    value?.includes(':') && images.find(({name}) => name === parsedImageName) != null
  const isDisabled = useContext(DisabledContext)
  const isLoading = imagesLoading || tagsLoading
  const isError = imagesError != null || tagsError != null
  const isFetchDisabled = parsedImageName == null || parsedImageName.length < 2
  const options = useMemo(() => {
    if (isFetchDisabled || isLoading || isTypingEvent) {
      return emptyArray
    }
    return isTagMode
      ? getSelectTagsOptions(tags, parsedImageName, value)
      : getSelectImagesOptions(images, value)
  }, [images, isFetchDisabled, isLoading, isTypingEvent, isTagMode, parsedImageName, tags, value])

  const hasImage = images.find(({name}) => name === parsedImageName) != null
  const fetchDockerImagesWithThrottle = useMemo(
    () => debounce(fetchDockerImages, THROTTLE_TIME, {leading: false, trailing: true}),
    [fetchDockerImages],
  )
  const fetchDockerTagsWithThrottle = useMemo(
    () => debounce(fetchDockerTags, THROTTLE_TIME, {leading: false, trailing: true}),
    [fetchDockerTags],
  )
  const typingQueryThrottle = useMemo(
    () => debounce(() => setTypingEvent(false), THROTTLE_TIME, {leading: false, trailing: true}),
    [],
  )
  const cencelTypingQueryHandler = useCallback(
    (request?: Promise<unknown>) => {
      if (request) {
        request?.then(typingQueryThrottle)
      } else {
        typingQueryThrottle()
      }
    },
    [typingQueryThrottle],
  )
  const onChangeSelect = useCallback(
    (selected: SelectItem | null) => {
      const {key, selectedLabel} = selected ?? {}

      if (selected == null) {
        onStepPropertyChange(stepIndex, DOCKER_IMAGE_PROPERTY_NAME, '')
      }
      if (typeof key === 'string' && selectedLabel) {
        onStepPropertyChange(stepIndex, DOCKER_IMAGE_PROPERTY_NAME, selectedLabel)
      }
      if (typeof key === 'number' && typeof selected?.label === 'string') {
        onStepPropertyChange(stepIndex, DOCKER_IMAGE_PROPERTY_NAME, selected.label)
        setTypingEvent(true)
      }
    },
    [onStepPropertyChange, stepIndex],
  )
  const renderTopToolbar = () => {
    if (!isLoading && value != null && value !== '') {
      if (isError) {
        return <ErrorMessage />
      }
      if (!isTypingEvent && !isLoading && !options.length) {
        return <NotFoundMessage image={value} />
      }
    }

    return null
  }
  const errorMessage = useDraftStepError({
    name: DOCKER_IMAGE_PROPERTY_NAME,
    stepIndex,
  })
  const selectFilterIcon =
    !!parsedImageName && (isTypingEvent || isLoading) ? LoaderInline : searchIcon
  const selectedOption = useMemo(
    () => ({
      key: `${value}`,
      label: value,
    }),
    [value],
  )

  useEffect(() => {
    if (!isFetchDisabled) {
      const fetchDockerImagesRequest = fetchDockerImagesWithThrottle({q: parsedImageName}) // TODO add the count parameter when it is implemented in the backend

      cencelTypingQueryHandler(fetchDockerImagesRequest)
    }
  }, [
    cencelTypingQueryHandler,
    parsedImageName,
    parsedTag,
    isFetchDisabled,
    fetchDockerImagesWithThrottle,
    typingQueryThrottle,
  ])

  useEffect(() => {
    if (!isFetchDisabled && isTagMode && hasImage) {
      const fetchDockerTagsRequest = fetchDockerTagsWithThrottle({
        image: parsedImageName,
        name: parsedTag ?? '',
      }) // TODO add the count parameter when it is implemented in the backend

      cencelTypingQueryHandler(fetchDockerTagsRequest)
    }
  }, [
    cencelTypingQueryHandler,
    fetchDockerTagsWithThrottle,
    hasImage,
    isFetchDisabled,
    isTagMode,
    parsedImageName,
    parsedTag,
    typingQueryThrottle,
  ])

  return (
    <Select
      className={styles.select}
      type={Select.Type.INPUT}
      directions={[Directions.BOTTOM_LEFT]}
      selected={selectedOption}
      filterRef={filterRef}
      inputPlaceholder={'Search Docker Image'}
      filter={{value, fn: () => true}}
      filterIcon={selectFilterIcon}
      disabled={isDisabled}
      data={options}
      notFoundMessage={''}
      label={''}
      renderTopToolbar={renderTopToolbar}
      onChange={onChangeSelect}
      error={errorMessage ? errorMessage : undefined}
      hideArrow
      allowAny
      clear
    />
  )
}

export default memo(JobStepRunInDocker)
