import {HttpsRepositoryAuthType} from '../../../../../components/VcsAnyRepositoryAuthenticationForm/VcsAnyRepositoryAuthenticationForm.consts'

export function getDefaultVcsAnyRepositoryAuthType(
  username?: string,
  password?: string,
): HttpsRepositoryAuthType {
  if (username) {
    return HttpsRepositoryAuthType.PASSWORD
  }

  if (password && !username) {
    return HttpsRepositoryAuthType.TOKEN
  }

  return HttpsRepositoryAuthType.TOKEN
}

export function getVcsRootPopupSettings() {
  const windowPercent = 0.8
  const width = window.innerWidth * windowPercent
  const height = window.innerHeight * windowPercent
  const left = (window.innerWidth - width) / 2
  const top = (window.innerHeight - height) / 2

  return `scrollbars=no,resizable=no,status=no,location=no,toolbar=no,menubar=no,width=${width},height=${height},left=${left},top=${top}`
}
