import {VcsProviderType} from '../../../../../services/pipelinesApi.types'

export function isStatusPublishingAvailable(vcsProviderType?: VcsProviderType | null) {
  if (!vcsProviderType) {
    return false
  }

  return ![VcsProviderType.ANY, VcsProviderType.EXISTING_VCS_ROOT].includes(vcsProviderType)
}
