import Button from '@jetbrains/ring-ui-built/components/button/button'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'

import SidebarFooterContainer from '../../../SidebarFooterContainer/SidebarFooterContainer'

import styles from './PipelineRepositorySidebarFooter.module.css'

type PipelineRepositorySidebarFooterProps = {
  onDone?: () => void
  onCancel?: () => void
  onDelete?: () => void
  errorMessage?: string | null
  doneButtonLabel?: string
}

function PipelineRepositorySidebarFooter({
  onDone,
  onCancel,
  onDelete,
  doneButtonLabel,
  errorMessage,
}: PipelineRepositorySidebarFooterProps) {
  const deleteButtonLabel = 'Delete repository'
  const hasErrorMessage = Boolean(errorMessage)
  const isDisabledButttonDone = hasErrorMessage || !onDone

  return (
    <SidebarFooterContainer>
      {errorMessage}
      <div className={styles.leftSide}>
        <Button primary disabled={isDisabledButttonDone} onClick={onDone}>
          {doneButtonLabel}
        </Button>
        <Button onClick={onCancel}>{'Cancel'}</Button>
      </div>
      {onDelete && (
        <IconButton title={deleteButtonLabel} icon={'trash'} onClick={onDelete} danger>
          {deleteButtonLabel}
        </IconButton>
      )}
    </SidebarFooterContainer>
  )
}

export default PipelineRepositorySidebarFooter
