import AddIcon from '@jetbrains/icons/add.svg'
import Button from '@jetbrains/ring-ui-built/components/button/button'
import Checkbox from '@jetbrains/ring-ui-built/components/checkbox/checkbox'
import classNames from 'classnames'
import {Suspense} from 'react'

import Actions from '../../../../components/Actions/Actions'
import HighlighterTextInput from '../../../../components/HighlighterTextField/HighlighterTextInput'
import HighlighterTextView from '../../../../components/HighlighterTextField/HighlighterTextView'
import ParametersSidebarFooter from '../../../../components/ParametersSidebar/ParametersSidebarFooter/ParametersSidebarFooter'
import type {pipelineHeadBuildTypeFragment$key} from '../../../../hooks/__generated__/pipelineHeadBuildTypeFragment.graphql'
import {useJobId} from '../../../EditPipelinePage.hooks'
import SidebarHeader from '../../SidebarSlider/Header/SidebarHeader'
import JobDirectoryPopup from '../JobDirectory/JobDirectoryPopup'
import {filesPublicationPlaceholder} from '../JobFilesPublication/JobFilesPublication.consts'

import useJobFilesPublicationSidebar from './useJobFilesPublicationSidebar'

import styles from './JobFilesPublicationSidebar.module.css'

type JobFilesPublicationSidebarProps = {
  pipelineHeadBuildTypeKey: pipelineHeadBuildTypeFragment$key | null
}

function JobFilesPublicationSidebar({pipelineHeadBuildTypeKey}: JobFilesPublicationSidebarProps) {
  const jobId = useJobId()!
  const {
    lastInputRef,
    filesPublication,
    isShowBottomAddButton,
    getIsKeyDelete,
    clickDoneFormButtonHandler,
    clickAddFilePublicationButtonHandler,
    clickRestoreFilePublicationHandler,
    clickDeleteFilePublicationHandler,
    changeFilePublicationInputHandler,
    changeFilePublicationSharedHandler,
    changeFilePublicationArtifactHandler,
    selectJobDirectoryHandler,
  } = useJobFilesPublicationSidebar()

  return (
    <div className={styles.sidebar}>
      <div className={styles.content}>
        <SidebarHeader
          title="Output files"
          subTitle="Use the * wildcard to include all files in the current directory"
          border
          onClick={clickDoneFormButtonHandler}
        />
        <div className={styles.continater}>
          <Button
            icon={AddIcon}
            title="Add parameter"
            onClick={clickAddFilePublicationButtonHandler}
            className={styles.addParameterButton}
          >
            {'Add file'}
          </Button>
          <div className={styles.notice}>
            {
              'Select a file or a folder or manually enter its relative path. Select “Shared file” to share the file with downstream Jobs, “Artifact” to publish it without sharing.'
            }
          </div>
          <div className={styles.parameters}>
            {filesPublication.map((file, index) => {
              const key = `key_${index}`
              const isFileDeleted = getIsKeyDelete(index)
              const className = classNames(styles.file, {
                [styles.fileDeleted]: isFileDeleted,
              })

              return (
                <div key={key} className={styles.fileAndCheckboxes}>
                  <div className={className}>
                    {isFileDeleted ? (
                      <HighlighterTextView value={file.path} />
                    ) : (
                      <>
                        <HighlighterTextInput
                          ref={lastInputRef}
                          value={file.path}
                          onChange={changeFilePublicationInputHandler(index)}
                          placeholder={filesPublicationPlaceholder}
                          aria-label={'Publish Files'}
                          autoComplete="off"
                          spellCheck={false}
                        />
                      </>
                    )}
                    <div className={styles.actions}>
                      {!isFileDeleted && (
                        <Suspense>
                          <JobDirectoryPopup
                            jobId={jobId}
                            pipelineHeadBuildTypeKey={pipelineHeadBuildTypeKey}
                            onSelect={selectJobDirectoryHandler(index)}
                          />
                        </Suspense>
                      )}
                      <Actions
                        className={styles.parameterActions}
                        deleted={isFileDeleted}
                        onRestoreClick={clickRestoreFilePublicationHandler(index)}
                        onDeleteClick={clickDeleteFilePublicationHandler(index)}
                      />
                    </div>
                  </div>
                  <div className={styles.checkboxRow}>
                    <Checkbox
                      label={'Shared file'}
                      checked={file['share-with-jobs']}
                      onChange={changeFilePublicationSharedHandler(index)}
                    />
                    <Checkbox
                      label={'Artifact'}
                      checked={file['publish-artifact']}
                      onChange={changeFilePublicationArtifactHandler(index)}
                    />
                  </div>
                </div>
              )
            })}
          </div>
          {isShowBottomAddButton && (
            <Button
              icon={AddIcon}
              title="Add parameter"
              onClick={clickAddFilePublicationButtonHandler}
              className={styles.addParameterButton}
            >
              {'Add file'}
            </Button>
          )}
        </div>
      </div>
      <ParametersSidebarFooter onDone={clickDoneFormButtonHandler} />
    </div>
  )
}

export default JobFilesPublicationSidebar
