import {useCallback, useEffect, useRef} from 'react'
import {useSearchParams} from 'react-router'

import {useAppDispatch} from '../../../../../../hooks/react-redux'
import {maxLimitParamatersAmount} from '../../../components/ParametersSidebar/ParametersSidebar.consts'
import {usePipelineId} from '../../../hooks/pipeline'
import {validateAllForms} from '../../EditPipelinePage.actions'
import {useApplySecrets} from '../../EditPipelinePage.hooks'
import {
  collapsedBlocks,
  pipelineDraft,
  pipelineSecrets as pipelineSecretsSlice,
} from '../../slices/EditPipelinePage.slices'
import {FormType} from '../../slices/EditPipelinePage.slices.types'
import {secretsSettingsBlockId} from '../PipelineSettingsSidebar/PipelineSecrets/PipelineSecrets'
import usePipelineSecretsStore from '../PipelineSettingsSidebar/PipelineSecrets/usePipelineSecretsStore'
import {sideBarNavigatiobSearchParam} from '../SettingsSidebarContent.const'

const waitSliderAnimnationTime = 300

function usePipelineSettingsSecretsSidebar() {
  const {
    pipelineSecrets,
    pipelineSecretsLength,
    pipelineSecretsKeys,
    pipelineSecretsKeysLength,
    pipelineAddedSecrets,
    pipelineRenamedSecrets,
    pipelineDeletedSecrets,
    clearAddedSecretsHandler,
    pipelineSecretsFormErrorMessage,
  } = usePipelineSecretsStore()
  const dispatch = useAppDispatch()
  const pipelineId = usePipelineId()
  const applySecrets = useApplySecrets()
  const [searchParams, setSearchParams] = useSearchParams()
  const lastNameInputRef = useRef<HTMLTextAreaElement>(null)
  const isShowBottomAddButton = pipelineSecretsLength > maxLimitParamatersAmount
  const hasParametersFormErrorMessage = !!pipelineSecretsFormErrorMessage
  const sidebarNavigationBackHandler = useCallback(() => {
    searchParams.delete(sideBarNavigatiobSearchParam.secrets)

    const searchParamsObject = Object.fromEntries(searchParams.entries())

    setSearchParams(searchParamsObject)
  }, [searchParams, setSearchParams])
  const clickDoneButtonHandler = useCallback(async () => {
    const secretsName = Object.values(pipelineRenamedSecrets).join('')
    const secretsValue = Object.values(pipelineSecrets).join('')
    const isFormNotFiled = !secretsName && !secretsValue

    if (isFormNotFiled) {
      clearAddedSecretsHandler()
      sidebarNavigationBackHandler()
    } else {
      await applySecrets(savedName => pipelineAddedSecrets[savedName] === true)

      const isValid = dispatch(
        validateAllForms(
          pipelineId,
          form => form.type === FormType.SECRET && pipelineAddedSecrets?.[form.id!] === true,
        ),
      )
      if (isValid) {
        dispatch(pipelineDraft.actions.applyAddedSecrets(pipelineId))
        Object.keys(pipelineSecrets).forEach(key =>
          dispatch(pipelineSecretsSlice.actions.unset({pipelineId, savedName: key})),
        )
        sidebarNavigationBackHandler()
      }
    }
  }, [
    pipelineRenamedSecrets,
    pipelineSecrets,
    clearAddedSecretsHandler,
    sidebarNavigationBackHandler,
    applySecrets,
    dispatch,
    pipelineId,
    pipelineAddedSecrets,
  ])
  const clickAddSecretButtonHandler = useCallback(() => {
    dispatch(pipelineDraft.actions.addSecret(pipelineId))
    dispatch(collapsedBlocks.actions.toggle({id: secretsSettingsBlockId, collapsed: false}))

    setTimeout(() => {
      const lastNameInput = lastNameInputRef.current
      const valueLength = lastNameInput?.value.length ?? 0

      lastNameInput?.focus()
      lastNameInput?.setSelectionRange(valueLength, valueLength)
    }, waitSliderAnimnationTime)
  }, [dispatch, pipelineId])

  useEffect(() => {
    if (!pipelineSecretsKeysLength) {
      clickAddSecretButtonHandler()
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  return {
    pipelineSecrets,
    pipelineSecretsKeys,
    pipelineDeletedSecrets,
    isShowBottomAddButton,
    hasParametersFormErrorMessage,
    lastNameInputRef,
    clickAddSecretButtonHandler,
    clickDoneButtonHandler,
  }
}

export default usePipelineSettingsSecretsSidebar
