import {memo, Suspense} from 'react'

import EditSettingsForm from '../../../../../components/EditSettingsForm/EditSettingsForm'
import PipelineSecretFormFieldset from '../PipelineSecretFormFieldset/PipelineSecretFormFieldset'
import usePipelineSecretControl from '../usePipelineSecretControl'

import styles from './PipelineSecretForm.module.css'

type PipelineSecretFormProps = {
  onDelete?: () => void
  savedName?: string
  inputRef?: React.RefObject<HTMLTextAreaElement>
}
function PipelineSecretForm({savedName = '', inputRef, onDelete}: PipelineSecretFormProps) {
  const {isFormInvalid} = usePipelineSecretControl(savedName)

  return (
    <EditSettingsForm
      inline
      settingsClassName={styles.pipelineSecretForm}
      onDeleteClick={onDelete}
      disabled={Boolean(isFormInvalid)}
    >
      <Suspense>
        <PipelineSecretFormFieldset inputRef={inputRef} savedName={savedName} />
      </Suspense>
    </EditSettingsForm>
  )
}

export default memo(PipelineSecretForm)
