import PipelineParametersSettingsBlock from '../../../../components/PipelineParametersSettingsBlock/PipelineParametersSettingsBlock'
import ParametersControlProvider from '../../../../contexts/ParametersControl/ParametersControlContext'

import {settingsBlockId} from './PipelineParameters.consts'
import usePipelineParameters from './usePipelineParameters'

function PipelineParameters() {
  const {
    summaryNote,
    parameters,
    deletedParameters,
    settingsBlockTitle,
    isSettingsBlockCollapsible,
    parametersFormErrorMessage,
    parametersControlValue,
    clickEditParametersHandler,
  } = usePipelineParameters()

  return (
    <ParametersControlProvider value={parametersControlValue}>
      <PipelineParametersSettingsBlock
        title={settingsBlockTitle}
        blockId={settingsBlockId}
        collapsible={isSettingsBlockCollapsible}
        parameters={parameters}
        collapsedNote={summaryNote}
        onEdit={clickEditParametersHandler}
        error={parametersFormErrorMessage}
        deleted={deletedParameters}
      />
    </ParametersControlProvider>
  )
}

export default PipelineParameters
