import type {ControlProps, RankedTester} from '@jsonforms/core'
import {rankWith, uiTypeIs} from '@jsonforms/core'
import {withJsonFormsControlProps} from '@jsonforms/react'
import {useCallback} from 'react'

import {useJobStepFormContext} from '../../../JobStepFormContext/JobStepFormContext'
import JobStepRunInDocker from '../../../JobStepRunInDocker/JobStepRunInDocker'

import styles from './styles.module.css'

function JsonFormDockerImageControl({visible, handleChange}: ControlProps) {
  const {stepIndex, step} = useJobStepFormContext()
  const stepPropertiesChangeHandler = useCallback(
    (_: number, properties: Array<{name: string; value: string | null}>) => {
      properties.forEach(({name, value}) => handleChange(name, value))
    },
    [handleChange],
  )
  const stepPropertyChangeHandler = useCallback(
    (_: number, name: string, value: string | null) => handleChange(name, value),
    [handleChange],
  )

  if (!visible) {
    return null
  }

  return (
    <div className={styles.container}>
      <JobStepRunInDocker
        step={step}
        stepIndex={stepIndex}
        onStepPropertiesChange={stepPropertiesChangeHandler}
        onStepPropertyChange={stepPropertyChangeHandler}
      />
    </div>
  )
}

export const jsonFormDockerImageControlTester: RankedTester = rankWith(
  1,
  uiTypeIs('DockerImageControl'),
)

export default withJsonFormsControlProps(JsonFormDockerImageControl)
