import InfoIcon from '@jetbrains/icons/info.svg'
import Dropdown from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import {ControlsHeight} from '@jetbrains/ring-ui-built/components/global/controls-height'
import {Size} from '@jetbrains/ring-ui-built/components/input/input'
import type {ToggleTagParams} from '@jetbrains/ring-ui-built/components/tags-input/tags-input'
import TagsInput from '@jetbrains/ring-ui-built/components/tags-input/tags-input'
import type {TagType} from '@jetbrains/ring-ui-built/components/tags-list/tags-list'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import {useCallback, useEffect, useRef, useState} from 'react'

import Popup from '../../../../../../../../common/Popup/Popup.lazy'

import styles from './NotificationsUsersSelect.module.css'

type Props = {
  label: string
  onChange: (values: string[]) => void
  className?: string
  buttonClassName?: string
  popupClassName?: string
  selectedEmails: string[]
}

function NotificationsUsersSelect(props: Props) {
  const parentRef = useRef<HTMLDivElement | null>(null)
  const [error, setError] = useState<string | null>(null)

  const [selectedItems, setSelectedItems] = useState<TagType[]>(
    props.selectedEmails.map(email => ({key: email, label: email})),
  )
  useEffect(() => {
    setSelectedItems(props.selectedEmails.map(email => ({key: email, label: email})))
  }, [props.selectedEmails])

  const onChangeSelect = useCallback(
    (selected: TagType[]) => {
      setSelectedItems(selected)
      props.onChange(selected.map(s => s.key as string))
    },
    [props],
  )

  return (
    <div className={styles.wrapper}>
      {props.label && (
        <label className={classNames(styles.label)}>
          {props.label}{' '}
          <Dropdown
            hoverMode
            hoverShowTimeOut={0}
            anchor={<IconButton aria-labelledby="what-label" icon={InfoIcon} title="" />}
          >
            <Popup className={styles.infoPopup}>
              {
                'We recommend using a service email for\ngeneral notifications to avoid overwhelming\npersonal inboxes with updates. Users who\nwish to keep a closer eye on a project can\nalways set up personal notification rules on\nthe Pipelines page.'
              }
              <br />
              {''}
            </Popup>
          </Dropdown>
        </label>
      )}
      <div
        className={styles.wrapperContainer}
        ref={parentRef}
        role="button"
        tabIndex={0}
        aria-label="Clear error"
        onKeyDown={() => {
          setError(null)
        }}
      >
        <TagsInput
          notFoundMessage=""
          height={ControlsHeight.M}
          allowAddNewTags
          onAddTag={({tag}) => {
            /* It ensures the email has:
        - Alphanumeric characters or allowed symbols (`[[\w-.]]`) before the `@`
        - A valid domain structure with at least one dot after the `@` (`[([\w-]+\.)]`)
        - A domain suffix with a length longer than 2 characters (`[[\w-]{2,}])
             */
            if (/^[\w-.]+@([\w-]+\.)+[\w-]{2,}$/.test(tag.label as string)) {
              onChangeSelect([...selectedItems, tag])
              setError(null)
            } else {
              setError(`Invalid email: ${tag.label}`)
              onChangeSelect(selectedItems?.filter(item => item.label !== tag))
            }
          }}
          placeholder="Add email in format email@example.com"
          tags={selectedItems as TagType[]}
          size={Size.FULL}
          onRemoveTag={(params: ToggleTagParams) => {
            onChangeSelect(selectedItems?.filter(item => item.label !== params.tag.label))
          }}
        />
        {error && <div className={styles.errorText}>{error}</div>}
      </div>
    </div>
  )
}

export default NotificationsUsersSelect
