import classnames from 'classnames'

import {vcsStorageSwitchLabel} from '../../../../../../components/ConfigurationStorage/ConfigurationStorageSwitch'

import useConfigurationStorageSection from './useConfigurationStorageSection'

type ConfigurationStorageSectionPreviewProps = {
  className?: string
}

function ConfigurationStorageSectionPreview({className}: ConfigurationStorageSectionPreviewProps) {
  const {storedInRepo} = useConfigurationStorageSection()
  const containerClassNames = classnames(className)
  const storeLabel = storedInRepo
    ? vcsStorageSwitchLabel.storedInRepo
    : vcsStorageSwitchLabel.storedOnServer

  return (
    <div className={containerClassNames}>{`Store the configuration YAML file: ${storeLabel}`}</div>
  )
}
export default ConfigurationStorageSectionPreview
