import {useCallback, useMemo, useRef} from 'react'

import {useJobId} from '../../EditPipelinePage/EditPipelinePage.hooks'
import {usePipelineId} from '../../hooks/pipeline'

import type {SettingsValueStore, SettingsStoreValue} from './StoredSettingsValueContext.types'

function useStoredSettingsValueProvider() {
  const jobId = useJobId()
  const pipelineId = usePipelineId()
  const rootKey = jobId ?? pipelineId
  const store = useRef<SettingsValueStore>({})
  const setValueToStoredSettings = useCallback(
    (key: string, value: SettingsStoreValue) => {
      store.current[`${rootKey}_${key}`] = value
    },
    [rootKey],
  )
  const getValueFromStoredSettings = useCallback(
    (key: string) => store.current[`${rootKey}_${key}`],
    [rootKey],
  )
  const storeValue = useMemo(
    () => ({
      setValueToStoredSettings,
      getValueFromStoredSettings,
    }),
    [getValueFromStoredSettings, setValueToStoredSettings],
  )

  return {
    storeValue,
  }
}

export default useStoredSettingsValueProvider
