import {useCallback, useMemo} from 'react'
import {useSearchParams} from 'react-router'

import {HighlightSpotId} from '../../../../components/HighlighterTextField/HighlighterTextFieldContext.types'
import {ParameterInputPrefix} from '../../../../contexts/ParametersControl/ParametersControlContext.const'
import {sideBarNavigatiobSearchParam} from '../../SettingsSidebarContent.const'
import useJobParametersStore from '../JobParameters/useJobParametersStore'

function useJobParametersSidebar() {
  const {
    jobParameters,
    deletedJobParameters,
    renamedJobParameters,
    formSpotParamId,
    formErrorSpotId,
    jobParametersFormErrorMessage,
    getIsJobParametersValid,
    changeNameHandler,
    changeValueHandler,
    restoreParametersHandler,
    clearAddedJobParametersHandler,
    deleteParametersHandler,
    confirmParametersHandler,
    jobParameterMultiplyConfirmHandler,
    addJobParameterHandler,
  } = useJobParametersStore()
  const parametersControlValue = useMemo(
    () => ({
      formSpotParamId,
      formErrorSpotId,
      parameters: jobParameters,
      renamedParameters: renamedJobParameters,
      valueHighlightSpotId: HighlightSpotId.PARAMETER,
      onNameChange: changeNameHandler,
      onValueChange: changeValueHandler,
      onRestore: restoreParametersHandler,
      onDelete: deleteParametersHandler,
      onConfirm: confirmParametersHandler,
    }),
    [
      changeNameHandler,
      changeValueHandler,
      confirmParametersHandler,
      deleteParametersHandler,
      formErrorSpotId,
      formSpotParamId,
      jobParameters,
      renamedJobParameters,
      restoreParametersHandler,
    ],
  )
  const clickAddParameterButtonHandler = useCallback(() => {
    addJobParameterHandler(ParameterInputPrefix.ENV)
  }, [addJobParameterHandler])
  const [searchParams, setSearchParams] = useSearchParams()
  const sidebarNavigationBackHandler = useCallback(() => {
    searchParams.delete(sideBarNavigatiobSearchParam.parameters)

    const searchParamsObject = Object.fromEntries(searchParams.entries())

    setSearchParams(searchParamsObject)
  }, [searchParams, setSearchParams])
  const clickDoneButtonHandler = useCallback(() => {
    const parametersName = Object.values(renamedJobParameters)
      .join('')
      .replaceAll(ParameterInputPrefix.ENV, '')
    const parametersValue = Object.values(jobParameters).join('')
    const isFormNotFiled = !parametersName && !parametersValue

    if (isFormNotFiled) {
      clearAddedJobParametersHandler()
      sidebarNavigationBackHandler()
    } else {
      const isValid = getIsJobParametersValid()

      if (isValid) {
        jobParameterMultiplyConfirmHandler()
        sidebarNavigationBackHandler()
      }
    }
  }, [
    renamedJobParameters,
    jobParameters,
    clearAddedJobParametersHandler,
    sidebarNavigationBackHandler,
    getIsJobParametersValid,
    jobParameterMultiplyConfirmHandler,
  ])

  return {
    jobParameters,
    deletedJobParameters,
    parametersControlValue,
    jobParametersFormErrorMessage,
    clickDoneButtonHandler,
    clickAddParameterButtonHandler,
  }
}

export default useJobParametersSidebar
