import {createContext, useContext, useMemo} from 'react'

type JsonFormInputControlControlContextProps = {
  onBlur?: () => void
  onFocus?: () => void
  onInitRef?: (ref: HTMLInputElement | HTMLTextAreaElement) => void
}

const JsonFormInputControlControlContext = createContext<JsonFormInputControlControlContextProps>(
  {} as JsonFormInputControlControlContextProps,
)

export const useJobStepFormInputControlContext = () =>
  useContext(JsonFormInputControlControlContext)

type JsonFormInputControlControlProviderProps = {
  children: React.ReactNode
} & JsonFormInputControlControlContextProps

function JsonFormInputControlControlProvider({
  children,
  onBlur,
  onFocus,
  onInitRef,
}: JsonFormInputControlControlProviderProps) {
  const valueProvider = useMemo(
    () => ({
      onBlur,
      onFocus,
      onInitRef,
    }),
    [onBlur, onFocus, onInitRef],
  )

  return (
    <JsonFormInputControlControlContext.Provider value={valueProvider}>
      {children}
    </JsonFormInputControlControlContext.Provider>
  )
}

export default JsonFormInputControlControlProvider
