import classNames from 'classnames'
import type {ReactNode} from 'react'
import {useRef, memo} from 'react'
import {Transition} from 'react-transition-group'
import type {TransitionProps} from 'react-transition-group/Transition'

import styles from './SidebarSlider.module.css'

type SettingsSidebarSliderProps = {
  children: ReactNode
  triggerAnimationStart?: boolean
} & Partial<TransitionProps>

function SidebarSliderTransition({
  children,
  triggerAnimationStart,
  ...props
}: SettingsSidebarSliderProps) {
  const timeoutDuration = {appear: 0, enter: 0, exit: 400}
  const transitionRef = useRef<HTMLDivElement>(null)

  return (
    <Transition
      nodeRef={transitionRef}
      unmountOnExit
      mountOnEnter
      in={triggerAnimationStart}
      timeout={timeoutDuration}
      {...props}
    >
      {transitionStatus => {
        const animationClassName =
          transitionStatus in styles ? styles[transitionStatus as keyof typeof styles] : null
        const sliderClassNames = classNames(styles.container, animationClassName)

        return (
          <div ref={transitionRef} className={sliderClassNames}>
            {children}
          </div>
        )
      }}
    </Transition>
  )
}

export default memo(SidebarSliderTransition)
