import Toggle from '@jetbrains/ring-ui-built/components/toggle/toggle'
import classNames from 'classnames'
import {memo, useCallback} from 'react'

import Actions from '../../../../../components/Actions/Actions'
import {isPullRequestsFeatureEnabled} from '../../../../../utils/featureToggles'
import PipelineTrigger from '../PipelineTrigger/PipelineTrigger'
import PipelineTriggerForm from '../PipelineTriggerForm/PipelineTriggerForm'

import usePipelineScheduleTrigger from './PipelineScheduleTrigger.hooks'

import styles from './PipelineScheduleTrigger.module.css'

type Props = {
  index: number
  parameters?: Record<string, string>
  disabled?: boolean
  unsaved?: boolean
  onDisabled: (event: React.ChangeEvent<HTMLInputElement>) => void
  onDelete: () => void
}

function PipelineScheduleTrigger({parameters = {}, index, disabled, onDisabled, onDelete}: Props) {
  const {
    isShowTriggerForm,
    daysOfWeekLabel,
    detailWhenTriggerLabel,
    timeLabel,
    timezone,
    parameterHour,
    parameterMinute,
    daysOfWeek,
    schedulingPolicy,
    triggerPolicyLabel,
    handlerEditButtonClick,
    handlerJobTriggerFormClose,
    isAdd,
  } = usePipelineScheduleTrigger(parameters, index)

  const handleDelete = useCallback(() => {
    onDelete?.()
    handlerJobTriggerFormClose()
  }, [handlerJobTriggerFormClose, onDelete])

  const triggerDetailsClassNames = classNames(styles.triggerDetail, {
    [styles.triggerDetailDisabled]: disabled,
  })

  if (isPullRequestsFeatureEnabled) {
    return (
      <PipelineTrigger
        label={`${triggerPolicyLabel}: every ${daysOfWeekLabel} at ${timeLabel} (${timezone})`}
        details={detailWhenTriggerLabel}
        onDelete={onDelete}
        onEdit={handlerEditButtonClick}
        onDisabled={onDisabled}
        disabled={disabled}
      />
    )
  }

  return (
    <div className={styles.trigger}>
      {isShowTriggerForm ? (
        <PipelineTriggerForm
          timezone={timezone}
          hour={parameterHour}
          minute={parameterMinute}
          daysOfWeek={daysOfWeek}
          schedulingPolicy={schedulingPolicy}
          onApply={handlerJobTriggerFormClose}
          onDelete={handleDelete}
          index={index}
          isAdd={isAdd}
        />
      ) : (
        <div className={styles.triggerTime}>
          <Toggle onChange={onDisabled} className={styles.triggerToggle} checked={!disabled}>
            {`${triggerPolicyLabel}: every ${daysOfWeekLabel} at ${timeLabel} (${timezone})`}
            <div className={triggerDetailsClassNames}>{detailWhenTriggerLabel}</div>
          </Toggle>
          <Actions
            className={styles.triggerActions}
            onDeleteClick={onDelete}
            onEditClick={handlerEditButtonClick}
          />
        </div>
      )}
    </div>
  )
}

export default memo(PipelineScheduleTrigger)
