import Input, {Size} from '@jetbrains/ring-ui-built/components/input/input'
import Link from '@jetbrains/ring-ui-built/components/link/link'
import {Suspense, useId} from 'react'

import type {PipelineId, ProjectId} from '../../../../../../../../types'
import Alert from '../../../../../../../common/Alert/Alert'
import BranchSpecificationSelect from '../../../../../components/BranchSpecificationSelect/BranchSpecificationSelect'
import type {ConfigurationStorageSwitchFragment$key} from '../../../../../components/ConfigurationStorage/__generated__/ConfigurationStorageSwitchFragment.graphql'
import DefaultBranchSelect from '../../../../../components/DefaultBranchSelect/DefaultBranchSelect'
import ExistingVcsRootSelect from '../../../../../components/ExistingVcsRootSelect/ExistingVcsRootSelect'
import AdvancedIntegrationSection from '../../../../../components/PipelineForm/AdvancedIntegrationSection/AdvancedIntegrationSection'
import ExistingVcsRootForm from '../../../../../components/PipelineForm/ExistingVcsRootForm/ExistingVcsRootForm'
import RepositoryEditUrl from '../../../../../components/PipelineForm/RepositoryEditUrl/RepositoryEditUrl'
import RepositoryNameInput from '../../../../../components/PipelineForm/RepositoryNameInput/RepositoryNameInput'
import PublishStatusToggle from '../../../../../components/PublishStatusToggle/PublishStatusToggle'
import RepositorySelect from '../../../../../components/RepositorySelect/RepositorySelect'
import SlideInOutAnimation from '../../../../../components/SlideInOutAnimation/SlideInOutAnimation'
import VcsAnyRepositoryAuthenticationForm from '../../../../../components/VcsAnyRepositoryAuthenticationForm/VcsAnyRepositoryAuthenticationForm'
import type {ProtocolVcsRepository} from '../../../../../components/VcsAnyRepositoryAuthenticationForm/VcsAnyRepositoryAuthenticationForm.consts'
import VcsLoginLink from '../../../../../components/VcsLoginLink/VcsLoginLink'
import VcsProviderIcon from '../../../../../components/VcsProviderIcon/VcsProviderIcon'
import VcsProviderSelect from '../../../../../components/VcsProviderSelect/VcsProviderSelect'
import {VcsProviderType} from '../../../../../services/pipelinesApi.types'
import {isStatusPublishingFeatureEnabled} from '../../../../../utils/featureToggles'
import {getExternalVcsRootEditUrl} from '../../../../../utils/vcs'
import SidebarHeader from '../../../SidebarSlider/Header/SidebarHeader'
import type {PipelineBaseRepository} from '../PipelineRepositories.types'
import PipelineRepositorySidebarFooter from '../PipelineRepositorySidebarFooter/PipelineRepositorySidebarFooter'

import ConfigurationStorageSection from './ConfigurationStorageSection/ConfigurationStorageSection'
import {DISABLE_REASON_FOR_MAIN_ROOT} from './NewPipelineRepositoryForm.consts'
import {useNewPipelineRepositoryForm} from './NewPipelineRepositoryForm.hooks'

import styles from './NewPipelineRepositoryForm.module.css'

type Props = {
  className?: string
  projectId?: ProjectId
  pipelineId?: PipelineId
  repositoryUrl: string
  name?: string
  vcsName?: string
  createdRepositories?: Set<string>
  vcsProviderType?: VcsProviderType | null
  branch?: string
  branchSpec?: string | null
  formId?: string | number
  username?: string
  password?: string
  vcsProtocol?: ProtocolVcsRepository
  isRoot?: boolean
  vcsRootId?: string
  isExternal?: boolean
  isCreateMode?: boolean
  isStatusPublishingEnabled?: boolean
  isPullRequestsEnabled?: boolean
  onDelete?: () => void
  onChange?: (value: PipelineBaseRepository) => void
  onConfirm?: () => void
  onCancel?: () => void
  externalVcsRootId?: string
  pipelineKey: ConfigurationStorageSwitchFragment$key | null
}
function NewPipelineRepositoryForm({
  projectId,
  pipelineId,
  repositoryUrl,
  createdRepositories,
  vcsRootId,
  name,
  vcsName,
  branch,
  branchSpec,
  vcsProviderType,
  isRoot = false,
  isExternal,
  isCreateMode,
  isStatusPublishingEnabled,
  isPullRequestsEnabled,
  onConfirm,
  onDelete,
  onChange,
  onCancel,
  className,
  formId,
  username,
  password,
  vcsProtocol,
  externalVcsRootId,
  pipelineKey,
}: Props) {
  const {
    vcsProviders,
    selectedProvider,
    handleSelectProvider,
    selectedRepository,
    handleSelectRepository,
    handleSelectBranch,
    handleSelectBranchSpec,
    handleTogglePublishStatus,
    handleTogglePullRequests,
    filterRepositories,
    onVcsLogin,
    onError,
    hasError,
    isVcsProviderTypeAny,
    isAnyVcsProviderVerified,
    isShowVcsAnyRepositoryAuthenticationForm,
    errorAnyVcsRepositoryNameErrorMessage,
    isAnyVcsUrlRepositoryAlreadyExists,
    anyVcsRepositoryUrl,
    isInvalidForm,
    repositoryFormErrorMessageMap,
    vcsProtocolRepositoryAuthType,
    vcsProtocolRepositoryAuthenticationFormChangeHandler,
    repositoryNameInputChangeHandler,
    vcsAnyRepositoryAuthenticationFormChangeAuthTypeHandler,
    vcsProviderVerifiedLabelButtonClickHandler,
    vcsAnyRepositoryAuthenticationFormSubmitHandler,
    selectExistingVcsRootHandler,
    vcsAnyRepositoryAuthType,
  } = useNewPipelineRepositoryForm(
    repositoryUrl,
    projectId,
    formId,
    createdRepositories,
    onChange,
    username,
    password,
    vcsProtocol,
    vcsProviderType,
  )
  const id = useId()
  const usedRepositoryInputId = `${id}-used-repository-input`
  const showLoginAlert =
    (selectedProvider != null &&
      selectedProvider?.username == null &&
      !isVcsProviderTypeAny &&
      !isExternal) ||
    hasError
  const sidebarFooterDoneButtonLabel = isCreateMode ? 'Add' : 'Done'
  const sidebarHeaderTitle = `${isCreateMode ? 'Add' : 'Edit'} Repository`
  const anyVcsRepositoryAuthenticationUrl = isAnyVcsUrlRepositoryAlreadyExists
    ? undefined
    : anyVcsRepositoryUrl
  const isShowAdditionFields =
    (selectedRepository != null && !isVcsProviderTypeAny) ||
    (isVcsProviderTypeAny && isAnyVcsProviderVerified)

  const isDisabledButtonDone =
    isInvalidForm || hasError || (isVcsProviderTypeAny && !isAnyVcsProviderVerified)
  const sidebarFooterDoneButtonHandler = !isDisabledButtonDone ? onConfirm : undefined
  const sidebarFooterDeleteButtonHandler = !isCreateMode ? onDelete : undefined
  const formBottomSection = (
    <>
      {isStatusPublishingFeatureEnabled && selectedProvider.connectionId != null && (
        <>
          <label>{'Advanced integration'}</label>
          <AdvancedIntegrationSection />
        </>
      )}
    </>
  )
  const advancedIntegrationSection = isStatusPublishingFeatureEnabled &&
    selectedProvider?.connectionId != null && (
      <div>
        <label className={styles.label}>{'Advanced integration'}</label>
        <PublishStatusToggle
          checked={isStatusPublishingEnabled}
          onToggle={handleTogglePublishStatus}
        />
      </div>
    )

  if (projectId == null) {
    return null
  }

  return (
    <div className={styles.sidebar}>
      <div className={styles.content}>
        <SidebarHeader title={sidebarHeaderTitle} onClick={onCancel} />
        <div className={className}>
          {isExternal && (
            <Alert className={styles.usedVcsRootAlert}>
              {'This repository connection reuses settings of a VCS root. '}
              <Link
                href={getExternalVcsRootEditUrl(vcsRootId, 'editVcsRoot', {
                  editingScope: `editPipeline:${pipelineId}`,
                })}
              >
                {'Edit its settings'}
              </Link>
              {' to modify a repository connection.'}
            </Alert>
          )}
          {isExternal || vcsProviders == null ? (
            <>
              <label htmlFor={usedRepositoryInputId} className={styles.label}>
                {`Used ${isExternal ? 'VCS root' : 'repository'}`}
              </label>
              <Input
                id={usedRepositoryInputId}
                size={Size.FULL}
                value={isExternal ? name : selectedRepository?.name}
                icon={() => (
                  <VcsProviderIcon
                    className={styles.disabledIcon}
                    vcsProviderType={
                      isExternal ? VcsProviderType.EXISTING_VCS_ROOT : vcsProviderType
                    }
                  />
                )}
                disabled
              />
            </>
          ) : (
            <div className={styles.repositoryBlock}>
              <div className={styles.controls}>
                <VcsProviderSelect
                  projectId={projectId}
                  vcsProviders={vcsProviders}
                  selected={selectedProvider}
                  disabled={isRoot}
                  disableReason={isRoot ? DISABLE_REASON_FOR_MAIN_ROOT : null}
                  onSelectProvider={handleSelectProvider}
                  onLogin={onVcsLogin}
                />
                {isVcsProviderTypeAny && !isExternal ? (
                  <RepositoryNameInput
                    error={errorAnyVcsRepositoryNameErrorMessage}
                    value={anyVcsRepositoryUrl}
                    disabled={isRoot || isAnyVcsProviderVerified}
                    disableReason={isRoot ? DISABLE_REASON_FOR_MAIN_ROOT : null}
                    onChange={repositoryNameInputChangeHandler}
                  />
                ) : isExternal ? (
                  <ExistingVcsRootSelect
                    projectId={projectId}
                    vcsRootId={externalVcsRootId}
                    onVcsRootSelect={selectExistingVcsRootHandler}
                    createdRepositories={createdRepositories}
                  />
                ) : (
                  <div>
                    <RepositorySelect
                      projectId={projectId}
                      vcsProvider={selectedProvider}
                      selected={selectedRepository}
                      onSelectRepository={handleSelectRepository}
                      repositoryFilterFn={filterRepositories}
                      autoFocus={isCreateMode}
                      disabled={isRoot || showLoginAlert}
                      disableReason={isRoot ? DISABLE_REASON_FOR_MAIN_ROOT : null}
                      error={repositoryFormErrorMessageMap?.url}
                      onError={onError}
                    />
                  </div>
                )}
              </div>
              {showLoginAlert && (
                <Alert contentClassName={styles.loginAlertContent}>
                  {`To show available repositories TeamCity requires access to your ${selectedProvider?.displayName} account.`}
                  {selectedProvider?.connectionId && (
                    <VcsLoginLink
                      className={styles.loginLink}
                      connectionId={selectedProvider?.connectionId}
                      onLogin={onVcsLogin}
                      projectId={projectId}
                    />
                  )}
                </Alert>
              )}
              {isShowVcsAnyRepositoryAuthenticationForm && (
                <VcsAnyRepositoryAuthenticationForm
                  projectId={projectId}
                  url={anyVcsRepositoryAuthenticationUrl}
                  password={password}
                  username={username}
                  disableChangingVcsProtocol={isRoot}
                  vcsProtocol={vcsProtocolRepositoryAuthType}
                  onChangeVcsProtocol={vcsProtocolRepositoryAuthenticationFormChangeHandler}
                  httpsAuthType={vcsAnyRepositoryAuthType}
                  onChangeHttpsAuthType={vcsAnyRepositoryAuthenticationFormChangeAuthTypeHandler}
                  onSumbit={vcsAnyRepositoryAuthenticationFormSubmitHandler}
                  compact
                />
              )}
              {isAnyVcsProviderVerified && isVcsProviderTypeAny && (
                <RepositoryEditUrl
                  vcsProtocol={vcsProtocolRepositoryAuthType}
                  onClick={vcsProviderVerifiedLabelButtonClickHandler}
                />
              )}
            </div>
          )}
          {isExternal ? (
            <ExistingVcsRootForm compact vcsRootId={externalVcsRootId} vcsName={vcsName}>
              {formBottomSection}
            </ExistingVcsRootForm>
          ) : (
            <SlideInOutAnimation
              contentClassName={styles.form}
              show={isShowAdditionFields}
              mountOnEnter
              unmountOnExit
            >
              <div>
                <label className={styles.label}>{'Default branch'}</label>
                <DefaultBranchSelect
                  projectId={projectId}
                  vcsProtocol={vcsProtocolRepositoryAuthType}
                  vcsProvider={selectedProvider}
                  selected={branch}
                  repoUrl={repositoryUrl}
                  repoDefaultBranch={selectedRepository?.defaultBranch}
                  onSelectBranch={handleSelectBranch}
                  disabled={isExternal}
                />
              </div>
              <div>
                <label className={styles.label}>{'Branches to monitor'}</label>
                <BranchSpecificationSelect
                  disabled={isExternal}
                  groupClassName={styles.branchSpecPolicy}
                  specification={branchSpec ?? ''}
                  defaultBranch={branch}
                  isPullRequestsSupported={selectedProvider?.pullRequestTriggersSupported}
                  isPullRequestsEnabled={isPullRequestsEnabled}
                  onSelectSpecification={handleSelectBranchSpec}
                  onTogglePullRequests={handleTogglePullRequests}
                />
              </div>
              {!isRoot && advancedIntegrationSection}
            </SlideInOutAnimation>
          )}
          {isRoot && (isShowAdditionFields || isExternal) && (
            <Suspense>
              <ConfigurationStorageSection pipelineKey={pipelineKey} />
              {advancedIntegrationSection}
            </Suspense>
          )}
        </div>
      </div>
      <PipelineRepositorySidebarFooter
        doneButtonLabel={sidebarFooterDoneButtonLabel}
        onDone={sidebarFooterDoneButtonHandler}
        onDelete={sidebarFooterDeleteButtonHandler}
        onCancel={onCancel}
      />
    </div>
  )
}

export default NewPipelineRepositoryForm
