import classnames from 'classnames'

import {isPullRequestsFeatureEnabled} from '../../../../../utils/featureToggles'
import {getIsGitVcsRoot} from '../../../../../utils/getIsGitVcsRoot'
import PipelineRepositoryPreview from '../PipelineRepositoryPreview/PipelineRepositoryPreview'

import type {PipelineRepositoryProps} from './PipelineRepository.types'
import usePipelineRepository from './usePipelineRepository'

import styles from './PipelineRepository.module.css'

function PipelineRepository({
  branch = '',
  branchSpec = '',
  repositoryUrl = '',
  vcsProviderType,
  name,
  vcsName,
  isRoot = false,
  index,
  onDelete,
  onRestore,
  isDeleted = false,
  className,
  isStatusPublishingEnabled,
  isExternalVcsRoot,
  trackPullRequests,
}: PipelineRepositoryProps) {
  const {
    repositoryName,
    canEditable,
    canDeletable,
    canRestore,
    branchSpecLabel,
    repositoryFormErrorMessage,
    deleteRepositoryHandler,
    toggleEditModeHandler,
  } = usePipelineRepository(
    repositoryUrl,
    branch,
    branchSpec,
    isDeleted,
    isRoot,
    index,
    onDelete,
    vcsProviderType,
    trackPullRequests,
  )
  const isGitVcsRoot = getIsGitVcsRoot(vcsName)
  const containerClassNames = classnames(
    className,
    styles.container,
    {[styles.block]: isPullRequestsFeatureEnabled},
    {[styles.deleted]: isDeleted},
  )
  return (
    <PipelineRepositoryPreview
      className={containerClassNames}
      vcsProviderType={vcsProviderType}
      repositoryName={name ?? repositoryName}
      url={!name || name === repositoryUrl ? undefined : repositoryUrl}
      deleteRepositoryHandler={deleteRepositoryHandler}
      toggleEditModeHandler={toggleEditModeHandler}
      canEditable={canEditable}
      canDeletable={canDeletable}
      canRestore={canRestore}
      onRestore={onRestore}
      branchSpecLabel={isGitVcsRoot ? branchSpecLabel : undefined}
      branch={isGitVcsRoot ? branch : undefined}
      isRoot={isRoot}
      errorMessage={repositoryFormErrorMessage}
      isStatusPublishingEnabled={isStatusPublishingEnabled}
      isExternalVcsRoot={isExternalVcsRoot}
    />
  )
}

export default PipelineRepository
