import {useEffect, useRef} from 'react'
import {useSearchParams} from 'react-router'

import {sideBarNavigatiobSearchParam} from '../../SettingsSidebarContent.const'
import {JobDirectoryType} from '../JobDirectory/JobDirectoryTree/JobDirectoryTree.types'
import useJobFilesPublicationStore from '../JobFilesPublication/useJobFilesPublicationStore'

import {maxLimitFilesAmount, timeToWaisSidebarAnimation} from './JobFilesPublicationSidebar.const'

function useJobFilesPublicationSidebar() {
  const {
    getIsKeyDelete,
    filesPublication,
    addFilesPublicationHandler,
    changeFilePublicationHandler,
    deleteFilesPublicationHandler,
    restoreFilesPublicationHandler,
    updateFilesDependenciesHandler,
    filesPublicationMultiplyDeleteHandler,
    filesPublicationMultiplyConfirmHandler,
  } = useJobFilesPublicationStore()
  const changeFilePublicationInputHandler =
    (index: number) =>
    ({target}: React.ChangeEvent<HTMLInputElement>) => {
      const file = filesPublication[index]
      const shared = file?.['share-with-jobs'] || true
      const publishArtifact = file?.['publish-artifact'] || false

      changeFilePublicationHandler(index, {
        path: target.value,
        'share-with-jobs': shared,
        'publish-artifact': publishArtifact,
      })
    }
  const selectJobDirectoryHandler = (index: number) => (type: JobDirectoryType, path: string) => {
    const value = type === JobDirectoryType.DIRECTORY ? `${path.slice(1)}/**/*` : path.slice(1)
    const file = filesPublication[index]
    const shared = file?.['share-with-jobs'] || true
    const publishArtifact = file?.['publish-artifact'] || false

    changeFilePublicationHandler(index, {
      path: value,
      'share-with-jobs': shared,
      'publish-artifact': publishArtifact,
    })
  }
  const changeFilePublicationSharedHandler =
    (index: number) => (event: React.ChangeEvent<HTMLInputElement>) => {
      const file = filesPublication[index]
      const path = file?.path || ''
      const publishArtifact = file?.['publish-artifact'] || false
      const newSharedValue = event.target.checked

      const newArtifactValue = !newSharedValue && !publishArtifact ? true : publishArtifact

      changeFilePublicationHandler(index, {
        path,
        'share-with-jobs': newSharedValue,
        'publish-artifact': newArtifactValue,
      })
    }

  const changeFilePublicationArtifactHandler =
    (index: number) => (event: React.ChangeEvent<HTMLInputElement>) => {
      const file = filesPublication[index]
      const path = file?.path || ''
      const shared = file?.['share-with-jobs'] || true
      const newArtifactValue = event.target.checked
      const newSharedValue = !newArtifactValue && !shared ? true : shared

      changeFilePublicationHandler(index, {
        path,
        'share-with-jobs': newSharedValue,
        'publish-artifact': newArtifactValue,
      })
    }

  const clickRestoreFilePublicationHandler = (index: number) => () =>
    restoreFilesPublicationHandler(index)
  const clickDeleteFilePublicationHandler = (index: number) => () =>
    deleteFilesPublicationHandler(index)
  const lastInputRef = useRef<HTMLInputElement>(null)
  const clickAddFilePublicationButtonHandler = () => {
    addFilesPublicationHandler()
    setTimeout(() => lastInputRef.current?.focus(), timeToWaisSidebarAnimation)
  }

  const filesPublicationLength = filesPublication.length
  const isShowBottomAddButton = filesPublicationLength > maxLimitFilesAmount
  const isFilesPublicationEmpty = !filesPublicationLength
  const isShowFormNote = !isFilesPublicationEmpty
  const [searchParams, setSearchParams] = useSearchParams()
  const clickDoneFormButtonHandler = () => {
    filesPublicationMultiplyDeleteHandler()
    filesPublicationMultiplyConfirmHandler()
    updateFilesDependenciesHandler()

    searchParams.delete(sideBarNavigatiobSearchParam.sharedFiles)

    const searchParamsObject = Object.fromEntries(searchParams.entries())

    setSearchParams(searchParamsObject)
  }

  useEffect(() => {
    if (isFilesPublicationEmpty) {
      clickAddFilePublicationButtonHandler()
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  return {
    lastInputRef,
    filesPublication,
    isShowBottomAddButton,
    isShowFormNote,
    getIsKeyDelete,

    clickDoneFormButtonHandler,
    clickAddFilePublicationButtonHandler,
    clickRestoreFilePublicationHandler,
    clickDeleteFilePublicationHandler,
    changeFilePublicationInputHandler,
    changeFilePublicationSharedHandler,
    changeFilePublicationArtifactHandler,
    selectJobDirectoryHandler,
  }
}

export default useJobFilesPublicationSidebar
