import type {SelectItem} from '@jetbrains/ring-ui-built/components/select/select'
import type {ChangeEvent} from 'react'
import {useMemo} from 'react'

import {useAppDispatch} from '../../../../../../../../hooks/react-redux'
import {usePipelineId} from '../../../../../hooks/pipeline'
import {pipelineDraft} from '../../../../slices/EditPipelinePage.slices'
import {TriggerSchedulingPolicy} from '../PipelineTriggers.consts'

import {defaultHour, defaultMinute, timeZoneList} from './PipelineTriggerForm.consts'

function usePipelineTriggerForm(
  daysOfWeek: string[],
  index: number,
  timezone: string,
  hour: string,
  minute: string,
  schedulingPolicy: string,
) {
  const timeZoneSelected = useMemo(() => timeZoneList.find(({key}) => key === timezone), [timezone])
  const selectedDaysOfWeek = useMemo(
    () => daysOfWeek.map(day => ({key: day, label: day})),
    [daysOfWeek],
  )
  const dispatch = useAppDispatch()
  const pipelineId = usePipelineId()
  const setParameters = (newParameters: Record<string, string>) => {
    const parameters = {
      timezone,
      daysOfWeek: daysOfWeek.join(','),
      hour,
      minute,
      schedulingPolicy,
      ...newParameters,
    }
    const newSchedulingPolicy = !parameters.daysOfWeek
      ? TriggerSchedulingPolicy.DAILY
      : TriggerSchedulingPolicy.WEEKLY

    dispatch(
      pipelineDraft.actions.changeTrigger({
        id: pipelineId,
        index,
        parameters: {
          ...parameters,
          schedulingPolicy: newSchedulingPolicy,
        },
      }),
    )
  }

  const handlerDayChange = (value: SelectItem[] | null) => {
    setParameters({daysOfWeek: value?.map(day => day.key).join(',') ?? ''})
  }
  const handlerTimeZoneChange = (value: SelectItem | null) =>
    setParameters({timezone: value!.key.toString()})
  const handlerTimeChange = ({currentTarget}: ChangeEvent<HTMLInputElement>) => {
    const [newHour = defaultHour, newMinute = defaultMinute] = currentTarget.value.split(':')
    setParameters({hour: newHour, minute: newMinute})
  }

  return {
    handlerTimeZoneChange,
    handlerDayChange,
    handlerTimeChange,
    timeZoneSelected,
    selectedDaysOfWeek,
  }
}

export default usePipelineTriggerForm
