import type {RankedTester, LayoutProps, VerticalLayout} from '@jsonforms/core'
import {rankWith, uiTypeIs, toDataPath} from '@jsonforms/core'
import type {ControlElement} from '@jsonforms/core/src/models/uischema'
import {withJsonFormsLayoutProps} from '@jsonforms/react'
import {Fragment, memo, useCallback, useRef} from 'react'

import useBooleanState from '../../../../../../../../hooks/useBooleanState'
import {useJobStepFormContext} from '../../../JobStepFormContext/JobStepFormContext'
import {SmartDetectors, SmartDetectorsSuccess} from '../../../SmartDetectors/SmartDetectors'
import JsonFormsDispatchMemo from '../components/JsonFormsDispatchMemo'
import JsonFormInputControlControlProvider from '../controls/JsonFormInputControl/JsonFormInputControlControlProvider'

import styles from './JsonFormSmartDetectorsWrapper.module.css'

function JsonFormSmartDetectorsWrapper({
  uischema,
  schema,
  path,
  enabled,
  renderers,
  cells,
  data,
}: LayoutProps) {
  const detectors = (uischema?.options?.detectors ?? []) as string[]
  const {elements} = uischema as VerticalLayout
  const {stepIndex} = useJobStepFormContext()
  const [focused, onFocus, onBlur] = useBooleanState()
  const inputRef = useRef<HTMLInputElement | HTMLTextAreaElement | null>(null)
  const controlInputInitRefHander = useCallback((ref: HTMLInputElement | HTMLTextAreaElement) => {
    inputRef.current = ref
  }, [])

  return elements.map((child, index) => {
    const childElement = child as ControlElement
    const elementPath = toDataPath(childElement?.scope)
    const key = `${elementPath}-${index}`
    const value = data[elementPath]

    return (
      <Fragment key={key}>
        <JsonFormInputControlControlProvider
          onFocus={onFocus}
          onBlur={onBlur}
          onInitRef={controlInputInitRefHander}
        >
          <JsonFormsDispatchMemo
            uischema={child}
            schema={schema}
            path={path}
            enabled={enabled}
            renderers={renderers}
            cells={cells}
          />
        </JsonFormInputControlControlProvider>
        <div className={styles.detectors}>
          {detectors.map((detector, detectorIndex) => {
            const detectorKey = `detector-${detectorIndex}`
            const SmartDetector = SmartDetectors[detector]

            return (
              SmartDetector && (
                <SmartDetector
                  key={detectorKey}
                  anchorElement={inputRef?.current}
                  name={elementPath}
                  value={value?.trim() ?? ''}
                  stepIndex={stepIndex}
                  focused={focused}
                />
              )
            )
          })}
          {detectors?.map((smartDetectorSuccess, detectorIndex) => {
            const detectorKey = `detector-${detectorIndex}`
            const SmartDetectorSuccess = SmartDetectorsSuccess[smartDetectorSuccess]

            return (
              SmartDetectorSuccess && (
                <SmartDetectorSuccess key={detectorKey} stepIndex={stepIndex} />
              )
            )
          })}
        </div>
      </Fragment>
    )
  })
}

export const jsonFormSmartDetectorsWrapperTester: RankedTester = rankWith(
  1,
  uiTypeIs('SmartDetectorsWrapper'),
)

export default withJsonFormsLayoutProps(memo(JsonFormSmartDetectorsWrapper), true)
