import {useAppSelector} from '../../../../../../hooks/react-redux'
import styles from '../../../components/ParametersSidebar/ParametersSidebar.module.css'
import ParametersSidebarFooter from '../../../components/ParametersSidebar/ParametersSidebarFooter/ParametersSidebarFooter'
import {usePipelineId} from '../../../hooks/pipeline'
import {TriggerType} from '../PipelineSettingsSidebar/PipelineTriggers/PipelineTriggers.consts'
import SidebarHeader from '../SidebarSlider/Header/SidebarHeader'

import PipelineOnChangesTriggerForm from './PipelineOnChangesTriggerForm/PipelineOnChangesTriggerForm'
import PipelineScheduleTriggerForm from './PipelineScheduleTriggerForm/PipelineScheduleTriggerForm'
import usePipelineTrigger from './PipelineSettingsTriggerSidebar.hooks'

type Props = {
  index?: string | null
}
function PipelineSettingsTriggerSidebar({index}: Props) {
  const id = usePipelineId()
  const triggerIndex = Number(index)
  const type = useAppSelector(
    state => state.pipelines.pipelineDraft[id]?.draft?.triggers?.[triggerIndex]?.type,
  )
  const isVcsTrigger = type === TriggerType.VCS

  const {isAdd, handlerJobTriggerFormClose} = usePipelineTrigger(triggerIndex)

  return (
    <div className={styles.sidebar}>
      <div className={styles.content}>
        <SidebarHeader
          title={`${isAdd ? 'Adding' : 'Editing'} ${isVcsTrigger ? 'auto-run' : 'schedule'} trigger`}
          border
          onClick={handlerJobTriggerFormClose}
        />
        <div className={styles.continater}>
          {isVcsTrigger ? (
            <PipelineOnChangesTriggerForm index={triggerIndex} />
          ) : (
            <PipelineScheduleTriggerForm index={triggerIndex} />
          )}
        </div>
      </div>
      <ParametersSidebarFooter onDone={handlerJobTriggerFormClose} />
    </div>
  )
}

export default PipelineSettingsTriggerSidebar
