import Toggle from '@jetbrains/ring-ui-built/components/toggle/toggle'
import {isBooleanControl, rankWith} from '@jsonforms/core'
import type {RankedTester, ControlProps} from '@jsonforms/core'
import {withJsonFormsControlProps} from '@jsonforms/react'
import {useCallback} from 'react'
import type * as React from 'react'

import styles from '../styles.module.css'

import JsonFormHelpDetailsIcon from './JsonFormHelpDetailsIcon'

function JsonFormBooleanControl({
  data,
  visible,
  label,
  enabled,
  handleChange,
  path,
  uischema,
  description,
}: ControlProps) {
  const trueValue = 'true'
  const falseValue = ''
  const toggleChangeHandler = useCallback(
    ({currentTarget}: React.ChangeEvent<HTMLInputElement>) => {
      handleChange(path, currentTarget.checked ? trueValue : falseValue)
    },
    [handleChange, path],
  )
  const checked = data === trueValue
  const isHidden = uischema.options?.hide

  if (!visible || isHidden) {
    return null
  }

  return (
    <div className={styles.container}>
      <Toggle checked={checked} onChange={toggleChangeHandler} disabled={!enabled}>
        {label}
        {description && <JsonFormHelpDetailsIcon>{description}</JsonFormHelpDetailsIcon>}
      </Toggle>
    </div>
  )
}

export const jsonFormBooleanControlTester: RankedTester = rankWith(1, isBooleanControl)
export default withJsonFormsControlProps(JsonFormBooleanControl)
