import exceptionIcon from '@jetbrains/icons/exception.svg'
import ErrorMessage from '@jetbrains/ring-ui-built/components/error-message/error-message'
import classNames from 'classnames'
import {lazy, Suspense, useEffect, useState} from 'react'
import type {EntryPointProps} from 'react-relay'
import {usePreloadedQuery} from 'react-relay'
import {parseDocument} from 'yaml'

import {useAppDispatch, useAppSelector} from '../../../../hooks/react-redux'
import {useBooleanQueryParam} from '../../../../hooks/routes'
import type {State} from '../../../../reducers/types'
import {getPipelineHref, getPipelinesHref} from '../../../../routes'
import {subscribeOnProjectEvents} from '../../../../utils/subscriber'
import {PROJECT_PERSISTED} from '../../../../utils/subscriptionEvents'
import Loader from '../../../common/Loader/Loader'
import Redirect from '../../../common/Redirect/Redirect'
import RouterLink from '../../../common/RouterLink/RouterLink'
import type {PipelinesPagesQuery} from '../__generated__/PipelinesPagesQuery.graphql'
import FullScreenErrorWrapper from '../components/FullScreenErrorWrapper/FullScreenErrorWrapper'
import PageWithSidebar from '../components/PageWithSidebar/PageWithSidebar'
import {usePipelineId} from '../hooks/pipeline'
import {pipelineQuery} from '../PipelinesPages.queries'
import {pipelinesApi} from '../services/pipelinesApi'
import {serializeError} from '../utils/error'

import EditPipelineConfigurationDialog from './EditPipelineConfigurationDialog/EditPipelineConfigurationDialog'
import {EditPipelineProvider} from './EditPipelineContext'
import EditPipelineToolbar from './EditPipelineToolbar/EditPipelineToolbar'
import type {EditPipelineYAMLEntryPoint} from './EditPipelineYAML/EditPipelineYAML.entryPoint'
import EditPipelineYAMLContainer from './EditPipelineYAML/EditPipelineYAMLContainer'
import useYamlSchema from './EditPipelineYAML/YamlEditor/hooks/useYamlSchema'
import type {JobSettingsSidebarEntryPoint} from './SettingsSidebarContent/JobSettingsSidebar/JobSettingsSidebar.entryPoint'
import SidebarContent from './SettingsSidebarContent/SettingsSidebarContent'
import {pipelineYamlValidity} from './slices/EditPipelinePage.slices'

import styles from './EditPipelinePage.module.css'

type Queries = {pipeline: PipelinesPagesQuery}
export type NestedEntryPoints = {
  jobSettingsSidebar?: typeof JobSettingsSidebarEntryPoint
  editPipelineYAML: typeof EditPipelineYAMLEntryPoint
}

const PipelineChart = lazy(
  () =>
    import(
      /* webpackChunkName: "PipelineChart" */
      './EditPipelineChart/EditPipelineChart'
    ),
)

function EditPipelinePage({
  queries,
  entryPoints,
}: EntryPointProps<Queries, NestedEntryPoints, {}, {}>) {
  const {pipeline} = usePreloadedQuery(pipelineQuery, queries.pipeline) ?? {}
  const {headBuildType: pipelineHeadBuildTypeKey = null, parentProject, internalId} = pipeline ?? {}
  const id = usePipelineId()
  const dispatch = useAppDispatch()
  const pipelineData = pipelinesApi.endpoints.getPipelineById.useQuery(id, {
    selectFromResult: ({currentData, isLoading, isUninitialized, isFetching, error}) => ({
      yaml: currentData?.yaml,
      isLoading: isLoading || isUninitialized,
      isFetching,
      hasVcsRoot: currentData?.vcsRoot,
      error,
    }),
    refetchOnMountOrArgChange: true,
  })
  const isYaml = useBooleanQueryParam('yaml')
  const [validated, setValidated] = useState(false)
  const {schema, validator} = useYamlSchema(
    pipelineData.yaml ?? '',
    entryPoints.editPipelineYAML.queries.cloudImages!,
  )
  const isSubmitted = useAppSelector((state: State) => state.pipelines.pipelineDraftForm.submitted)

  useEffect(() => {
    if (pipelineData.yaml != null && !validated) {
      const validate = validator.validate(parseDocument(pipelineData.yaml).toJSON(), schema, {
        nestedErrors: true,
      })

      if (!validate.valid) {
        dispatch(
          pipelineYamlValidity.actions.setParsed({id, value: false, yaml: pipelineData.yaml}),
        )
      }
      setValidated(true)
    }
  }, [dispatch, id, pipelineData.yaml, schema, validated, validator])

  useEffect(
    () =>
      internalId
        ? subscribeOnProjectEvents(internalId, [PROJECT_PERSISTED], () => {
            if (!isSubmitted) {
              dispatch(pipelinesApi.endpoints.getPipelineById.initiate(id))
            }
          })
        : undefined,
    [dispatch, id, internalId, isSubmitted],
  )

  if (pipelineData.isLoading) {
    return <Loader />
  }

  if (pipelineData.error) {
    return (
      <FullScreenErrorWrapper>
        <ErrorMessage
          icon={exceptionIcon}
          message="Error while loading pipeline"
          description={serializeError(pipelineData.error)}
        >
          <RouterLink to={getPipelinesHref()}>{'Go to the home page'}</RouterLink>
        </ErrorMessage>
      </FullScreenErrorWrapper>
    )
  }

  if (!pipelineData.hasVcsRoot && !pipelineData.isFetching) {
    return <Redirect to={getPipelineHref(id)} replace state={{isVcsEmpty: true}} />
  }

  return (
    <EditPipelineProvider parentProjectId={parentProject?.id}>
      <PageWithSidebar
        className={classNames(styles.pageWithSidebar, {[styles.openSidebar]: !isYaml})}
        sidebarClassName={styles.sidebar}
        content={
          <>
            <div className={styles.main}>
              <EditPipelineToolbar className={styles.toolbar} />
              <div className={styles.content}>
                {isYaml && entryPoints.editPipelineYAML != null ? (
                  <Suspense>
                    <EditPipelineYAMLContainer
                      pipelineHeadBuildTypeKey={pipelineHeadBuildTypeKey}
                      editPipelineYAMLEntryPoint={entryPoints.editPipelineYAML}
                    />
                  </Suspense>
                ) : (
                  <div className={styles.chart}>
                    <Suspense fallback={<Loader data-suspense-fallback />}>
                      <PipelineChart pipelineHeadBuildTypeKey={pipelineHeadBuildTypeKey} />
                    </Suspense>
                  </div>
                )}
              </div>
              <Suspense>
                <EditPipelineConfigurationDialog pipelineKey={pipeline ?? null} />
              </Suspense>
            </div>
          </>
        }
        sidebar={
          <SidebarContent
            pipelineKey={pipeline ?? null}
            jobSettingsSidebarEntryPoint={entryPoints.jobSettingsSidebar}
          />
        }
        isOpenSidebar={!isYaml}
      />
    </EditPipelineProvider>
  )
}

export type EditPipelinePageComponent = typeof EditPipelinePage

export default EditPipelinePage
