import {useCallback} from 'react'

import {useAppDispatch, useAppSelector} from '../../../../../../../hooks/react-redux'
import {usePipelineId} from '../../../../hooks/pipeline'
import {validateForm} from '../../../EditPipelinePage.actions'
import {getPipelineErrorMessage} from '../../../EditPipelinePage.selectors'
import {pipelineDraft} from '../../../slices/EditPipelinePage.slices'
import {FormType} from '../../../slices/EditPipelinePage.slices.types'

import {ALL_BRANCHES} from './PipelineOnChangesTriggerForm.const'

import type {NewTriggerDto} from 'src/components/pages/PipelinesPages/services/pipelinesApi.types'

function usePipelineOnChangesTriggerForm(index: number, trigger?: NewTriggerDto) {
  const dispatch = useAppDispatch()
  const pipelineId = usePipelineId()
  const {triggerBranches, triggerPullRequests, parameters = {}} = trigger ?? {}
  const branchFilter = parameters?.branchFilter ?? ALL_BRANCHES
  const errorMessage = useAppSelector(
    getPipelineErrorMessage({pipelineId, formType: FormType.TRIGGER}),
  )
  const setParameters = useCallback(
    ({
      newBranchFilter,
      newTriggerBranches,
      newTriggerPullRequests,
    }: {
      newBranchFilter?: string
      newTriggerBranches?: boolean
      newTriggerPullRequests?: boolean
    }) =>
      dispatch(
        pipelineDraft.actions.changeTrigger({
          id: pipelineId,
          index,
          triggerBranches: newTriggerBranches != null ? newTriggerBranches : triggerBranches,
          triggerPullRequests:
            newTriggerPullRequests != null ? newTriggerPullRequests : triggerPullRequests,
          parameters: {
            branchFilter: newBranchFilter != null ? newBranchFilter : branchFilter,
          },
        }),
      ),
    [branchFilter, dispatch, index, pipelineId, triggerBranches, triggerPullRequests],
  )
  const handleSelectBranchSpec = useCallback(
    (selected: string) => {
      setParameters({newBranchFilter: selected})
    },
    [setParameters],
  )
  const handleToggleBranches = useCallback(
    (value?: boolean) => {
      setParameters({
        newTriggerBranches: value,
        ...(!value && !triggerPullRequests ? {newTriggerPullRequests: true} : {}),
        ...(!value ? {newBranchFilter: ALL_BRANCHES} : {}),
      })
    },
    [setParameters, triggerPullRequests],
  )
  const handleTogglePullRequests = useCallback(
    (value?: boolean) => {
      setParameters({
        newTriggerPullRequests: value,
        ...(!value && !triggerBranches ? {newTriggerBranches: true} : {}),
      })
      if (!value) {
        dispatch(validateForm({pipelineId, type: FormType.REPOSITORIES}))
      }
      dispatch(validateForm({pipelineId, type: FormType.TRIGGER}))
    },
    [dispatch, pipelineId, setParameters, triggerBranches],
  )
  return {
    triggerBranches,
    triggerPullRequests,
    branchFilter,
    errorMessage,
    handleSelectBranchSpec,
    handleToggleBranches,
    handleTogglePullRequests,
  }
}
export default usePipelineOnChangesTriggerForm
