import type React from 'react'
import {useSearchParams} from 'react-router'

import {emptyArray} from '../../../../../../../utils/empty'
import {usePipelineId} from '../../../../hooks/pipeline'
import {isPullRequestsFeatureEnabled} from '../../../../utils/featureToggles'
import {validateForm} from '../../../EditPipelinePage.actions'
import {getOriginalPipelineTriggers} from '../../../EditPipelinePage.selectors'
import {FormType} from '../../../slices/EditPipelinePage.slices.types'
import {sideBarNavigatiobSearchParam} from '../../SettingsSidebarContent.const'

import {
  currentTimeZone,
  defaultHour,
  defaultMinute,
} from './PipelineTriggerForm/PipelineTriggerForm.consts'
import {TriggerSchedulingPolicy, TriggerType} from './PipelineTriggers.consts'

import {
  collapsedBlocks,
  pipelineDraft,
  pipelineForm,
} from 'src/components/pages/PipelinesPages/EditPipelinePage/slices/EditPipelinePage.slices'
import {useAppDispatch, useAppSelector} from 'src/hooks/react-redux'

function usePipelineTriggers() {
  const dispatch = useAppDispatch()
  const id = usePipelineId()
  const sevedTriggers = useAppSelector(getOriginalPipelineTriggers(id)) ?? emptyArray
  const triggers = useAppSelector(state => state.pipelines.pipelineDraft[id]?.draft?.triggers)
  const [searchParams, setSearchParams] = useSearchParams()
  const openForm = () => {
    const searchParamsObject = Object.fromEntries(searchParams.entries())
    if (isPullRequestsFeatureEnabled) {
      setSearchParams({
        ...searchParamsObject,
        [sideBarNavigatiobSearchParam.trigger]: `${triggers?.length}`,
      })
    }
    dispatch(collapsedBlocks.actions.toggle({id: 'triggers', collapsed: false}))
    dispatch(
      pipelineForm.actions.open({
        pipelineId: id,
        type: FormType.TRIGGER,
        id: triggers?.length ?? 0,
        isAdd: true,
      }),
    )
  }
  const handlerAddJobScheduleTriggerButtonClick = () => {
    dispatch(
      pipelineDraft.actions.addTrigger({
        id,
        type: TriggerType.SCHEDULE,
        parameters: {
          timeZone: currentTimeZone,
          daysOfWeek: '',
          hour: defaultHour,
          minute: defaultMinute,
          schedulingPolicy: TriggerSchedulingPolicy.DAILY,
        },
        disabled: false,
      }),
    )
    openForm()
  }
  const handlerAddJobOnChangesTriggerButtonClick = () => {
    dispatch(
      pipelineDraft.actions.addTrigger({
        id,
        type: TriggerType.VCS,
        disabled: false,
        triggerBranches: true,
      }),
    )
    openForm()
  }
  const handlerDisabledToggleChange =
    (index: number) =>
    ({currentTarget}: React.ChangeEvent<HTMLInputElement>) => {
      dispatch(
        pipelineDraft.actions.toggleDisabledTrigger({
          id,
          index,
          value: !currentTarget.checked,
        }),
      )
      dispatch(validateForm({pipelineId: id, type: FormType.TRIGGER}))
      dispatch(validateForm({pipelineId: id, type: FormType.REPOSITORIES}))
    }
  const handlerTriggerDelete = (index: number) => () => {
    dispatch(pipelineDraft.actions.deleteTrigger({id, index}))
    dispatch(validateForm({pipelineId: id, type: FormType.TRIGGER}))
    dispatch(validateForm({pipelineId: id, type: FormType.REPOSITORIES}))
  }

  return {
    triggers,
    sevedTriggers,
    handlerDisabledToggleChange,
    handlerAddJobOnChangesTriggerButtonClick,
    handlerAddJobScheduleTriggerButtonClick,
    handlerTriggerDelete,
  }
}

export default usePipelineTriggers
