import Select from '@jetbrains/ring-ui-built/components/select/select'
import {useMemo} from 'react'

import {useAppSelector} from '../../../../../../../hooks/react-redux'
import {usePipelineId} from '../../../../hooks/pipeline'
import {
  currentTimeZone,
  timeZoneList,
  daysOfWeek as daysOfWeekConstant,
} from '../../PipelineSettingsSidebar/PipelineTriggers/PipelineTriggerForm/PipelineTriggerForm.consts'
import usePipelineTriggerForm from '../../PipelineSettingsSidebar/PipelineTriggers/PipelineTriggerForm/PipelineTriggerForm.hooks'
import {TriggerSchedulingPolicy} from '../../PipelineSettingsSidebar/PipelineTriggers/PipelineTriggers.consts'

import styles from './PipelineScheduleTriggerForm.module.css'

import Input, {Size} from 'src/components/pages/PipelinesPages/components/Input'

type Props = {
  index: number
}

function PipelineScheduleTriggerForm({index}: Props) {
  const id = usePipelineId()
  const parameters = useAppSelector(
    state => state.pipelines.pipelineDraft[id]?.draft?.triggers?.[index]?.parameters,
  )
  const {
    daysOfWeek: parameterDaysOfWeek = '',
    hour = '00',
    minute = '00',
    timezone = currentTimeZone,
    schedulingPolicy = TriggerSchedulingPolicy.WEEKLY,
  } = parameters ?? {}
  const daysOfWeek = useMemo(() => {
    if (!parameterDaysOfWeek) {
      return []
    }
    return parameterDaysOfWeek.split(',')
  }, [parameterDaysOfWeek])

  const time = `${hour}:${minute}`
  const {
    handlerTimeZoneChange,
    handlerDayChange,
    handlerTimeChange,
    timeZoneSelected,
    selectedDaysOfWeek,
  } = usePipelineTriggerForm(daysOfWeek, index, timezone, hour, minute, schedulingPolicy)

  return (
    <div className={styles.content}>
      <Select
        label="Select day"
        multiple={{
          selectAll: true,
          selectAllLabel: 'Every day',
        }}
        size={Size.AUTO}
        onChange={handlerDayChange}
        selected={selectedDaysOfWeek}
        data={daysOfWeekConstant}
      />
      <div className={styles.timeSettings}>
        <Input
          label="Time"
          size={Size.AUTO}
          value={time}
          onChange={handlerTimeChange}
          inputClassName={styles.inputTime}
          min="00:00"
          max="23:59"
          type="time"
        />
        <div className={styles.selectTimeZoneWrapper}>
          <Select
            selectedLabel="Time zone"
            label="Select time zone"
            clear
            filter
            className={styles.selectTimeZone}
            size={Size.AUTO}
            onChange={handlerTimeZoneChange}
            selected={timeZoneSelected}
            data={timeZoneList}
          />
        </div>
      </div>
    </div>
  )
}

export default PipelineScheduleTriggerForm
