import {Fragment, memo, Suspense} from 'react'
import {EntryPointContainer, graphql, useFragment} from 'react-relay'
import type {PreloadedEntryPoint} from 'react-relay/relay-hooks/EntryPointTypes'

import StoredSettingsValueProvider from '../../contexts/StoredSettingsValue/StoredSettingsValueContext'
import {
  isNotificationsFeatureEnabled,
  isPipelineNotificationsEnabled,
} from '../../utils/featureToggles'
import {useJobId} from '../EditPipelinePage.hooks'

import type {SettingsSidebarContentFragment$key} from './__generated__/SettingsSidebarContentFragment.graphql'
import JobFilesPublicationSidebar from './JobSettingsSidebar/JobFilesPublicationSidebar/JobFilesPublicationSidebar'
import JobOutputParametersSidebar from './JobSettingsSidebar/JobOutputParametersSidebar/JobOutputParametersSidebar'
import JobParametersSidebar from './JobSettingsSidebar/JobParametersSidebar/JobParametersSidebar'
import type {JobSettingsSidebarComponent} from './JobSettingsSidebar/JobSettingsSidebar'
import JobStepSidebar from './JobSettingsSidebar/JobStepSidebar/JobStepSidebar'
import PipelineSettingsParametersSidebar from './PipelineSettingsParametersSidebar/PipelineSettingsParametersSidebar'
import PipelineSettingsSecretsSidebar from './PipelineSettingsSecretsSidebar/PipelineSettingsSecretsSidebar'
import NotificationEditor from './PipelineSettingsSidebar/PipelineNotifications/editor/NotificationEditor'
import PipelineRepositorySidebar from './PipelineSettingsSidebar/PipelineRepositories/PipelineRepositorySidebar/PipelineRepositorySidebar'
import PipelineSettingsSidebar from './PipelineSettingsSidebar/PipelineSettingsSidebar'
import PipelineSettingsTriggerSidebar from './PipelineSettingsTriggerSidebar/PipelineSettingsTriggerSidebar'
import {sideBarNavigatiobSearchParam} from './SettingsSidebarContent.const'
import {useNavigateSearchParamSidebar} from './SettingsSidebarContent.hooks'
import SidebarSliderTransition from './SidebarSlider/SidebarSliderTransition'

import styles from './SettingsSidebarContent.module.css'

const fragment = graphql`
  fragment SettingsSidebarContentFragment on PipelineRest {
    ...PipelineRepositorySidebarFragment
    parentProject {
      ...pipelineParentProjectFragment
    }
    headBuildType {
      ...pipelineHeadBuildTypeFragment
    }
  }
`

type SettingsSidebarContentProps = {
  pipelineKey: SettingsSidebarContentFragment$key | null
  jobSettingsSidebarEntryPoint?: PreloadedEntryPoint<JobSettingsSidebarComponent>
}

function SettingsSidebarContent({
  pipelineKey,
  jobSettingsSidebarEntryPoint,
}: SettingsSidebarContentProps) {
  const pipeline = useFragment(fragment, pipelineKey)
  const pipelineHeadBuildTypeKey = pipeline?.headBuildType ?? null
  const pipelineParentProjectKey = pipeline?.parentProject ?? null
  const selectedJob = useJobId()
  const searchParamsSet = new Set(Object.values(sideBarNavigatiobSearchParam))
  const {
    [sideBarNavigatiobSearchParam.step]: navigateStepParam,
    [sideBarNavigatiobSearchParam.parameters]: navigateParametersParam,
    [sideBarNavigatiobSearchParam.repository]: navigateRepositoryParam,
    [sideBarNavigatiobSearchParam.notification]: navigateNotificationParam,
    [sideBarNavigatiobSearchParam.outputParameters]: navigateOutputParametersParam,
    [sideBarNavigatiobSearchParam.sharedFiles]: navigateSharedFilesParam,
    [sideBarNavigatiobSearchParam.secrets]: navigateSecretsParam,
    [sideBarNavigatiobSearchParam.trigger]: navigateTriggerParam,
  } = useNavigateSearchParamSidebar(searchParamsSet)
  const hasNotificationId = !!navigateNotificationParam && isNotificationsFeatureEnabled

  return (
    <StoredSettingsValueProvider>
      <div className={styles.content}>
        <Suspense>
          {selectedJob != null ? (
            jobSettingsSidebarEntryPoint != null && (
              <Fragment>
                <SidebarSliderTransition
                  key="jobStepSidebar"
                  triggerAnimationStart={!!navigateStepParam}
                >
                  <JobStepSidebar
                    index={navigateStepParam}
                    pipelineHeadBuildTypeKey={pipelineHeadBuildTypeKey}
                  />
                </SidebarSliderTransition>
                <SidebarSliderTransition triggerAnimationStart={!!navigateSharedFilesParam}>
                  <JobFilesPublicationSidebar pipelineHeadBuildTypeKey={pipelineHeadBuildTypeKey} />
                </SidebarSliderTransition>
                <SidebarSliderTransition triggerAnimationStart={!!navigateParametersParam}>
                  <JobParametersSidebar />
                </SidebarSliderTransition>
                <SidebarSliderTransition triggerAnimationStart={!!navigateOutputParametersParam}>
                  <JobOutputParametersSidebar />
                </SidebarSliderTransition>
                <EntryPointContainer
                  entryPointReference={jobSettingsSidebarEntryPoint}
                  props={{pipelineHeadBuildTypeKey}}
                />
              </Fragment>
            )
          ) : (
            <Fragment>
              <SidebarSliderTransition
                key="pipelineSettingsParametersSidebar"
                triggerAnimationStart={!!navigateParametersParam}
              >
                <PipelineSettingsParametersSidebar />
              </SidebarSliderTransition>
              <SidebarSliderTransition triggerAnimationStart={!!navigateSecretsParam}>
                <Suspense>
                  <PipelineSettingsSecretsSidebar />
                </Suspense>
              </SidebarSliderTransition>
              <SidebarSliderTransition triggerAnimationStart={!!navigateTriggerParam}>
                <PipelineSettingsTriggerSidebar index={navigateTriggerParam} />
              </SidebarSliderTransition>
              <SidebarSliderTransition triggerAnimationStart={!!navigateRepositoryParam}>
                <PipelineRepositorySidebar index={navigateRepositoryParam} pipelineKey={pipeline} />
              </SidebarSliderTransition>
              {isNotificationsFeatureEnabled && isPipelineNotificationsEnabled && (
                <SidebarSliderTransition triggerAnimationStart={hasNotificationId}>
                  <NotificationEditor />
                </SidebarSliderTransition>
              )}
              <PipelineSettingsSidebar pipelineParentProjectKey={pipelineParentProjectKey} />
            </Fragment>
          )}
        </Suspense>
      </div>
    </StoredSettingsValueProvider>
  )
}

export default memo(SettingsSidebarContent)
