import {useAppDispatch, useAppSelector} from '../../../../../../../hooks/react-redux'
import {usePipelineId} from '../../../../hooks/pipeline'
import {matchError} from '../../../../utils/validators'
import {validateField} from '../../../EditPipelinePage.actions'
import {getDraft, getPipelineErrorMessage} from '../../../EditPipelinePage.selectors'
import {
  pipelineDraft,
  pipelineErrors,
  pipelineForm,
  pipelineSecrets,
  pipelineSecrets as pipelineSecretsSlice,
} from '../../../slices/EditPipelinePage.slices'
import {FormType} from '../../../slices/EditPipelinePage.slices.types'

function usePipelineSecretControl(savedName: string) {
  const dispatch = useAppDispatch()
  const pipelineId = usePipelineId()
  const formErrorSpotId = {
    pipelineId,
    formType: FormType.SECRET,
    formId: savedName,
  }
  const formSpotParamId = {pipelineId, type: FormType.SECRET, id: savedName}
  const secretNameErrorMessage = useAppSelector(
    getPipelineErrorMessage({
      ...formErrorSpotId,
      fieldName: 'name',
    }),
  )
  const secretValueErrorMessage = useAppSelector(
    getPipelineErrorMessage({
      ...formErrorSpotId,
      fieldName: 'value',
    }),
  )
  const secretValue = useAppSelector(
    state => state.pipelines.pipelineSecrets[pipelineId]?.[savedName],
  )
  const secretName = useAppSelector(
    state => state.pipelines.pipelineDraft[pipelineId]?.renamed?.secrets?.[savedName] ?? savedName,
  )
  const secretValueExisting = useAppSelector(
    state => getDraft(state, pipelineId)?.settings?.secrets?.[savedName],
  )
  const changeSecretNameHandler = (newName: string) =>
    dispatch(pipelineDraft.actions.renameSecret({id: pipelineId, name: newName, savedName}))
  const secretNameInputChangeHandler = ({
    currentTarget,
  }: React.ChangeEvent<HTMLTextAreaElement>) => {
    const {value} = currentTarget
    changeSecretNameHandler(value)
    dispatch(validateField(formSpotParamId, 'name'))
  }
  const secretValueInputChangeHandler = ({
    currentTarget,
  }: React.ChangeEvent<HTMLTextAreaElement>) => {
    const {value} = currentTarget
    dispatch(
      pipelineErrors.actions.clear({
        ...formErrorSpotId,
        fieldName: 'value',
      }),
    )
    dispatch(pipelineSecretsSlice.actions.set({pipelineId, savedName, value}))
  }
  const deleteSecretHandler = () => {
    dispatch(pipelineDraft.actions.deleteSecret({id: pipelineId, savedName}))
    dispatch(pipelineErrors.actions.clear(formErrorSpotId))
    dispatch(pipelineSecretsSlice.actions.unset({pipelineId, savedName}))
  }
  const secretRestoreButtonClickHandler = () =>
    dispatch(pipelineDraft.actions.restoreSecret({id: pipelineId, savedName}))
  const secretDeleteButtonClickHandler = () => {
    dispatch(pipelineDraft.actions.deleteSecret({id: pipelineId, savedName}))
    dispatch(pipelineErrors.actions.clear(formErrorSpotId))
    dispatch(pipelineForm.actions.close(formSpotParamId))
    dispatch(pipelineSecrets.actions.unset({pipelineId, savedName}))
  }
  const isFormInvalid = useAppSelector(state =>
    state.pipelines.pipelineErrors.some(matchError(formErrorSpotId)),
  )

  return {
    secretName,
    secretValue,
    secretValueExisting,
    //
    isFormInvalid,
    secretNameErrorMessage,
    secretValueErrorMessage,
    //
    deleteSecretHandler,
    //
    secretNameInputChangeHandler,
    secretValueInputChangeHandler,
    secretRestoreButtonClickHandler,
    secretDeleteButtonClickHandler,
  }
}

export default usePipelineSecretControl
