import type {LayoutProps, RankedTester, VerticalLayout} from '@jsonforms/core'
import {rankWith, uiTypeIs} from '@jsonforms/core'
import {JsonFormsDispatch, withJsonFormsLayoutProps} from '@jsonforms/react'

import JobStepAdvancedSettingsSection from '../../../JobStepAdvancedSettingsSection/JobStepAdvancedSettingsSection'

function JsonFormAdvancedSettingsSectionLayout({
  uischema,
  schema,
  path,
  enabled,
  renderers,
  cells,
}: LayoutProps) {
  const {elements} = uischema as VerticalLayout

  return (
    <JobStepAdvancedSettingsSection>
      {elements.map((child, index) => {
        const key = `${path}-${index}`

        return (
          <JsonFormsDispatch
            key={key}
            uischema={child}
            schema={schema}
            path={path}
            enabled={enabled}
            renderers={renderers}
            cells={cells}
          />
        )
      })}
    </JobStepAdvancedSettingsSection>
  )
}

export const jsonFormAdvancedSettingsSectionLayoutTester: RankedTester = rankWith(
  1,
  uiTypeIs('AdvancedSettingsSection'),
)

export default withJsonFormsLayoutProps(JsonFormAdvancedSettingsSectionLayout)
