import AddIcon from '@jetbrains/icons/add.svg'
import Button from '@jetbrains/ring-ui-built/components/button/button'

import PipelineParameter from '../../EditPipelinePage/SettingsSidebarContent/PipelineSettingsSidebar/PipelineParameters/PipelineParameter/PipelineParameter'
import SidebarHeader from '../../EditPipelinePage/SettingsSidebarContent/SidebarSlider/Header/SidebarHeader'

import ParametersSidebarFooter from './ParametersSidebarFooter/ParametersSidebarFooter'
import useParametersSidebar from './useParametersSidebar'

import styles from './ParametersSidebar.module.css'

type ParametersSidebarProps = {
  parameters?: Record<string, string | undefined>
  deleted?: string[]
  errorMessage?: string
  onDone?: () => void
  onAdd?: () => void
  title?: string
  subTitle?: React.ReactNode
}

function ParametersSidebar({
  parameters = {},
  deleted,
  errorMessage,
  onAdd,
  onDone,
  title,
  subTitle,
}: ParametersSidebarProps) {
  const {
    parametersKeys,
    lastNameInputRef,
    hasParametersFormErrorMessage,
    isShowBottomAddButton,
    clickAddParameterButtonHandler,
  } = useParametersSidebar(parameters, onAdd, errorMessage)

  return (
    <div className={styles.sidebar}>
      <div className={styles.content}>
        <SidebarHeader title={title} subTitle={subTitle} border onClick={onDone} />
        <div className={styles.continater}>
          <Button
            icon={AddIcon}
            title="Add parameter"
            onClick={clickAddParameterButtonHandler}
            className={styles.addParameterButton}
          >
            {'Add parameter'}
          </Button>
          <div className={styles.parameters}>
            {parametersKeys.map(key => {
              const value = parameters[key]
              const isDeleted = deleted?.includes(key)

              return (
                <PipelineParameter
                  isEditMode
                  inputRef={lastNameInputRef}
                  key={key}
                  value={value}
                  name={key}
                  deleted={isDeleted}
                />
              )
            })}
          </div>
          {isShowBottomAddButton && (
            <Button
              icon={AddIcon}
              title="Add parameter"
              onClick={clickAddParameterButtonHandler}
              className={styles.addParameterButton}
            >
              {'Add parameter'}
            </Button>
          )}
        </div>
      </div>
      <ParametersSidebarFooter onDone={onDone} hasErrorMessage={hasParametersFormErrorMessage} />
    </div>
  )
}

export default ParametersSidebar
