import plur from 'plur'
import {useMemo} from 'react'
import {useSearchParams} from 'react-router'

import {HighlightSpotId} from '../../../../components/HighlighterTextField/HighlighterTextFieldContext.types'
import {sideBarNavigatiobSearchParam} from '../../SettingsSidebarContent.const'

import usePipelineParametersStore from './usePipelineParametersStore'

function usePipelineParameters() {
  const {
    summaryNote,
    parameters,
    parametersLength,
    renamedParameters,
    formSpotParamId,
    formErrorSpotId,
    deletedParameters,
    parametersFormErrorMessage,
    existingParametersLength,
    changeNameHandler,
    changeValueHandler,
    restoreParametersHandler,
    deleteParametersHandler,
    confirmParametersHandler,
  } = usePipelineParametersStore()
  const [searchParams, setSearchParams] = useSearchParams()
  const parametersControlValue = useMemo(
    () => ({
      parameters,
      renamedParameters,
      formSpotParamId,
      formErrorSpotId,
      valueHighlightSpotId: HighlightSpotId.PIPELINEPARAMETER,
      onNameChange: changeNameHandler,
      onValueChange: changeValueHandler,
      onRestore: restoreParametersHandler,
      onDelete: deleteParametersHandler,
      onConfirm: confirmParametersHandler,
    }),
    [
      changeNameHandler,
      changeValueHandler,
      confirmParametersHandler,
      deleteParametersHandler,
      formErrorSpotId,
      formSpotParamId,
      parameters,
      renamedParameters,
      restoreParametersHandler,
    ],
  )
  const isSettingsBlockCollapsible = !!parametersLength
  const settingsBlockTitle = existingParametersLength
    ? plur('Parameter', existingParametersLength)
    : 'No Parameters'
  const searchParamsObject = Object.fromEntries(searchParams.entries())
  const clickEditParametersHandler = () =>
    setSearchParams({
      ...searchParamsObject,
      [sideBarNavigatiobSearchParam.parameters]: 'true',
    })

  return {
    summaryNote,
    parameters,
    deletedParameters,
    settingsBlockTitle,
    isSettingsBlockCollapsible,
    parametersFormErrorMessage,
    parametersControlValue,
    clickEditParametersHandler,
  }
}

export default usePipelineParameters
