import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'

import EditButton from '../../../../../components/EditButton/EditButton'
import VcsProviderIcon from '../../../../../components/VcsProviderIcon/VcsProviderIcon'
import {VcsProviderType} from '../../../../../services/pipelinesApi.types'
import {
  isPullRequestsFeatureEnabled,
  isStatusPublishingFeatureEnabled,
} from '../../../../../utils/featureToggles'
import ConfigurationStorageSectionPreview from '../NewPipelineRepositoryForm/ConfigurationStorageSection/ConfigurationStorageSectionPreview'
import styles from '../PipelineRepository/PipelineRepository.module.css'

import {isStatusPublishingAvailable} from './PipelineRepositoryPreview.utils'

import SwitcherLabel from 'src/components/common/SwitcherLabel/SwitcherLabel'

type PipelineRepositoryPreviewProps = {
  className?: string
  vcsProviderType?: VcsProviderType | null
  toggleEditModeHandler: (state: boolean) => () => void
  url?: string
  repositoryName?: string
  branch?: string
  branchSpecLabel?: string
  isRoot: boolean
  canEditable: boolean
  canRestore: boolean
  isStatusPublishingEnabled?: boolean
  deleteRepositoryHandler: () => void
  onRestore?: () => void
  canDeletable?: boolean
  errorMessage?: string
  isExternalVcsRoot?: boolean
}

function PipelineRepositoryPreview({
  className,
  vcsProviderType,
  repositoryName,
  url,
  deleteRepositoryHandler,
  toggleEditModeHandler,
  canEditable,
  canDeletable,
  canRestore,
  onRestore,
  branchSpecLabel,
  branch,
  isRoot,
  errorMessage,
  isStatusPublishingEnabled,
  isExternalVcsRoot,
}: PipelineRepositoryPreviewProps) {
  const vcsProviderIconType = isExternalVcsRoot
    ? VcsProviderType.EXISTING_VCS_ROOT
    : vcsProviderType

  return (
    <div className={className}>
      {isPullRequestsFeatureEnabled ? null : (
        <VcsProviderIcon className={styles.icon} vcsProviderType={vcsProviderIconType} />
      )}
      <div
        role="presentation"
        onClick={toggleEditModeHandler(true)}
        className={styles.defaultBranch}
      >
        <div className={styles.repository}>
          <div>
            <div
              className={classNames(styles.repositoryName, {
                [styles.repositoryNameMissing]: !repositoryName,
              })}
            >
              {isPullRequestsFeatureEnabled ? (
                <VcsProviderIcon
                  className={classNames(styles.icon, styles.inline)}
                  vcsProviderType={vcsProviderIconType}
                />
              ) : null}
              {repositoryName ? repositoryName : 'Missing URL'}
            </div>
          </div>
          {url && <div className={styles.url}>{url}</div>}
          {branch && <div className={styles.branch}>{`Default branch: ${branch}`}</div>}
          {branchSpecLabel && <div className={styles.branchRules}>{branchSpecLabel}</div>}
          {isRoot && <ConfigurationStorageSectionPreview className={styles.vcsStorePreview} />}
          {isStatusPublishingFeatureEnabled && isStatusPublishingAvailable(vcsProviderType) && (
            <div className={styles.publishStatus}>
              <SwitcherLabel className={styles.tag} on={isStatusPublishingEnabled} />
              {'Publish status to repository'}
            </div>
          )}
          <div className={styles.errorMessage}>{errorMessage}</div>
        </div>
        {canEditable && (
          <EditButton iconClassName={styles.editButtonIcon} className={styles.actionButton} />
        )}
      </div>
      {canDeletable && (
        <IconButton
          className={styles.actionButton}
          icon={'trash'}
          title={'Delete'}
          aria-label={'Delete'}
          onClick={deleteRepositoryHandler}
        />
      )}
      {canRestore && (
        <IconButton
          className={styles.actionButton}
          icon={'update'}
          title={'Restore'}
          aria-label={'Restore'}
          onClick={onRestore}
        />
      )}
    </div>
  )
}

export default PipelineRepositoryPreview
