import deepEqual from 'fast-deep-equal'
import uniq from 'lodash/uniq'
import plur from 'plur'
import {memo, useRef} from 'react'

import SettingsBlock from '../../../../components/SettingsBlock/SettingsBlock'
import {usePipelineId} from '../../../../hooks/pipeline'
import usePermissionCanEditPipeline from '../../../../hooks/usePermissionCanEditPipeline'
import {getDraft, getPipelineOriginalIntegrations} from '../../../EditPipelinePage.selectors'
import {collapsedBlocks, pipelineForm} from '../../../slices/EditPipelinePage.slices'
import {FormType} from '../../../slices/EditPipelinePage.slices.types'
import AddIntegration from '../../Integrations/AddIntegration/AddIntegration'
import Integration from '../../Integrations/Integration/Integration'
import {addIntegration} from '../../Integrations/Integrations.actions'
import {integrations} from '../../Integrations/Integrations.consts'
import {useAvailableIntegrations} from '../../Integrations/Integrations.hooks'

import {useAppDispatch, useAppSelector} from 'src/hooks/react-redux'
import {notNull} from 'src/utils/guards'

function PipelineIntegrations() {
  const {canEditPipeline} = usePermissionCanEditPipeline()
  const availableIntegrations = useAvailableIntegrations()
  const pipelineId = usePipelineId()
  const integrationsas = useAppSelector(state => getDraft(state, pipelineId)?.integrations) ?? []
  const savedIntegrations = useAppSelector(getPipelineOriginalIntegrations(pipelineId)) ?? []
  const count = availableIntegrations.filter(({isDeleted}) => !isDeleted).length

  const dispatch = useAppDispatch()

  const settingsBlockId = 'pipeline-integrations'
  const settingsBlockTitle = count ? plur('Integration', count) : 'No Integrations'

  const addIntegrationButtonRef = useRef<HTMLInputElement>(null)

  return (
    <>
      <SettingsBlock
        id={settingsBlockId}
        collapsible={availableIntegrations.length > 0 && canEditPipeline}
        collapsedDefault
        collapsedNote={uniq(
          availableIntegrations
            .filter(({isDeleted}) => !isDeleted)
            .map(({type}) => integrations[type]?.displayName)
            .filter(notNull),
        ).join(', ')}
        title={settingsBlockTitle}
        onAddClick={canEditPipeline ? () => addIntegrationButtonRef?.current?.click() : undefined}
        customActions={anchor => (
          <AddIntegration
            anchor={<div ref={addIntegrationButtonRef}>{anchor}</div>}
            onSelectIntegration={type => {
              const integrationId = dispatch(
                addIntegration({
                  pipelineId,
                  type,
                  parameters: {},
                }),
              )
              dispatch(
                collapsedBlocks.actions.toggle({
                  id: settingsBlockId,
                  collapsed: false,
                }),
              )
              dispatch(
                pipelineForm.actions.open({
                  pipelineId,
                  id: integrationId,
                  type: FormType.PIPELINE_INTEGRATION,
                  isAdd: true,
                }),
              )
            }}
          />
        )}
      >
        {availableIntegrations.map((integration, index) => {
          const {type, parameters, isDeleted, id} = integration
          const isUnsaved =
            !isDeleted && !deepEqual(savedIntegrations[index], integrationsas[index])
          const {displayName} = parameters
          const integrationKey = `${displayName}_${type}`

          return (
            <Integration
              id={id!}
              key={integrationKey}
              type={type}
              unsaved={isUnsaved}
              parameters={parameters}
              isDeleted={isDeleted}
            />
          )
        })}
      </SettingsBlock>
    </>
  )
}

export default memo(PipelineIntegrations)
