import {memo} from 'react'

import {usePipelineId} from '../../../../hooks/pipeline'
import {usePipelineNameOrDraft} from '../../../EditPipelinePage.hooks'
import {pipelineDraft} from '../../../slices/EditPipelinePage.slices'
import NameSection from '../../NameSection/NameSection'

import {useAppDispatch} from 'src/hooks/react-redux'

function PipelineName() {
  const id = usePipelineId()
  const name = usePipelineNameOrDraft() ?? ''
  const dispatch = useAppDispatch()

  return (
    <NameSection
      name={name}
      aria-label={'Pipeline Name'}
      onNameChange={newName => dispatch(pipelineDraft.actions.setPipelineName({id, name: newName}))}
    />
  )
}

export default memo(PipelineName)
