import {memo} from 'react'
import {graphql, useLazyLoadQuery} from 'react-relay'

import type {JobDirectoryPopupContentQuery} from './__generated__/JobDirectoryPopupContentQuery.graphql'
import JobDirectoryTree from './JobDirectoryTree/JobDirectoryTree'
import type {JobDirectoryType} from './JobDirectoryTree/JobDirectoryTree.types'

interface Props {
  buildLocator: string
  onlyDirectories?: boolean
  onSelect: (type: JobDirectoryType, path: string) => void
}

const query = graphql`
  query JobDirectoryPopupContentQuery($buildLocator: String!) {
    pipelineBuildDirectoryStructure(buildLocator: $buildLocator)
  }
`

function JobDirectoryPopupContent(props: Props) {
  const {buildLocator, onlyDirectories, onSelect} = props

  const {pipelineBuildDirectoryStructure} = useLazyLoadQuery<JobDirectoryPopupContentQuery>(query, {
    buildLocator,
  })

  return (
    <JobDirectoryTree
      entities={pipelineBuildDirectoryStructure}
      onlyDirectories={onlyDirectories}
      onSelect={onSelect}
    />
  )
}

export default memo(JobDirectoryPopupContent)
