import classNames from 'classnames'
import {memo} from 'react'

import Actions from '../../../../../components/Actions/Actions'
import PipelineSecretForm from '../PipelineSecretForm/PipelineSecretForm'
import usePipelineSecretControl from '../usePipelineSecretControl'

import {emptySecretTitleName, emptySecretTitleValue, passwordMask} from './PipelineSecret.const'
import type {PipelineSecretProps} from './PipelineSecret.types'

import styles from './PipelineSecret.module.css'

function PipelineSecret({
  originalName,
  inputRef,
  disabled,
  isEditMode,
  deleted,
}: PipelineSecretProps) {
  const {
    secretName,
    secretValue,
    secretValueExisting,
    secretRestoreButtonClickHandler,
    secretDeleteButtonClickHandler,
  } = usePipelineSecretControl(originalName)
  const secretInputWrapperClasses = classNames(styles.secretInputWrapper, {
    [styles.secretInputWrapperDeleted]: deleted,
    [styles.secretInputWrapperEdit]: isEditMode,
  })
  const isSecretNameEmpty = !secretName
  const isSecretValueEmpty = !secretValue && !secretValueExisting
  const secretNameTitle = isSecretNameEmpty ? emptySecretTitleName : secretName

  return (
    <div className={styles.secret}>
      {isEditMode && !deleted ? (
        <PipelineSecretForm
          savedName={originalName}
          inputRef={inputRef}
          onDelete={secretDeleteButtonClickHandler}
        />
      ) : (
        <div className={secretInputWrapperClasses}>
          <div className={classNames(styles.secretName, {[styles.emptyField]: isSecretNameEmpty})}>
            {secretNameTitle}
          </div>
          <span
            className={classNames(styles.secretValue, {[styles.emptyField]: isSecretValueEmpty})}
          >
            {isSecretValueEmpty ? emptySecretTitleValue : passwordMask}
          </span>
        </div>
      )}
      {(!isEditMode || deleted) && (
        <Actions
          className={styles.secretActions}
          deleted={deleted}
          disabled={disabled}
          onRestoreClick={secretRestoreButtonClickHandler}
          onDeleteClick={secretDeleteButtonClickHandler}
        />
      )}
    </div>
  )
}

export default memo(PipelineSecret)
