import Link from '@jetbrains/ring-ui-built/components/link/link'

import {Size} from '../../../../components/Input'
import Input from '../../../../components/Input/Input'
import PipelineTextInfo from '../../../../components/PipelineTextInfo/PipelineTextInfo'
import SelectRunner from '../../../../components/SelectRunner/SelectRunner'
import type {pipelineHeadBuildTypeFragment$key} from '../../../../hooks/__generated__/pipelineHeadBuildTypeFragment.graphql'
import SidebarHeader from '../../SidebarSlider/Header/SidebarHeader'
import JobStepFormProvider from '../JobSteps/JobStep/JobStepFormContext/JobStepFormContext'
import JobStepJsonForm from '../JobSteps/JobStep/JobStepJsonForm/JobStepJsonForm'

import {availableSoftwareLink} from './JobStepSidebar.consts'
import JobStepSidebarFooter from './JobStepSidebarFooter/JobStepSidebarFooter'
import useJobStepSidebar from './useJobStepSidebar'

import styles from './JobStepSidebar.module.css'

type JobStepSidebarProps = {
  pipelineHeadBuildTypeKey: pipelineHeadBuildTypeFragment$key | null
  index?: string | null
}

const defaultStepIndex = '0'

function JobStepSidebar({pipelineHeadBuildTypeKey, index = defaultStepIndex}: JobStepSidebarProps) {
  const stepIndex = Number(index)
  const {
    jobRunnersKey,
    valueProvider,
    jobSidebarTitle,
    onStepTypeChange,
    currenStepType,
    currentStepName,
    currentStep,
    errorMessage,
    isApiRunnersAvailable,
    changeNameInputHandler,
    clickJobDoneButtonHandler,
    clickDeleteButtonHandler,
    clickButtonBackHandler,
  } = useJobStepSidebar(stepIndex, pipelineHeadBuildTypeKey)

  return (
    <div className={styles.sidebar}>
      <div className={styles.content}>
        <SidebarHeader onClick={clickButtonBackHandler} title={jobSidebarTitle} />
        <PipelineTextInfo className={styles.textInfo}>
          <Link target="_blank" href={availableSoftwareLink} rel="noreferrer">{`List`}</Link>
          {' of pre-installed software on the agent'}
        </PipelineTextInfo>
        <div className={styles.selectRunner}>
          <SelectRunner
            onSelect={runner => onStepTypeChange(stepIndex, runner!.toLowerCase())}
            selected={currenStepType}
            runners={jobRunnersKey}
          />
        </div>
        <div className={styles.stepContainer}>
          <JobStepFormProvider value={valueProvider}>
            <Input
              className={styles.inputName}
              size={Size.FULL}
              value={currentStepName ?? ''}
              label={'Step name'}
              onChange={changeNameInputHandler}
              aria-label="name"
            />
            {isApiRunnersAvailable && currentStep && <JobStepJsonForm type={currentStep.type} />}
          </JobStepFormProvider>
        </div>
      </div>
      <JobStepSidebarFooter
        errorMessage={errorMessage}
        onDone={clickJobDoneButtonHandler}
        onDelete={clickDeleteButtonHandler}
      />
    </div>
  )
}

export default JobStepSidebar
