import {useEffect} from 'react'
import {graphql, useFragment} from 'react-relay'

import {useAppSelector} from '../../../../../hooks/react-redux'
import {useBooleanQueryParamState} from '../../../../../hooks/routes'
import ConfigurationStorageDialog from '../../components/ConfigurationStorageDialog/ConfigurationStorageDialog'
import {useBanners} from '../../contexts/Banners/BannersContext'
import {VALIDATION_ERRROR_MESSAGE} from '../../contexts/Banners/BannersContext.types'
import {usePipelineId} from '../../hooks/pipeline'
import {AlertMessageType} from '../../types/AlertMessages'
import {useConfigurationStorage} from '../EditPipelinePage.hooks'

import type {EditPipelineConfigurationDialogFragment$key} from './__generated__/EditPipelineConfigurationDialogFragment.graphql'

const fragment = graphql`
  fragment EditPipelineConfigurationDialogFragment on PipelineRest {
    ...ConfigurationStorageCanEditFragment
    ...ConfigurationStorageSwitchFragment
  }
`

type Props = {
  pipelineKey: EditPipelineConfigurationDialogFragment$key | null
}

function EditPipelineConfigurationDialog({pipelineKey}: Props) {
  const pipeline = useFragment(fragment, pipelineKey)
  const id = usePipelineId()

  const {dialogVisible, isLoading, onConfigurationStorageChange} = useConfigurationStorage(pipeline)
  const [_, setIsYaml] = useBooleanQueryParamState('yaml')
  const isParsed = useAppSelector(state => state.pipelines.pipelineYamlValidity[id]?.isParsed)
  const {addBanner} = useBanners()

  useEffect(() => {
    if (isParsed != null && !isParsed) {
      setIsYaml(true)
      addBanner(id, {
        key: `${id}-${VALIDATION_ERRROR_MESSAGE}`,
        type: AlertMessageType.INFO,
        message:
          'The Pipelines project loaded from the YAML configuration file that contains errors. The Visual editor is disabled until these issues are resolved.',
      })
    }
  }, [addBanner, id, isParsed, setIsYaml])

  return (
    <ConfigurationStorageDialog
      isCreationMode
      isLoading={isLoading}
      visible={dialogVisible}
      onConfirm={onConfigurationStorageChange}
      pipelineKey={pipeline}
    />
  )
}

export default EditPipelineConfigurationDialog
