import type {SelectItem} from '@jetbrains/ring-ui-built/components/select/select'
import Select from '@jetbrains/ring-ui-built/components/select/select'
import type {
  ControlProps,
  JsonSchema4,
  JsonSchema7,
  OwnPropsOfEnum,
  RankedTester,
} from '@jsonforms/core'
import {rankWith, uiTypeIs} from '@jsonforms/core'
import {type TranslateProps, withJsonFormsEnumProps, withTranslateProps} from '@jsonforms/react'
import {Fragment, memo, type SyntheticEvent, useCallback, useMemo} from 'react'

import HighlighterTextInput from '../../../../../../../../components/HighlighterTextField/HighlighterTextInput'
import {Size} from '../../../../../../../../components/Input'

import JsonFormHelpDetailsIcon from './JsonFormHelpDetailsIcon'

import styles from './JsonFormMavenVersionPickerControl.module.css'

type RootSchema = (JsonSchema4 | JsonSchema7) & {
  defs?: Record<
    string,
    {
      enumNames?: string[]
      enumDescription?: string[]
      enumValues?: string[]
    }
  >
}

type JsonFormEnumControlProps = {
  rootSchema: RootSchema
} & ControlProps &
  OwnPropsOfEnum &
  TranslateProps

const customOption = 'custom'

function JsonFormMavenVersionPickerControl(props: JsonFormEnumControlProps) {
  const {id, handleChange, path, description, label, visible, rootSchema, data} = props
  const value = data != null ? data : undefined
  const selectHandler = useCallback(
    (selected: SelectItem | null, _?: Event | SyntheticEvent) => {
      const isCustomSelected = selected?.key === customOption
      const newValue = isCustomSelected ? '' : selected?.key
      handleChange(path, newValue)
    },
    [handleChange, path],
  )
  const inputChangeHandler = useCallback(
    ({target}: React.ChangeEvent<HTMLInputElement>) => {
      handleChange(path, target.value)
    },
    [handleChange, path],
  )
  const rootSchemaDef = rootSchema?.defs?.['maven-version'] ?? {}
  const selectOptions: SelectItem[] = useMemo(() => {
    const enumNames = rootSchemaDef?.enumNames ?? []
    const enumDescription = rootSchemaDef?.enumDescription ?? []
    return (
      rootSchemaDef?.enumValues?.map((key, index) => ({
        key,
        label: enumNames[index],
        details: enumDescription[index],
      })) ?? []
    )
  }, [rootSchemaDef?.enumDescription, rootSchemaDef?.enumNames, rootSchemaDef?.enumValues])
  const selectedOption = useMemo(() => {
    const selectedItem = selectOptions?.find(({key}) => key === value)

    if (!selectedItem || value === '') {
      return selectOptions?.find(({key}) => key === customOption)
    }

    return selectedItem
  }, [selectOptions, value])
  const selectedLabel = useMemo(
    () => (
      <Fragment>
        {label}
        {description && <JsonFormHelpDetailsIcon>{description}</JsonFormHelpDetailsIcon>}
      </Fragment>
    ),
    [description, label],
  )
  const mavenInputLabel = 'Maven home path'
  const isCustomSelected = selectedOption?.key === customOption
  const selectClassName = isCustomSelected ? styles.selectCustom : null

  if (!visible) {
    return null
  }

  return (
    <div className={styles.container}>
      <Select
        id={id}
        selectedLabel={selectedLabel}
        label={label}
        className={selectClassName}
        selected={selectedOption}
        size={Size.FULL}
        data={selectOptions}
        onSelect={selectHandler}
        compact
      />
      {isCustomSelected && (
        <div className={styles.inputCustom}>
          <HighlighterTextInput
            value={value}
            spellCheck={false}
            aria-label={mavenInputLabel}
            onChange={inputChangeHandler}
            placeholder="Enter custom Maven version"
            label={mavenInputLabel}
          />
        </div>
      )}
    </div>
  )
}

export const jsonFormMavenVersionPickerControlTester: RankedTester = rankWith(
  1,
  uiTypeIs('JsonFormMavenVersionPickerControl'),
)

export default withJsonFormsEnumProps(withTranslateProps(memo(JsonFormMavenVersionPickerControl)))
