import type {LayoutProps, RankedTester, VerticalLayout} from '@jsonforms/core'
import {rankWith, uiTypeIs} from '@jsonforms/core'
import {JsonFormsDispatch, withJsonFormsLayoutProps} from '@jsonforms/react'

function JsonFormVerticalLayout({
  uischema,
  schema,
  path,
  enabled,
  visible,
  renderers,
  cells,
}: LayoutProps) {
  const {elements} = uischema as VerticalLayout

  if (!visible) {
    return null
  }

  return elements.map((child, index) => {
    const key = `${path}-${index}`

    return (
      <JsonFormsDispatch
        key={key}
        uischema={child}
        schema={schema}
        path={path}
        enabled={enabled}
        renderers={renderers}
        cells={cells}
      />
    )
  })
}

export const jsonFormVerticalLayoutTester: RankedTester = rankWith(1, uiTypeIs('VerticalLayout'))

export default withJsonFormsLayoutProps(JsonFormVerticalLayout)
