import Button from '@jetbrains/ring-ui-built/components/button/button'
import ButtonGroup from '@jetbrains/ring-ui-built/components/button-group/button-group'
import {objectToQuery} from '@jetbrains/teamcity-ui/dist/utils'
import {useNavigate} from 'react-router'

import {useBooleanQueryParam} from '../../../../../../hooks/routes'
import {RouterButton} from '../../../../../common/RouterLink/RouterLink'
import {usePipelineId} from '../../../hooks/pipeline'
import {useApplyYAMLChangesHandler, useIsEditPipelineYAMLValid} from '../../EditPipelinePage.hooks'
import useSaveChangesError from '../../SaveChanges/hooks/useSaveChangesError'

import styles from './EditPipelineToggle.module.css'

function EditPipelineToggle() {
  const pipelineId = usePipelineId()
  const isYaml = useBooleanQueryParam('yaml')
  const {hasErrors} = useSaveChangesError(pipelineId)
  const navigate = useNavigate()
  const isEditPipelineYAMLValid = useIsEditPipelineYAMLValid()
  const applyYAMLChangesHandler = useApplyYAMLChangesHandler()
  const clickVisualButtonHandler = () => {
    const to = {search: objectToQuery({edit: 'true', yaml: 'false'})}
    applyYAMLChangesHandler()
    navigate(to, {preventScrollReset: true})
  }

  return (
    <div className={styles.toggle}>
      <ButtonGroup>
        <Button
          onClick={clickVisualButtonHandler}
          active={!isYaml}
          disabled={hasErrors || !isEditPipelineYAMLValid}
        >
          {'Visual'}
        </Button>
        <RouterButton
          preventScrollReset
          to={{search: objectToQuery({edit: 'true', yaml: 'true'})}}
          active={isYaml}
          disabled={hasErrors || !isEditPipelineYAMLValid}
        >
          {'YAML'}
        </RouterButton>
      </ButtonGroup>
    </div>
  )
}

export default EditPipelineToggle
