import {rankWith, uiTypeIs} from '@jsonforms/core'
import type {LayoutProps, RankedTester, VerticalLayout} from '@jsonforms/core'
import {JsonFormsDispatch, withJsonFormsLayoutProps} from '@jsonforms/react'

import ShowAllOptions from '../../../ShowAllOptions/ShowAllOptions'

function JsonFormCollapsibleLayout({
  uischema,
  schema,
  path,
  enabled,
  renderers,
  cells,
}: LayoutProps) {
  const {elements} = uischema as VerticalLayout

  return (
    <ShowAllOptions>
      {elements.map((child, index) => {
        const key = `${path}-${index}`

        return (
          <JsonFormsDispatch
            key={key}
            uischema={child}
            schema={schema}
            path={path}
            enabled={enabled}
            renderers={renderers}
            cells={cells}
          />
        )
      })}
    </ShowAllOptions>
  )
}

export const jsonFormCollapsibleLayoutTester: RankedTester = rankWith(
  1,
  uiTypeIs('CollapsibleLayout'),
)

export default withJsonFormsLayoutProps(JsonFormCollapsibleLayout)
