import {useAppSelector} from '../../../../../../../hooks/react-redux'
import BranchSpecificationSelect from '../../../../components/BranchSpecificationSelect/BranchSpecificationSelect'

import {ALL_BRANCHES, DEFAULT_BRANCH} from './PipelineOnChangesTriggerForm.const'
import usePipelineOnChangesTriggerForm from './PipelineOnChangesTriggerForm.hooks'

import styles from './PipelineOnChangesTriggerForm.module.css'

import {usePipelineId} from 'src/components/pages/PipelinesPages/hooks/pipeline'

type Props = {
  index: number
}
function PipelineOnChangesTriggerForm({index}: Props) {
  const id = usePipelineId()
  const trigger = useAppSelector(
    state => state.pipelines.pipelineDraft[id]?.draft?.triggers?.[index],
  )
  const {
    triggerBranches,
    triggerPullRequests,
    branchFilter,
    errorMessage,
    handleSelectBranchSpec,
    handleToggleBranches,
    handleTogglePullRequests,
  } = usePipelineOnChangesTriggerForm(index, trigger)

  return (
    <div>
      <label className={styles.label}>{'Start builds on new changes in'}</label>
      <BranchSpecificationSelect
        isPullRequestsSupported
        isBranchesToggleSupported
        groupClassName={styles.branchSpecPolicy}
        specification={branchFilter ?? ''}
        isBranchesEnabled={triggerBranches}
        isPullRequestsEnabled={triggerPullRequests}
        defaultBranch={DEFAULT_BRANCH}
        allBranches={ALL_BRANCHES}
        onSelectSpecification={handleSelectBranchSpec}
        onToggleBranches={handleToggleBranches}
        onTogglePullRequests={handleTogglePullRequests}
      />
      {errorMessage && <div className={styles.errorMessage}>{errorMessage}</div>}
    </div>
  )
}
export default PipelineOnChangesTriggerForm
