import Radio from '@jetbrains/ring-ui-built/components/radio/radio'
import classNames from 'classnames'
import {memo, useCallback, useEffect, useRef, useState} from 'react'
import type * as React from 'react'

import HighlighterTextField from '../../../../../../../components/HighlighterTextField/HighlighterTextField'
import HighlighterTextInput from '../../../../../../../components/HighlighterTextField/HighlighterTextInput'
import {useStoredSettingsValue} from '../../../../../../../contexts/StoredSettingsValue/StoredSettingsValueContext'
import {useDraftStepError} from '../../../../../../EditPipelinePage.hooks'
import {
  DOCKERFILE_PATH_PROPERTY_NAME,
  DOCKERFILE_SOURCE_PROPERTY_NAME,
} from '../JobStepRunInDocker.consts'
import {useStoredDockerData} from '../JobStepRunInDocker.hooks'
import type {JobStepRunInDockerProps} from '../JobStepRunInDocker.types'
import {getDockerValues} from '../JobStepRunInDocker.utils'

import {
  DOCKERFILE_PATH_PLACEHOLDER,
  DOCKERFILE_PATH_RADIO_NAME,
  DOCKERFILE_SOURCE_PLACEHOLDER,
  DOCKERFILE_SOURCE_RADIO_NAME,
} from './JobStepRunInDockerDockerfile.consts'
import {DockerfileMode, isDockerfileMode} from './JobStepRunInDockerDockerfile.types'

import styles from './JobStepRunInDockerDockerfile.module.css'

function JobStepRunInDockerDockerfile({
  step,
  stepIndex,
  onStepPropertyChange,
}: JobStepRunInDockerProps) {
  const dockerfileSourceRef = useRef<HTMLTextAreaElement>(null)
  const dockerfilePathRef = useRef<HTMLInputElement>(null)

  const {setValueToStoredSettings} = useStoredSettingsValue()
  const {
    storedDockerfileSourceKey,
    storedDockerfilePathKey,
    storedDockerfilePathValue,
    storedDockerfileSourceValue,
  } = useStoredDockerData(step.type, stepIndex)
  const {dockerfileSourceValue, dockerfilePathValue} = getDockerValues(step)
  const defaultDockerfilePath =
    dockerfilePathValue != null ? DockerfileMode.PATH : DockerfileMode.SOURCE
  const [dockerfileMode, setDockerfileMode] = useState<DockerfileMode>(defaultDockerfilePath)

  useEffect(() => {
    const ref = dockerfilePathValue != null ? dockerfilePathRef : dockerfileSourceRef

    requestAnimationFrame(() =>
      ref.current?.focus({
        preventScroll: true,
      }),
    )
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  const onChangeDockerfileSource = useCallback(
    (event: React.ChangeEvent<HTMLInputElement> | React.ChangeEvent<HTMLTextAreaElement>) => {
      onStepPropertyChange(stepIndex, DOCKERFILE_SOURCE_PROPERTY_NAME, event.currentTarget.value)
    },
    [stepIndex, onStepPropertyChange],
  )

  const onChangeDockerfilePath = useCallback(
    (event: React.ChangeEvent<HTMLInputElement> | React.ChangeEvent<HTMLTextAreaElement>) => {
      onStepPropertyChange(stepIndex, DOCKERFILE_PATH_PROPERTY_NAME, event.currentTarget.value)
    },
    [stepIndex, onStepPropertyChange],
  )

  const onChangeDockerfileMode = useCallback(
    (mode: string) => {
      if (isDockerfileMode(mode)) {
        if (mode === DockerfileMode.PATH) {
          setValueToStoredSettings(
            storedDockerfileSourceKey,
            dockerfileSourceValue ?? storedDockerfileSourceValue,
          )
          setDockerfileMode(DockerfileMode.PATH)
        } else {
          setValueToStoredSettings(
            storedDockerfilePathKey,
            dockerfilePathValue ?? storedDockerfilePathValue,
          )

          setDockerfileMode(DockerfileMode.SOURCE)
        }
      }
    },
    [
      dockerfilePathValue,
      dockerfileSourceValue,
      setValueToStoredSettings,
      storedDockerfilePathKey,
      storedDockerfilePathValue,
      storedDockerfileSourceKey,
      storedDockerfileSourceValue,
    ],
  )

  const sourceError = useDraftStepError({
    name: DOCKERFILE_SOURCE_PROPERTY_NAME,
    stepIndex,
  })
  const pathError = useDraftStepError({
    name: DOCKERFILE_PATH_PROPERTY_NAME,
    stepIndex,
  })

  return (
    <>
      <Radio value={dockerfileMode} onChange={onChangeDockerfileMode}>
        <Radio.Item className={styles.radio} value={DockerfileMode.SOURCE}>
          {DOCKERFILE_SOURCE_RADIO_NAME}
        </Radio.Item>
        <HighlighterTextField
          data-test="highlighter-text-field-dockerfile-source"
          className={classNames(styles.dockerSourceRadio, styles.dockerfileSource)}
          ref={dockerfileSourceRef}
          placeholder={DOCKERFILE_SOURCE_PLACEHOLDER}
          value={dockerfileSourceValue || storedDockerfileSourceValue || ''}
          disabled={dockerfileMode === DockerfileMode.PATH}
          onChange={onChangeDockerfileSource}
          multiline
          autoComplete="off"
          spellCheck={false}
          aria-label="dockerfile-source"
          error={sourceError ? sourceError : undefined}
        />
        <Radio.Item className={styles.radio} value={DockerfileMode.PATH}>
          {DOCKERFILE_PATH_RADIO_NAME}
        </Radio.Item>
        <HighlighterTextInput
          className={styles.dockerfilePath}
          ref={dockerfilePathRef}
          placeholder={DOCKERFILE_PATH_PLACEHOLDER}
          value={dockerfilePathValue || storedDockerfilePathValue || ''}
          disabled={dockerfileMode === DockerfileMode.SOURCE}
          onChange={onChangeDockerfilePath}
          error={pathError ? pathError : undefined}
          spellCheck={false}
          autoComplete="off"
        />
      </Radio>
    </>
  )
}

export default memo(JobStepRunInDockerDockerfile)
