import {graphql, useFragment} from 'react-relay'
import {useSearchParams} from 'react-router'

import Redirect from '../../../../../../../common/Redirect/Redirect'
import {ProtocolVcsRepository} from '../../../../../components/VcsAnyRepositoryAuthenticationForm/VcsAnyRepositoryAuthenticationForm.consts'
import {usePipelineId, usePipelineParentProjectId} from '../../../../../hooks/pipeline'
import {VcsProviderType} from '../../../../../services/pipelinesApi.types'
import NewPipelineRepositoryForm from '../NewPipelineRepositoryForm/NewPipelineRepositoryForm'
import {usePipelineRepositories} from '../PipelineRepositories.hooks'
import styles from '../PipelineRepository/PipelineRepository.module.css'
import {ROOT_REPOSITORY_KEY} from '../PipelineRepository/PipelineRepository.utils'
import usePipelineRepository from '../PipelineRepository/usePipelineRepository'

import type {PipelineRepositorySidebarFragment$key} from './__generated__/PipelineRepositorySidebarFragment.graphql'

const fragment = graphql`
  fragment PipelineRepositorySidebarFragment on PipelineRest {
    parentProject {
      ...pipelineParentProjectFragment
    }
    ...ConfigurationStorageSwitchFragment
  }
`

type PipelineRepositorySidebarProps = {
  index?: string | null
  pipelineKey: PipelineRepositorySidebarFragment$key | null
}

function PipelineRepositorySidebar({index, pipelineKey}: PipelineRepositorySidebarProps) {
  const pipeline = useFragment(fragment, pipelineKey)
  const pipelineParentProjectKey = pipeline?.parentProject ?? null
  const pipelineId = usePipelineId()
  const parentProjectId = usePipelineParentProjectId(pipelineParentProjectKey)
  const indexNumber = Number(index)
  const {
    mainRepository,
    createdRepositories,
    additionalVcsRoots,
    deletedRepositoriesSet,
    deleteRepositoryHandler,
  } = usePipelineRepositories(pipelineParentProjectKey)
  const isRootIndex = index === ROOT_REPOSITORY_KEY
  const selectedRepository = isRootIndex
    ? mainRepository
    : index != null
      ? additionalVcsRoots[indexNumber]
      : null
  const {url: repositoryUrl = ''} = selectedRepository || {}
  const isDeleted = deletedRepositoriesSet.has(repositoryUrl)
  const [searchParams] = useSearchParams()
  const {
    isAdd,
    formId,
    onChange,
    onConfirm,
    cancelRepositoryFormHandler,
    deleteRepositoryFormHandler,
  } = usePipelineRepository(
    selectedRepository?.url,
    selectedRepository?.branch,
    selectedRepository?.branchSpecification,
    isDeleted,
    isRootIndex,
    indexNumber,
    deleteRepositoryHandler(repositoryUrl, indexNumber),
    selectedRepository?.vcsProviderType,
    selectedRepository?.trackPullRequests,
  )

  if (!selectedRepository && searchParams.has('repository')) {
    searchParams.delete('repository')

    return <Redirect to={{search: searchParams.toString()}} />
  }

  if (!selectedRepository) {
    return null
  }

  const {username, password, sshKey} = selectedRepository
  const repositoryUsername = username ?? sshKey?.name
  const repositoryPassword = password ?? sshKey?.passphrase
  const vcsProviderType = selectedRepository.vcsProviderType
  const isExternal =
    selectedRepository?.isExternal ?? vcsProviderType === VcsProviderType.EXISTING_VCS_ROOT

  return (
    <NewPipelineRepositoryForm
      projectId={parentProjectId ?? undefined}
      pipelineId={pipelineId ?? undefined}
      repositoryUrl={repositoryUrl}
      createdRepositories={createdRepositories}
      vcsRootId={selectedRepository.id}
      name={selectedRepository.name}
      vcsName={selectedRepository.vcsName}
      branch={selectedRepository.branch}
      branchSpec={selectedRepository.branchSpecification}
      externalVcsRootId={selectedRepository?.id}
      vcsProviderType={selectedRepository.vcsProviderType}
      vcsProtocol={sshKey != null ? ProtocolVcsRepository.SSH : ProtocolVcsRepository.HTTPS}
      isPullRequestsEnabled={selectedRepository.trackPullRequests}
      username={repositoryUsername}
      password={repositoryPassword}
      isCreateMode={isAdd}
      formId={formId}
      onConfirm={onConfirm}
      onDelete={deleteRepositoryFormHandler}
      onChange={onChange}
      onCancel={cancelRepositoryFormHandler}
      isRoot={isRootIndex}
      isExternal={isExternal}
      isStatusPublishingEnabled={selectedRepository.isStatusPublishingEnabled}
      className={styles.settingsFormContainer}
      pipelineKey={pipeline}
    />
  )
}

export default PipelineRepositorySidebar
