import type {JsonFormsCore} from '@jsonforms/core'
import {JsonForms} from '@jsonforms/react'
import {useCallback, useMemo} from 'react'

import {useAppDispatch} from '../../../../../../../../../hooks/react-redux'
import {usePipelineId} from '../../../../../../hooks/pipeline'
import {StepTypes} from '../../../../../../types'
import {validateField} from '../../../../../EditPipelinePage.actions'
import {FormType} from '../../../../../slices/EditPipelinePage.slices.types'
import {useJobStepFormContext} from '../JobStepFormContext/JobStepFormContext'

import renderers from './JobStepJsonFormRenderers'
import fallbackScriptJsonSchema from './jsonFormJsonSchema/script.json'
import uiSchemas from './jsonFormUiSchema'

type JobStepJsonFormProps = {
  type: string
}

function JobStepJsonForm({type}: JobStepJsonFormProps) {
  const pipelineId = usePipelineId()
  const {stepIndex, jobId, originalIndex, step, jobRunners, onStepPropertiesChange} =
    useJobStepFormContext()
  const runnerJsonSchema = useMemo(() => {
    const jobRunner = jobRunners?.[type]?.jsonSchema

    if (!jobRunner && type === StepTypes.CLI) {
      return fallbackScriptJsonSchema
    }

    return jobRunner
  }, [jobRunners, type])
  const runnerUiSchema = uiSchemas?.[type]
  const dispatch = useAppDispatch()
  const jsonFormsChangeHandler = useCallback(
    (value: Pick<JsonFormsCore, 'data' | 'errors'>) => {
      const valueData = value.data
      const valueDataKeys = Object.keys(valueData)
      const propertiesValue = valueDataKeys.map(name => ({
        name,
        value: valueData[name],
      }))

      onStepPropertiesChange(stepIndex, propertiesValue)

      valueDataKeys.forEach(name => {
        dispatch(validateField({pipelineId, jobId, type: FormType.STEP, id: originalIndex}, name))
      })
    },
    [dispatch, jobId, onStepPropertiesChange, originalIndex, pipelineId, stepIndex],
  )

  return (
    <JsonForms
      schema={runnerJsonSchema}
      uischema={runnerUiSchema}
      data={step}
      renderers={renderers}
      onChange={jsonFormsChangeHandler}
    />
  )
}

export default JobStepJsonForm
