import {resolveRelative} from '@jetbrains/teamcity-ui/dist/utils'
import {useNavigate} from 'react-router'

import type {pipelineParentProjectFragment$key} from '../../../../hooks/__generated__/pipelineParentProjectFragment.graphql'
import {usePipelineId, usePipelineParentProjectId} from '../../../../hooks/pipeline'
import useBooleanState from '../../../../hooks/useBooleanState'
import {pipelinesApi} from '../../../../services/pipelinesApi'
import {isPipelinesEnabledInExclusiveMode} from '../../../../utils/featureToggles'
import {useIsDebugRunning, usePipelineNameOrDraft} from '../../../EditPipelinePage.hooks'

import {getPipelinesHref} from 'src/routes'

export function usePipelineSettingsFooter(
  pipelineParentProjectKey: pipelineParentProjectFragment$key | null,
) {
  const id = usePipelineId()
  const name = usePipelineNameOrDraft()
  const parentProjectId = usePipelineParentProjectId(pipelineParentProjectKey)
  const navigate = useNavigate()
  const isDebugRunning = useIsDebugRunning()

  const [isDialogShown, showDialog, hideDialog] = useBooleanState()

  const [deletePipeline, {isLoading}] = pipelinesApi.endpoints.deletePipeline.useMutation()
  const handlerConfirmDeletePipelineButtonClick = () => {
    deletePipeline(id).then(() => {
      if (isPipelinesEnabledInExclusiveMode()) {
        navigate(getPipelinesHref())
      } else {
        location.href = resolveRelative('/admin/editProject.html', {projectId: parentProjectId})
      }
    })
  }

  return {
    name,
    isLoading,
    isDialogShown,
    isReadonly: isDebugRunning,
    showDialog,
    hideDialog,
    handlerConfirmDeletePipelineButtonClick,
  }
}
