import {HTTPCodesEnum} from '@jetbrains/teamcity-ui/dist/services'
import type {SerializedError} from '@reduxjs/toolkit'
import type {FetchBaseQueryError} from '@reduxjs/toolkit/query'
import type {ChangeEvent} from 'react'
import {useCallback, useEffect, useMemo, useRef, useState} from 'react'
import {shallowEqual} from 'react-redux'

import {useAppDispatch, useAppSelector} from '../../../../../../../../hooks/react-redux'
import {getCreatePipelineHref} from '../../../../../../../../routes'
import type {ProjectId} from '../../../../../../../../types'
import {branchNameDefault} from '../../../../../components/DefaultBranchSelect/DefaultBranchSelect.consts'
import {getGuessedGitProtocol} from '../../../../../components/PipelineForm/PipelineForm.utils'
import type {SelectedRepository} from '../../../../../components/RepositorySelect/RepositorySelect.types'
import type {HttpsRepositoryAuthType} from '../../../../../components/VcsAnyRepositoryAuthenticationForm/VcsAnyRepositoryAuthenticationForm.consts'
import {ProtocolVcsRepository} from '../../../../../components/VcsAnyRepositoryAuthenticationForm/VcsAnyRepositoryAuthenticationForm.consts'
import {vcsAnyGitProvider} from '../../../../../CreatePipelinePage/CreatePipelinePage.consts'
import {usePipelineId} from '../../../../../hooks/pipeline'
import usePipelineVcsProviders from '../../../../../hooks/usePipelineVcsProviders'
import type {VcsProvider, VcsRepository} from '../../../../../services/pipelinesApi.types'
import {VcsProviderType} from '../../../../../services/pipelinesApi.types'
import {getRepositoryFullName} from '../../../../../utils/vcs'
import {validateForm} from '../../../../EditPipelinePage.actions'
import {getPipelineErrors} from '../../../../EditPipelinePage.selectors'
import {FormType} from '../../../../slices/EditPipelinePage.slices.types'
import type {PipelineBaseRepository} from '../PipelineRepositories.types'

import {
  getDefaultVcsAnyRepositoryAuthType,
  getVcsRootPopupSettings,
} from './NewPipelineRepositoryForm.utils'

export function useNewPipelineRepositoryForm(
  repositoryUrl: string,
  projectId?: ProjectId,
  formId?: string | number,
  createdRepositories?: Set<string>,
  onChange?: (value: PipelineBaseRepository) => void,
  providerUsername?: string,
  providerPassword?: string,
  vcsProtocol?: ProtocolVcsRepository,
  vcsProviderType?: VcsProviderType | null,
) {
  const {vcsProviders} = usePipelineVcsProviders(projectId)
  const isProtocolManuallyChangedRef = useRef<boolean>(false)
  const pipelineId = usePipelineId()
  const dispatch = useAppDispatch()
  const repositoryFormErrors = useAppSelector(
    state =>
      getPipelineErrors(state, {
        pipelineId,
        formType: FormType.REPOSITORY,
        formId,
      }),
    shallowEqual,
  )
  const isInvalidForm = repositoryFormErrors.length
  const repositoryFormErrorMessageMap = useMemo(
    () =>
      repositoryFormErrors.reduce<Record<string, string>>((accumulator, {fieldName, message}) => {
        if (message && fieldName) {
          accumulator[fieldName] = message
        }

        return accumulator
      }, {}),
    [repositoryFormErrors],
  )
  const [anyVcsRepositoryUrl, setAnyVcsRepositoryUrl] = useState<string | undefined>(repositoryUrl)
  const [isAnyVcsProviderVerified, setIsAnyVcsProviderVerified] = useState<boolean>(!!repositoryUrl)
  const defaultVcsAnyRepositoryAuthType = getDefaultVcsAnyRepositoryAuthType(
    providerUsername,
    providerPassword,
  )
  const [vcsAnyRepositoryAuthType, setVcsAnyRepositoryAuthType] = useState<HttpsRepositoryAuthType>(
    defaultVcsAnyRepositoryAuthType,
  )
  const [vcsProtocolRepositoryAuthType, setVcsProtocolRepositoryAuthType] =
    useState<ProtocolVcsRepository>(vcsProtocol ?? ProtocolVcsRepository.SSH)
  const isAnyVcsUrlRepositoryAlreadyExists =
    anyVcsRepositoryUrl &&
    createdRepositories?.has(anyVcsRepositoryUrl) &&
    !isAnyVcsProviderVerified &&
    repositoryUrl !== anyVcsRepositoryUrl
  const selectedProvider = useMemo(() => {
    const vcsProvider = vcsProviders?.find(vcsProvider => vcsProvider?.type === vcsProviderType)
    const defaultVcsGitProvider = {
      ...vcsAnyGitProvider,
      username: providerUsername,
      password: providerPassword,
    }

    return vcsProvider ?? defaultVcsGitProvider
  }, [vcsProviders, providerUsername, providerPassword, vcsProviderType])
  const errorAnyVcsRepositoryNameErrorMessage = isAnyVcsUrlRepositoryAlreadyExists
    ? 'Repository already exists'
    : undefined
  const isVcsProviderTypeAny =
    selectedProvider?.type == null || selectedProvider?.type === VcsProviderType.ANY
  const isShowVcsAnyRepositoryAuthenticationForm = isVcsProviderTypeAny && !isAnyVcsProviderVerified
  const [repoDefaultBranch, setRepoDefaultBranch] = useState<string | null>(null)
  const selectedRepository = useMemo(
    () =>
      repositoryUrl && repositoryUrl.length > 0
        ? {
            url: repositoryUrl,
            name: isVcsProviderTypeAny ? repositoryUrl : getRepositoryFullName(repositoryUrl),
            defaultBranch: repoDefaultBranch,
          }
        : null,
    [repositoryUrl, isVcsProviderTypeAny, repoDefaultBranch],
  )
  const handleSelectRepository = useCallback(
    (selected: SelectedRepository | null) => {
      if (selected != null) {
        onChange?.({
          url: selected.url,
          branch: selected.defaultBranch ?? branchNameDefault,
        })
        setRepoDefaultBranch(selected.defaultBranch ?? null)
        return
      }
      onChange?.({url: ''})
    },
    [onChange],
  )
  const [hasError, setHasError] = useState<boolean>(false)
  const onError = useCallback((error: FetchBaseQueryError | SerializedError | null) => {
    if (
      error != null &&
      'status' in error &&
      ((error.status === HTTPCodesEnum.NOT_FOUND &&
        'data' in error &&
        typeof error.data === 'string' &&
        (error.data.includes('No user tokens found') || error.data.includes('Bad credentials'))) ||
        error.status === HTTPCodesEnum.INTERNAL_SERVER_ERROR)
    ) {
      setHasError(true)
    }
  }, [])
  const onVcsLogin = useCallback(() => {
    setHasError(false)
  }, [])
  const repositoryNameInputChangeHandler = ({
    currentTarget,
  }: React.ChangeEvent<HTMLInputElement>) => {
    const {value} = currentTarget
    setAnyVcsRepositoryUrl(value)
    setIsAnyVcsProviderVerified(false)
  }
  const vcsAnyRepositoryAuthenticationFormChangeAuthTypeHandler = (
    value: HttpsRepositoryAuthType,
  ) => setVcsAnyRepositoryAuthType(value)
  const vcsProtocolRepositoryAuthenticationFormChangeHandler = (value: ProtocolVcsRepository) => {
    setVcsProtocolRepositoryAuthType(value)

    isProtocolManuallyChangedRef.current = true
  }
  const vcsProviderVerifiedLabelButtonClickHandler = () => setIsAnyVcsProviderVerified(false)
  const vcsAnyRepositoryAuthenticationFormSubmitHandler = (
    isPrivate: boolean,
    username?: string,
    password?: string,
  ) => {
    const isSshProtocol = vcsProtocolRepositoryAuthType === ProtocolVcsRepository.SSH
    const vcsAuthCredentials = isSshProtocol
      ? {
          sshKey: {
            name: username ?? '',
            passphrase: password,
          },
        }
      : {username, password}
    onChange?.({
      url: anyVcsRepositoryUrl,
      isPrivate,
      ...vcsAuthCredentials,
    })
    setIsAnyVcsProviderVerified(true)
  }
  const filterRepositories = useCallback(
    (repos: VcsRepository[]) =>
      repos.filter(
        repo => repo.htmlUrl === repositoryUrl || !createdRepositories?.has(repo.htmlUrl),
      ),
    [createdRepositories, repositoryUrl],
  )
  const handleSelectProvider = useCallback(
    (selected: VcsProvider) => {
      if (selected.type === VcsProviderType.NEW_CONNECTION && projectId) {
        const windowSettings = getVcsRootPopupSettings()
        const href = `${getCreatePipelineHref(projectId)}&mode=loginScreen&openedPalce=edit`

        window.open(href, '_blank', windowSettings)

        onChange?.({
          vcsProviderType: undefined,
        })

        window.addEventListener(
          'message',
          ({data}) => {
            const isDataString = typeof data === 'string'

            if (isDataString) {
              try {
                const vcsProvider: {event?: string; type?: VcsProviderType} = JSON.parse(data)

                if (vcsProvider?.event === 'VCS_CONNECTION_CREATED' && vcsProvider?.type) {
                  onChange?.({
                    vcsProviderType: vcsProvider.type,
                  })
                }
              } catch (error) {
                // eslint-disable-next-line no-console
                console.error(error)
              }
            }
          },
          false,
        )
      } else {
        onChange?.({
          connectionId: selected.connectionId,
          vcsProviderType: selected.type,
          isStatusPublishingEnabled: selected.connectionId != null,
        })

        setIsAnyVcsProviderVerified(false)
        setAnyVcsRepositoryUrl(undefined)

        isProtocolManuallyChangedRef.current = false

        if (selected !== selectedProvider) {
          handleSelectRepository(null)
        }
      }
    },
    [projectId, onChange, selectedProvider, handleSelectRepository],
  )
  const handleSelectBranch = useCallback(
    (selected: string) => onChange?.({branch: selected}),
    [onChange],
  )
  const handleSelectBranchSpec = useCallback(
    (selected: string) => onChange?.({branchSpecification: selected}),
    [onChange],
  )
  const handleTogglePublishStatus = useCallback(
    ({currentTarget}: ChangeEvent<HTMLInputElement>) => {
      onChange?.({isStatusPublishingEnabled: currentTarget.checked})
    },
    [onChange],
  )
  const handleTogglePullRequests = useCallback(
    (value: boolean) => {
      onChange?.({trackPullRequests: value})
      dispatch(validateForm({pipelineId, type: FormType.REPOSITORIES}))
      if (value) {
        dispatch(validateForm({pipelineId, type: FormType.TRIGGER}))
      }
    },
    [dispatch, onChange, pipelineId],
  )
  const selectExistingVcsRootHandler = useCallback(
    (vcsRootId: string | null, name?: string) => {
      if (vcsRootId) {
        onChange?.({
          name,
          id: vcsRootId,
          isExternal: true,
          url: name,
        })
      }
    },
    [onChange],
  )

  useEffect(() => {
    setHasError(false)
  }, [selectedProvider])

  useEffect(() => {
    if (isShowVcsAnyRepositoryAuthenticationForm) {
      const guessedProtocol = getGuessedGitProtocol(anyVcsRepositoryUrl)

      if (guessedProtocol && !isProtocolManuallyChangedRef.current) {
        setVcsProtocolRepositoryAuthType(guessedProtocol)
      }
    }
  }, [isShowVcsAnyRepositoryAuthenticationForm, anyVcsRepositoryUrl])

  return {
    isInvalidForm,
    vcsProviders,
    selectedProvider,
    handleSelectProvider,
    selectedRepository,
    handleSelectRepository,
    handleSelectBranch,
    handleSelectBranchSpec,
    handleTogglePublishStatus,
    handleTogglePullRequests,
    repoDefaultBranch,
    filterRepositories,
    onVcsLogin,
    hasError,
    onError,
    isVcsProviderTypeAny,
    isAnyVcsProviderVerified,
    isShowVcsAnyRepositoryAuthenticationForm,
    vcsAnyRepositoryAuthType,
    errorAnyVcsRepositoryNameErrorMessage,
    isAnyVcsUrlRepositoryAlreadyExists,
    anyVcsRepositoryUrl,
    repositoryFormErrorMessageMap,
    vcsProtocolRepositoryAuthType,
    selectExistingVcsRootHandler,
    repositoryNameInputChangeHandler,
    vcsProtocolRepositoryAuthenticationFormChangeHandler,
    vcsAnyRepositoryAuthenticationFormChangeAuthTypeHandler,
    vcsProviderVerifiedLabelButtonClickHandler,
    vcsAnyRepositoryAuthenticationFormSubmitHandler,
  }
}
