import {useContext, createContext, memo} from 'react'

import useStoredSettingsValueProvider from './StoredSettingsValueContext.hooks'
import type {
  StoredSettingsValueProviderProps,
  StoredSettingsValueContextProps,
} from './StoredSettingsValueContext.types'

const StoredSettingsValueContext = createContext<StoredSettingsValueContextProps>(
  {} as StoredSettingsValueContextProps,
)

function StoredSettingsValueProvider({children}: StoredSettingsValueProviderProps) {
  const {storeValue} = useStoredSettingsValueProvider()

  return (
    <StoredSettingsValueContext.Provider value={storeValue}>
      {children}
    </StoredSettingsValueContext.Provider>
  )
}

export default memo(StoredSettingsValueProvider)

export const useStoredSettingsValue = (): StoredSettingsValueContextProps =>
  useContext(StoredSettingsValueContext)
