import {memo} from 'react'

import SettingsBlock from '../../../../components/SettingsBlock/SettingsBlock'

import PipelineSecretsSettingsBlockSummaryDetails from './PipelineSecretsSettingsBlockSummaryDetails/PipelineSecretsSettingsBlockSummaryDetails'
import usePipelineSecrets from './usePipelineSecrets'

export const secretsSettingsBlockId = 'secrets'

function PipelineSecrets() {
  const {
    settingsBlockCollapsedNote,
    listItemLimit,
    pipelineSecretsKeys,
    pipelineDeletedSecrets,
    isSettingsBlockCollapsible,
    isBlockExpanded,
    isShowMoreButton,
    settingsBlockTitle,
    pipelineSecretsFormErrorMessage,
    clickEditSecretsHandler,
    clickShowMoreButtonHandler,
  } = usePipelineSecrets()

  return (
    <SettingsBlock
      id={secretsSettingsBlockId}
      collapsible={isSettingsBlockCollapsible}
      title={settingsBlockTitle}
      details={
        'Parameters whose actual values are stored securely by TeamCity and hidden away from web UI, logs, YAML configurations, and other locations'
      }
      collapsedNote={settingsBlockCollapsedNote}
      onAddClick={!isSettingsBlockCollapsible ? clickEditSecretsHandler : undefined}
    >
      <PipelineSecretsSettingsBlockSummaryDetails
        secretsKeys={pipelineSecretsKeys}
        deleted={pipelineDeletedSecrets}
        error={pipelineSecretsFormErrorMessage}
        isBlockExpanded={isBlockExpanded}
        isShowMoreButton={isShowMoreButton}
        onClickShowMore={clickShowMoreButtonHandler}
        listItemLimit={listItemLimit}
        onEdit={clickEditSecretsHandler}
      />
    </SettingsBlock>
  )
}

export default memo(PipelineSecrets)
