import closeIcon from '@jetbrains/icons/close'
import warningIcon from '@jetbrains/icons/warning'
import Button from '@jetbrains/ring-ui-built/components/button/button'
import ButtonGroup from '@jetbrains/ring-ui-built/components/button-group/button-group'
import Icon from '@jetbrains/ring-ui-built/components/icon/icon'
import {Size} from '@jetbrains/ring-ui-built/components/input/input'
import Tooltip from '@jetbrains/ring-ui-built/components/tooltip/tooltip'
import type {ChangeEvent} from 'react'
import {useCallback} from 'react'
import {graphql, useFragment} from 'react-relay'

import {useAppDispatch, useAppSelector} from '../../../../../hooks/react-redux'
import {useSetUserProperty} from '../../../../../hooks/useSetUserProperty'
import {useBooleanUserProperty} from '../../../../../hooks/useUserProperty'
import {UserProperties} from '../../../../../utils/userProperties'
import type {VersionedSettingsDto} from '../../services/pipelinesApi.types'
import Input from '../Input'

import type {ConfigurationStorageSwitchFragment$key} from './__generated__/ConfigurationStorageSwitchFragment.graphql'
import {useCanEditVersionedSettings, useIsGitRepository} from './ConfigurationStorage.hooks'
import {pipelinesVsWarningBannerDismissed} from './ConfigurationStorage.slices'

import styles from './ConfigurationStorageSwitch.module.css'

const DEFAULT_FILENAME = '.teamcity.yml'

const pipelineFragment = graphql`
  fragment ConfigurationStorageSwitchFragment on PipelineRest {
    ...ConfigurationStorageCanEditFragment
    parentProject {
      name
    }
  }
`

type Props = {
  storedInRepo?: boolean
  className?: string
  changeStorageHandler: (settings: VersionedSettingsDto) => void
  pipelineKey: ConfigurationStorageSwitchFragment$key | null
}

export const vcsStorageSwitchLabel = {
  storedInRepo: 'in VCS repository',
  storedOnServer: 'on TeamCity server',
}

function ConfigurationStorageSwitch({
  storedInRepo = false,
  className,
  changeStorageHandler,
  pipelineKey,
}: Props) {
  const pipeline = useFragment(pipelineFragment, pipelineKey)
  const canEditVersionedSettings = useCanEditVersionedSettings(pipeline)
  const warningBannerDismissedFromStore = useAppSelector(
    state => state.pipelinesVsWarningBannerDismissed,
  )
  const warningBannerDismissedFromProperty = useBooleanUserProperty(
    UserProperties.PIPELINES_VS_WARNING_BANNER_DISMISSED,
  )
  const warningBannerDismissed =
    warningBannerDismissedFromStore || warningBannerDismissedFromProperty
  const dispatch = useAppDispatch()
  const setUserProperty = useSetUserProperty()
  const dismissWarningBanner = useCallback(() => {
    dispatch(pipelinesVsWarningBannerDismissed.actions.dismiss())
    setUserProperty(UserProperties.PIPELINES_VS_WARNING_BANNER_DISMISSED, 'true')
  }, [dispatch, setUserProperty])
  const handleFilenameChange = useCallback(
    ({currentTarget: {value}}: ChangeEvent<HTMLInputElement>) => {
      changeStorageHandler({filename: value})
    },
    [changeStorageHandler],
  )
  const isGitRepository = useIsGitRepository()
  const canEdit = canEditVersionedSettings && isGitRepository
  const tooltipTitle = !isGitRepository
    ? 'Pipelines currently support storing configuration files only in Git repositories'
    : `You need a permission to enable / disable versioned settings in the "${pipeline?.parentProject?.name}" project`

  const switcher = (
    <ButtonGroup className={styles.toggle}>
      <Button
        disabled={!canEdit}
        className={styles.item}
        active={storedInRepo}
        onClick={() => {
          changeStorageHandler({storedInRepo: true})
        }}
      >
        {vcsStorageSwitchLabel.storedInRepo}
      </Button>
      <Button
        disabled={!canEdit}
        className={styles.item}
        active={!storedInRepo}
        onClick={() => changeStorageHandler({storedInRepo: false})}
      >
        {vcsStorageSwitchLabel.storedOnServer}
      </Button>
    </ButtonGroup>
  )

  return (
    <div className={className}>
      <div className={styles.label}>{'Store the configuration YAML file:'}</div>
      {!warningBannerDismissed && (
        <div className={styles.warningBanner}>
          <Icon className={styles.warningIcon} glyph={warningIcon} />
          <div>
            {
              'If a parent project uses versioned settings, its Kotlin/XML files do not include pipeline configurations. Pipelines generate a separate YAML file that can be stored independently.'
            }
          </div>
          <Button aria-label="Dismiss" icon={closeIcon} onClick={dismissWarningBanner} />
        </div>
      )}
      {canEdit ? (
        switcher
      ) : (
        <Tooltip title={tooltipTitle} popupProps={{offset: 4}}>
          {switcher}
        </Tooltip>
      )}
      {storedInRepo && (
        <Input
          disabled
          size={Size.FULL}
          className={styles.input}
          label={'YAML file name and path'}
          value={DEFAULT_FILENAME}
          onChange={handleFilenameChange}
        />
      )}
    </div>
  )
}

export default ConfigurationStorageSwitch
