import {useCallback, useMemo} from 'react'
import {useSearchParams} from 'react-router'

import {useAppDispatch, useAppSelector} from '../../../../../../../../hooks/react-redux'
import {usePipelineId} from '../../../../../hooks/pipeline'
import {VcsProviderType} from '../../../../../services/pipelinesApi.types'
import {isPullRequestsFeatureEnabled} from '../../../../../utils/featureToggles'
import {validateForm} from '../../../../EditPipelinePage.actions'
import {getPipelineErrorMessage, isPipelineFormAdd} from '../../../../EditPipelinePage.selectors'
import {
  pipelineDraft,
  pipelineErrors,
  pipelineForm,
} from '../../../../slices/EditPipelinePage.slices'
import {FormType} from '../../../../slices/EditPipelinePage.slices.types'
import type {PipelineBaseRepository} from '../PipelineRepositories.types'
import {getRepositoryName} from '../PipelineRepositories.utils'

import {getBranchesToMonitor, getRepositoryKey} from './PipelineRepository.utils'

function usePipelineRepository(
  repositoryUrl = '',
  branch = '',
  branchSpec: string | null = '',
  isDeleted = false,
  isRoot = false,
  index?: number,
  onDelete?: () => void,
  vcsProviderType?: VcsProviderType | null,
  trackPullRequests?: boolean,
) {
  const pipelineId = usePipelineId()
  const formId = getRepositoryKey(isRoot, index)
  const formParams = useMemo(
    () => ({pipelineId, type: FormType.REPOSITORY, id: formId}),
    [formId, pipelineId],
  )
  const isAdd = useAppSelector(state => isPipelineFormAdd(state, formParams))
  const [searchParams, setSearchParams] = useSearchParams()
  const searchParamsObject = Object.fromEntries(searchParams.entries())
  const dispatch = useAppDispatch()
  const toggleNavigationRepositoryParamHandler = useCallback(
    (open: boolean) => {
      const {repository, ...newSearchParamsObject} = searchParamsObject

      if (open) {
        setSearchParams({...newSearchParamsObject, repository: `${formId}`})
      } else {
        setSearchParams(newSearchParamsObject)
      }
    },
    [formId, searchParamsObject, setSearchParams],
  )
  const onChange = useCallback(
    (vcsRoot: PipelineBaseRepository) => {
      const prevState = {
        pipelineId,
        branch,
        url: repositoryUrl,
      }

      if (isRoot) {
        dispatch(pipelineDraft.actions.updateMainVcsRoot({...prevState, ...vcsRoot}))
      } else {
        dispatch(
          pipelineDraft.actions.updateAdditionalVcsRoot({
            index: index!,
            ...prevState,
            ...vcsRoot,
          }),
        )
      }

      dispatch(
        pipelineErrors.actions.clear({
          pipelineId,
          formType: FormType.REPOSITORY,
          formId: getRepositoryKey(false, index),
        }),
      )
    },
    [branch, dispatch, index, isRoot, pipelineId, repositoryUrl],
  )
  const onConfirm = () => {
    const isValid = dispatch(validateForm(formParams))

    if (isValid) {
      dispatch(pipelineForm.actions.close(formParams))
      toggleNavigationRepositoryParamHandler(false)
    }
  }
  const pullRequestsLabel = trackPullRequests
    ? ' including Pull requests'
    : ' excluding Pull requests'
  const branchSpecLabel = `Branches to monitor: ${getBranchesToMonitor(branchSpec ?? '', branch)}${isPullRequestsFeatureEnabled ? pullRequestsLabel : ''}`
  const deleteRepositoryHandler = () => {
    dispatch(pipelineForm.actions.close(formParams))
    toggleNavigationRepositoryParamHandler(false)
    onDelete?.()
  }
  const toggleEditModeHandler = useCallback(
    (state: boolean) => () => {
      if (!isDeleted) {
        const pipelineFormAction = state ? 'open' : 'close'

        toggleNavigationRepositoryParamHandler(state)

        dispatch(pipelineForm.actions[pipelineFormAction](formParams))
      }
    },
    [dispatch, formParams, isDeleted, toggleNavigationRepositoryParamHandler],
  )
  const cancelRepositoryFormHandler = () => {
    dispatch(validateForm(formParams))

    if (isAdd) {
      deleteRepositoryHandler()
    } else {
      dispatch(pipelineForm.actions.close(formParams))
      toggleNavigationRepositoryParamHandler(false)
    }
  }
  const repositoryFormErrorMessage = useAppSelector(
    getPipelineErrorMessage({
      pipelineId,
      formType: FormType.REPOSITORY,
      formId,
    }),
  )
  const canDeletable = onDelete && !isDeleted
  const canEditable = !isDeleted
  const canRestore = !isRoot && isDeleted
  const repositoryName =
    !vcsProviderType || vcsProviderType === VcsProviderType.ANY
      ? repositoryUrl
      : getRepositoryName(repositoryUrl)
  const deleteRepositoryFormHandler = !isRoot ? deleteRepositoryHandler : undefined

  return {
    isAdd,
    deleteRepositoryFormHandler,
    repositoryName,
    canEditable,
    canDeletable,
    canRestore,
    branchSpecLabel,
    onChange,
    formId,
    repositoryFormErrorMessage,
    cancelRepositoryFormHandler,
    onConfirm,
    deleteRepositoryHandler,
    toggleEditModeHandler,
  }
}

export default usePipelineRepository
