import {useCallback, useMemo} from 'react'
import {shallowEqual} from 'react-redux'

import {useAppDispatch, useAppSelector} from '../../../../../../../hooks/react-redux'
import {getEmptyHash} from '../../../../../../../utils/empty'
import {usePipelineId} from '../../../../hooks/pipeline'
import {getDraft, getPipeline, getPipelineErrorMessage} from '../../../EditPipelinePage.selectors'
import {
  pipelineDraft,
  pipelineErrors,
  pipelineSecrets as pipelineSecretsSlice,
} from '../../../slices/EditPipelinePage.slices'
import {FormType} from '../../../slices/EditPipelinePage.slices.types'

function usePipelineSecretsStore() {
  const dispatch = useAppDispatch()
  const pipelineId = usePipelineId()
  const formErrorSpotId = useMemo(
    () => ({
      pipelineId,
      formType: FormType.SECRET,
    }),
    [pipelineId],
  )
  const pipelineSecrets: Record<string, string | undefined> = useAppSelector(
    state => getDraft(state, pipelineId)?.settings.secrets ?? getEmptyHash(),
  )
  const pipelineSecretsKeys = useMemo(() => Object.keys(pipelineSecrets), [pipelineSecrets])
  const pipelineSecretsKeysLength = pipelineSecretsKeys.length
  const pipelineAddedSecrets = useAppSelector(
    state => getPipeline(state, pipelineId)?.added?.secrets ?? getEmptyHash(),
  )
  const pipelineRenamedSecrets = (useAppSelector(
    state => getPipeline(state, pipelineId)?.renamed?.secrets,
  ) ?? getEmptyHash()) as Record<string, string>
  const pipelineDeletedSecrets = useAppSelector(
    state => getPipeline(state, pipelineId)?.deleted?.secrets,
    shallowEqual,
  )
  const pipelineSecretsLength = pipelineSecretsKeys.filter(
    key => !pipelineDeletedSecrets?.includes(key),
  ).length
  const addSecretHandler = () => dispatch(pipelineDraft.actions.addSecret(pipelineId))
  const pipelineSecretsFormErrorMessage = useAppSelector(getPipelineErrorMessage(formErrorSpotId))
  const clearAddedSecretsHandler = useCallback(() => {
    Object.keys(pipelineSecrets).forEach(key => {
      dispatch(
        pipelineErrors.actions.clear({
          ...formErrorSpotId,
          formId: key,
        }),
      )
      dispatch(pipelineSecretsSlice.actions.unset({pipelineId, savedName: key}))
    })
    dispatch(pipelineDraft.actions.clearAddedSecrets(pipelineId))
  }, [dispatch, formErrorSpotId, pipelineId, pipelineSecrets])

  return {
    pipelineSecrets,
    pipelineSecretsLength,
    pipelineSecretsKeys,
    pipelineSecretsKeysLength,
    pipelineAddedSecrets,
    pipelineRenamedSecrets,
    pipelineDeletedSecrets,
    pipelineSecretsFormErrorMessage,
    addSecretHandler,
    clearAddedSecretsHandler,
  }
}

export default usePipelineSecretsStore
