import {uiTypeIs, rankWith} from '@jsonforms/core'
import type {ControlProps, RankedTester} from '@jsonforms/core'
import {withJsonFormsControlProps} from '@jsonforms/react'
import cn from 'classnames'
import {Suspense, useCallback} from 'react'

import JobDirectoryPopup from '../../../../../JobDirectory/JobDirectoryPopup'
import type {JobDirectoryType} from '../../../../../JobDirectory/JobDirectoryTree/JobDirectoryTree.types'
import {useJobStepFormContext} from '../../../JobStepFormContext/JobStepFormContext'
import styles from '../styles.module.css'

import JsonFormInputControl from './JsonFormInputControl/JsonFormInputControl'

function JsonFormInputPathControl(props: ControlProps) {
  const {visible, path, handleChange} = props
  const {pipelineHeadBuildTypeKey, jobId} = useJobStepFormContext()
  const directoryPopupSelectHandler = useCallback(
    (_: JobDirectoryType, value: string) => handleChange(path, value.slice(1)),
    [handleChange, path],
  )

  if (!visible) {
    return null
  }

  return (
    <div className={cn(styles.inputContainer, styles.container)}>
      <JsonFormInputControl {...props} />
      <Suspense>
        <JobDirectoryPopup
          jobId={jobId}
          pipelineHeadBuildTypeKey={pipelineHeadBuildTypeKey}
          onlyDirectories
          onSelect={directoryPopupSelectHandler}
          buttonClass={styles.inputContainerPathIcons}
        />
      </Suspense>
    </div>
  )
}

export const jsonFormInputPathControlTester: RankedTester = rankWith(
  1,
  uiTypeIs('InputPathControl'),
)

export default withJsonFormsControlProps(JsonFormInputPathControl)
