import type {ControlProps} from '@jsonforms/core'
import classNames from 'classnames'
import {useCallback, useContext, useEffect, useMemo, useRef} from 'react'
import * as React from 'react'

import HighlighterTextField from '../../../../../../../../../components/HighlighterTextField/HighlighterTextField'
import HighlighterTextInput from '../../../../../../../../../components/HighlighterTextField/HighlighterTextInput'
import {DisabledContext} from '../../../../../../../../../contexts/DisabledContext'
import {useDraftStepError} from '../../../../../../../../EditPipelinePage.hooks'
import {useJobStepFormContext} from '../../../../JobStepFormContext/JobStepFormContext'
import JsonFormHelpDetailsIcon from '../JsonFormHelpDetailsIcon'

import {useJobStepFormInputControlContext} from './JsonFormInputControlControlProvider'

import styles from './JsonFormInputControl.module.css'

export type JsonFormTextControlProps = ControlProps

function JsonFormInputControl(props: JsonFormTextControlProps) {
  const {
    id,
    handleChange,
    path: name,
    description,
    errors,
    uischema,
    label,
    visible,
    required,
    enabled,
    data,
  } = props
  const {stepIndex} = useJobStepFormContext()
  const errorMessage = useDraftStepError({
    name,
    stepIndex,
  })
  const highlighterTextFieldRef = useRef<HTMLTextAreaElement | HTMLInputElement | null>(null)
  const {placeholder, multi, focus} = uischema.options ?? {}
  const {onInitRef, onBlur, onFocus} = useJobStepFormInputControlContext()
  const error = (errors ? errors : undefined) || errorMessage
  const value = data != null ? data : ''
  const isDisabled = useContext(DisabledContext)
  const disabled = isDisabled || !enabled
  const inputChangeHandler = useCallback(
    ({target}: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) =>
      handleChange(name, target.value),
    [handleChange, name],
  )
  const inputLabel = useMemo(
    () => (
      <React.Fragment>
        {label}
        {description && <JsonFormHelpDetailsIcon>{description}</JsonFormHelpDetailsIcon>}
      </React.Fragment>
    ),
    [description, label],
  )
  const elementClassNames = classNames(styles.input, {
    [styles.multiline]: multi,
    [styles.monospace]: multi,
  })

  useEffect(() => {
    const highlighterTextFieldRefCurrent = highlighterTextFieldRef.current

    if (highlighterTextFieldRefCurrent) {
      onInitRef?.(highlighterTextFieldRefCurrent)
    }
  }, [onInitRef])

  if (!visible) {
    return null
  }

  if (multi) {
    return (
      <HighlighterTextField
        data-test="highlighter-text-field"
        autoComplete="off"
        ref={highlighterTextFieldRef as never}
        onChange={inputChangeHandler}
        value={value ?? ''}
        className={elementClassNames}
        placeholder={placeholder}
        label={inputLabel}
        autoFocus={focus}
        multiline
        onFocus={onFocus}
        onBlur={onBlur}
        error={error}
        spellCheck={false}
        aria-label={label}
        required={required}
        disabled={disabled}
      />
    )
  }

  return (
    <HighlighterTextInput
      ref={highlighterTextFieldRef as never}
      data-test="highlighter-text-field"
      className={elementClassNames}
      id={id}
      value={value}
      name={id}
      label={inputLabel}
      spellCheck={false}
      aria-label={label}
      required={required}
      disabled={disabled}
      error={error}
      onChange={inputChangeHandler}
      placeholder={placeholder}
      autoComplete="off"
    />
  )
}

export default JsonFormInputControl
