import {useCallback} from 'react'
import {useSearchParams} from 'react-router'

import {useAppDispatch, useAppSelector} from '../../../../../../../hooks/react-redux'
import {usePipelineId} from '../../../../hooks/pipeline'
import type {NotificationDto} from '../../../../services/pipelinesApi.types'
import {getDraft} from '../../../EditPipelinePage.selectors'
import {pipelineDraft} from '../../../slices/EditPipelinePage.slices'

import {DEFAULT_BRANCH} from './NotificationEditor.consts'
import {DEFAULT_EVENTS} from './PipelineNotifications.const'

export const usePipelineNotifications = () => {
  const pipelineId = usePipelineId()
  const notifications = useAppSelector(state => getDraft(state, pipelineId)?.notifications) ?? []
  const settingsBlockId = 'pipeline-notifications'
  const [searchParams, setSearchParams] = useSearchParams()
  const searchParamsObject = Object.fromEntries(searchParams.entries())
  const dispatch = useAppDispatch()

  const editNotification = useCallback(
    (id: string) => {
      setSearchParams({
        ...searchParamsObject,
        notification: id,
      })
    },
    [searchParamsObject, setSearchParams],
  )

  const addNotification = useCallback(() => {
    const id = notifications.length.toString()
    setSearchParams({
      ...searchParamsObject,
      notification: id.toString(),
    })
    const notificationDto: NotificationDto = {
      type: 'email',
      enabled: true,
      branchSpecification: DEFAULT_BRANCH,
      events: DEFAULT_EVENTS,
      emails: [],
      users: [],
    }
    dispatch(pipelineDraft.actions.addNotification({id: pipelineId, notification: notificationDto}))
  }, [notifications.length, setSearchParams, searchParamsObject, dispatch, pipelineId])

  const cloneNotification = useCallback(
    (notification: NotificationDto) => {
      const id = notifications.length.toString()
      setSearchParams({
        ...searchParamsObject,
        notification: id.toString(),
      })
      const notificationDto: NotificationDto = {
        type: notification.type,
        enabled: notification.enabled,
        branchSpecification: notification.branchSpecification,
        emails: notification.emails,
        users: notification.users,
        events: notification.events,
      }
      dispatch(
        pipelineDraft.actions.addNotification({id: pipelineId, notification: notificationDto}),
      )
    },
    [notifications.length, setSearchParams, searchParamsObject, dispatch, pipelineId],
  )

  const deleteNotification = useCallback(
    (notificationId: string) => {
      dispatch(pipelineDraft.actions.deleteNotification({id: pipelineId, notificationId}))
    },
    [dispatch, pipelineId],
  )

  const restoreNotification = useCallback(
    (notificationId: string) => {
      dispatch(pipelineDraft.actions.restoreNotification({id: pipelineId, notificationId}))
    },
    [dispatch, pipelineId],
  )

  const deletedNotifications = useAppSelector(
    state => state.pipelines.pipelineDraft[pipelineId]?.deleted?.notifications,
  )

  const onNotificationEnabledChange = useCallback(
    (notificationId: string, notification: NotificationDto, enabled: boolean) => {
      if (notification.id !== undefined) {
        dispatch(
          pipelineDraft.actions.updateNotification({
            id: pipelineId,
            notificationId,
            notificationData: {
              ...notification,
              enabled,
            },
          }),
        )
      }
    },
    [dispatch, pipelineId],
  )

  return {
    notifications,
    settingsBlockId,
    addNotification,
    cloneNotification,
    deleteNotification,
    restoreNotification,
    editNotification,
    onNotificationEnabledChange,
    deletedNotifications,
  }
}
