import type {SelectItem} from '@jetbrains/ring-ui-built/components/select/select'
import {useMemo} from 'react'

import {pipelinesApi} from '../../services/pipelinesApi'

const jdkSelectOptionDefault: SelectItem = {
  key: '%JAVA_HOME%',
  label: 'Default',
  description: '%JAVA_HOME%',
}

const jdkSelectOptionCustom: SelectItem = {
  key: 'custom',
  label: 'Custom',
}

function useJavaVersionPicker(onChange: (value: string | null) => void, value?: string) {
  const {providerJdk, isLoadingProviderJdk} =
    pipelinesApi.endpoints.getPipelineProviderJdk.useQuery(undefined, {
      selectFromResult: ({data, isLoading, isFetching}) => ({
        providerJdk: data ?? [],
        isLoadingProviderJdk: isLoading || isFetching,
      }),
    })
  const jdkSelectOptions = useMemo(() => {
    const options = providerJdk.map(({displayName, parameterReference}) => ({
      key: parameterReference,
      label: displayName,
    }))

    return [jdkSelectOptionDefault, jdkSelectOptionCustom, ...options]
  }, [providerJdk])
  const selectedOption = useMemo(() => {
    const selectedOption = jdkSelectOptions.find(({key}) => key === value)
    const isCustom = !selectedOption && typeof value === 'string'

    if (selectedOption) {
      return selectedOption
    }

    if (isCustom) {
      return jdkSelectOptionCustom
    }

    return jdkSelectOptionDefault
  }, [jdkSelectOptions, value])
  const selectChangeHandler = (selectedItem: SelectItem | null) => {
    const isCustom = selectedItem?.key === jdkSelectOptionCustom.key
    const isDefault = selectedItem?.key === jdkSelectOptionDefault.key
    let newValue: string | null = selectedItem?.key.toString() ?? ''

    if (isDefault) {
      newValue = null
    } else if (isCustom) {
      newValue = ''
    }

    onChange(newValue)
  }
  const inputChangeHandler = ({target}: React.ChangeEvent<HTMLInputElement>) =>
    onChange(target.value)
  const isCustomSelected = selectedOption?.key === jdkSelectOptionCustom.key

  return {
    jdkSelectOptions,
    selectedOption,
    isCustomSelected,
    isLoadingProviderJdk,
    selectChangeHandler,
    inputChangeHandler,
  }
}

export default useJavaVersionPicker
