import {useCallback, useEffect, useState} from 'react'
import {useSearchParams} from 'react-router'

import {useAppDispatch, useAppSelector} from '../../../../../../../../hooks/react-redux'
import {usePipelineId} from '../../../../../hooks/pipeline'
import type {Event} from '../../../../../services/pipelinesApi.types'
import {getDraft} from '../../../../EditPipelinePage.selectors'
import {pipelineDraft} from '../../../../slices/EditPipelinePage.slices'
import {DEFAULT_BRANCH} from '../NotificationEditor.consts'
import {ALL_NEW_EVENTS, DEFAULT_EVENTS} from '../PipelineNotifications.const'

export const useNotificationEditorLogic = () => {
  const dispatch = useAppDispatch()
  const pipelineId = usePipelineId()
  const [searchParams, setSearchParams] = useSearchParams()

  const notificationIdParam = searchParams.get('notification')
  const notificationId = notificationIdParam ? notificationIdParam : undefined
  const notifications = useAppSelector(state => getDraft(state, pipelineId)?.notifications) || []
  const notification =
    notificationIdParam == null ? null : notifications[Number(notificationIdParam)]

  const [branchSpecification, setBranchSpecification] = useState(DEFAULT_BRANCH)
  const [isCustomEvents, setIsCustomEvents] = useState<boolean>()
  const [customEvents, setCustomEvents] = useState<Event[]>([])
  const [emails, setEmails] = useState<string[]>()

  useEffect(() => {
    if (notification) {
      setCustomEvents(
        notification?.events?.filter(event => DEFAULT_EVENTS.find(e => e.type === event.type)) ??
          [],
      )
      setEmails(notification.emails || [])
      setIsCustomEvents(!!notification.events.find(event => !event.enabled))
      setBranchSpecification(notification?.branchSpecification)
    }
  }, [notification])

  const onBack = useCallback(() => {
    searchParams.delete('notification')
    setSearchParams(Object.fromEntries(searchParams.entries()))
  }, [searchParams, setSearchParams])

  const updateNotification = useCallback(() => {
    if (notificationId !== undefined) {
      dispatch(
        pipelineDraft.actions.updateNotification({
          id: pipelineId,
          notificationId,
          notificationData: {
            ...notification,
            emails,
            events: isCustomEvents ? customEvents : ALL_NEW_EVENTS,
            branchSpecification,
          },
        }),
      )
    }
    onBack()
  }, [
    notificationId,
    onBack,
    dispatch,
    pipelineId,
    notification,
    emails,
    isCustomEvents,
    customEvents,
    branchSpecification,
  ])

  const handleEventChange = useCallback((events: Event[]) => {
    setCustomEvents(events)
  }, [])

  const handleEmailsChange = useCallback(
    (users: string[]) => {
      if (!users) {
        return
      }
      setEmails(users.filter(user => !!user))
    },
    [setEmails],
  )
  const handleSelectBranchSpec = useCallback(
    (selected: string) => {
      setBranchSpecification(selected)
    },
    [setBranchSpecification],
  )
  return {
    onBack,
    emails,
    handleEmailsChange,
    isCustomEvents,
    setIsCustomEvents,
    customEvents,
    handleEventChange,
    updateNotification,
    branchSpecification,
    handleSelectBranchSpec,
  }
}
